def t_t1_confirm_writes_decision_ref():
    """decision_refs 自動養成 T1:confirm 回寫 + 不對稱信任雙欄(by ai→_ai/human→正欄)。"""
    v = mkvault()
    write(v, "Projects/D.md", "type: project\nstatus: done")
    run(v, "decision-add", "D", "決策甲", "--decided", "2026-07-01", expect_rc=0)  # d1
    write(v, "Systems/A.md", "type: system\nstatus: done\nverified_by:\n  - \"[[Projects/D]]\"")
    write(v, "Verification/B.md", "type: verification\nstatus: pass\ndate: 2026-01-01\nplan_refs:\n  - \"[[Projects/D]]\"")
    lm = _lm(); env = lm.Env(v)
    gid = "Projects/D.md#d1"
    cid = lm.rel_cascade_create(env, gid, "Projects/D.md")
    # by ai → decision_refs_ai(抑制碰不到)
    run(v, "rel-cascade", "confirm", "A", "--cascade-id", cid, "--from", gid,
        "--edge", "verified_by", "--by", "ai", expect_rc=0)
    ta = read(v / "Systems/A.md")
    check("T1 by ai 回寫 decision_refs_ai(含引號、精確 #d1)",
          "decision_refs_ai:" in ta and '"Projects/D.md#d1"' in ta and "decision_refs:" not in ta.replace("decision_refs_ai", ""), ta)
    # by human → decision_refs(可抑制)
    run(v, "rel-cascade", "confirm", "B", "--cascade-id", cid, "--from", gid,
        "--edge", "plan_refs", "--by", "human", expect_rc=0)
    tb = read(v / "Verification/B.md")
    check("T1 by human 回寫 decision_refs(正欄)",
          "decision_refs:" in tb and '"Projects/D.md#d1"' in tb, tb)
    # prune 不回寫
    write(v, "Systems/C.md", "type: system\nstatus: done\nverified_by:\n  - \"[[Projects/D]]\"")
    run(v, "rel-cascade", "prune", "C", "--cascade-id", cid, "--from", gid,
        "--edge", "verified_by", "--by", "ai", expect_rc=0)
    check("T1 prune 不回寫(判無關=不記依賴)", "decision_refs" not in read(v / "Systems/C.md"), "")
    # 精確 dedup:同節點不同決策不誤合(link_target 會 strip #dN 的 bug 防護)
    run(v, "decision-add", "D", "決策乙", "--decided", "2026-07-02", expect_rc=0)  # d2
    env2 = lm.Env(v); gid2 = "Projects/D.md#d2"
    cid2 = lm.rel_cascade_create(env2, gid2, "Projects/D.md")
    run(v, "rel-cascade", "confirm", "A", "--cascade-id", cid2, "--from", gid2,
        "--edge", "verified_by", "--by", "ai", expect_rc=0)
    ta2 = read(v / "Systems/A.md")
    check("T1 精確 dedup:A.decision_refs_ai 同時有 #d1 和 #d2(不誤合)",
          '"Projects/D.md#d1"' in ta2 and '"Projects/D.md#d2"' in ta2, ta2)
    # 冪等:重 confirm 同一條不重複
    run(v, "rel-cascade", "confirm", "A", "--cascade-id", cid2, "--from", gid2,
        "--edge", "verified_by", "--by", "ai", expect_rc=0)
    check("T1 回寫冪等(重 confirm 不重複)", read(v / "Systems/A.md").count('"Projects/D.md#d2"') == 1, "")


def t_e3_reads_ai_field_e2_does_not():
    """不對稱信任接線:E3 firing 讀聯集(ai 也觸發)、E2 抑制只讀 decision_refs(ai 碰不到)。"""
    v = mkvault()
    write(v, "Projects/D.md",
          "type: project\nstatus: done\n"
          "decisions:\n"
          "  - content: 被翻\n    id: d1\n    decided: 2026-05-01\n    valid: false\n"
          "    superseded_by: 新\n    ended: 2026-06-10\n"
          "  - content: 別條\n    id: d2\n    decided: 2026-05-01\n    valid: true", body="# D\n")
    # E3:ai 欄指向翻案 d1 → firing 生效(放寬)
    write(v, "Verification/Vai.md",
          "type: verification\nstatus: pass\ndate: 2026-05-02\ndecision_refs_ai:\n  - \"Projects/D.md#d1\"", body="# Vai\n")
    r = run(v, "doctor")
    check("E3 firing 讀 decision_refs_ai(ai 填的也提醒)",
          "發現 1 條意圖鏈斷義" in r.stdout and "Vai" in r.stdout, r.stdout)
    # E2 抑制:A 只有 ai 欄指向「別條 d2」→ 不得抑制(ai 碰不到抑制)→ A 仍被節點級標
    write(v, "Systems/A.md",
          "type: system\nstatus: done\nupdated: 2026-06-01\nverified_by:\n  - \"[[Projects/D]]\"\n"
          "decision_refs_ai:\n  - \"Projects/D.md#d2\"", body="# A\n")
    r = run(v, "doctor")
    check("E2 抑制不讀 ai 欄:A 有 ai-ref 指別條仍被標(誤 ai-ref 抑制不了真落後邊)",
          "Systems/A.md --" in r.stdout, r.stdout)


def t_dref_codeloop_hardening():
    """code-loop r1 五修回歸:FIX2 fail-safe 選欄/FIX3 E3 去重/FIX4 拒不可序列化字元/
    FIX1 reindex --all OSError(以 code 錨)。canary 3/3 已由主 loop 記錄。"""
    v = mkvault()
    lm = _lm()
    src = open(GRAPHCTL, encoding="utf-8").read()
    # FIX1: reindex --all 內外層 except 含 OSError
    check("FIX1 reindex --all 內層含 OSError",
          "except (ValueError, RuntimeError, OSError) as e:   # [code-loop r1 A]" in src, "")
    # FIX2: fail-safe 選欄(未知 by → 不可信 ai 欄)
    write(v, "Projects/D.md", "type: project\nstatus: done")
    run(v, "decision-add", "D", "甲", "--decided", "2026-07-01", expect_rc=0)
    write(v, "Systems/A.md", "type: system\nstatus: done\nverified_by:\n  - \"[[Projects/D]]\"")
    env = lm.Env(v); gid = "Projects/D.md#d1"; cid = lm.rel_cascade_create(env, gid, "Projects/D.md")
    # 直接呼 cmd 以非 ai/human 的 by(繞 argparse choices,驗守門本身)
    env2 = lm.Env(v)
    lm.cmd_rel_cascade_write(env2, "confirm", "Systems/A.md", cid, gid, "verified_by", "robot")
    ta = read(v / "Systems/A.md")
    check("FIX2 fail-safe:未知 by=robot → 落不可信 decision_refs_ai(非可抑制正欄)",
          "decision_refs_ai:" in ta and "decision_refs:\n" not in ta, ta)
    # FIX4: 拒不可序列化字元
    try:
        lm.cmd_rel_cascade_write(lm.Env(v), "confirm", "Systems/A.md", cid, 'Projects/a"b.md#d1',
                                 "verified_by", "human")
        # from_id 驗證會先攔(格式),改直接測 helper
    except Exception:
        pass
    for bad, tag in (('Bad"Ref#d1', '雙引號'), ('Bad\\Ref#d1', '反斜線'),
                     ('Bad\rRef#d1', '裸CR'), ('Bad\nRef#d1', '換行')):
        try:
            lm._append_decision_ref(lm.Env(v), "Systems/A.md", "decision_refs", bad)
            check(f"FIX4 拒不可序列化字元({tag})", False, "未 raise")
        except ValueError as e:
            check(f"FIX4 拒不可序列化字元({tag})", "不可序列化" in str(e), str(e))
    # FIX3: E3 同 ref 兩欄不重複計
    write(v, "Projects/E.md",
          "type: project\nstatus: done\ndecisions:\n"
          "  - content: 翻\n    id: d1\n    decided: 2026-05-01\n    valid: false\n    superseded_by: x\n    ended: 2026-06-01", body="# E\n")
    write(v, "Verification/Vdup.md",
          "type: verification\nstatus: pass\ndate: 2026-05-02\n"
          "decision_refs:\n  - \"Projects/E.md#d1\"\ndecision_refs_ai:\n  - \"Projects/E.md#d1\"", body="# Vdup\n")
    r = run(v, "doctor")
    e3seg = r.stdout.split("[E3]")[1].split("[H]")[0] if "[E3]" in r.stdout else r.stdout
    check("FIX3 E3 同 ref 兩欄只計一次(去重)",
          e3seg.count("Vdup") == 1, e3seg)


def t_rel_cascade_hardening():
    """code-loop r1 六修回歸:畸形行 fold 防禦閘(MUT1)/空殼 header(CX2)/尾端換行(A3)/
    symlink 拒斥(CX1)/OSError→rc=2(B3);短寫驗證(B1)為 os.write 合約、以 code 檢查存在性錨。"""
    v = mkvault()
    write(v, "Projects/D.md", "type: project\nstatus: done")
    write(v, "Systems/A.md", "type: system\nstatus: done\nverified_by:\n  - \"[[Projects/D]]\"")
    lm = _lm(); env = lm.Env(v)
    gid = "Projects/D.md#d1"
    cid = lm.rel_cascade_create(env, gid, "Projects/D.md")
    p = v / "governance" / "rel-cascade" / (cid + ".jsonl")
    # MUT1:畸形 transition(缺 edge_type)→ fold 防禦閘 all(k) 必須跳過
    import json as _json
    with open(p, "a", encoding="utf-8") as f:
        f.write(_json.dumps({"event": "transition", "ts": "2026-07-15T00:00:00+00:00",
                             "neighbor": "Systems/A.md", "from_decision_id": gid,
                             "state": "confirmed", "by": "ai"}) + "\n")  # 無 edge_type
    _, trans = lm._ledger_read(p)
    st = lm._ledger_fold(trans)
    check("硬化 MUT1:畸形行(缺 edge_type)不進折疊", len(st) == 0 and len(trans) == 1, str(st))
    # CX2:空殼 header {"event":"header"} → 非法 header:confirm rc=2、resume rc=1
    sp = v / "governance" / "rel-cascade" / "c-20260101000000-bbbbbbbb.jsonl"
    sp.write_text('{"event": "header", "ts": "2026-01-01T00:00:00+00:00"}\n', encoding="utf-8")
    r = run(v, "rel-cascade", "confirm", "A", "--cascade-id", "c-20260101000000-bbbbbbbb",
            "--from", gid, "--edge", "verified_by", "--by", "ai")
    check("硬化 CX2:空殼 header confirm rc=2(缺 root/node=不合法)", r.returncode == 2, r.stderr)
    r = run(v, "rel-cascade", "resume", "c-20260101000000-bbbbbbbb")
    check("硬化 CX2:空殼 header resume rc=1(不可恢復,不裝成功)", r.returncode == 1, r.stderr)
    # A3:尾端換行 cascade-id → fullmatch 拒 rc=2
    r = run(v, "rel-cascade", "resume", cid + "\n")
    check("硬化 A3:尾端換行 id 被 fullmatch 拒 rc=2", r.returncode == 2, r.stderr)
    # CX1:symlink 終點 → O_NOFOLLOW 拒(OSError→dispatcher rc=2,兼證 B3)
    import os as _os
    victim = v / "victim.txt"; victim.write_text("勿附加", encoding="utf-8")
    link = v / "governance" / "rel-cascade" / "c-20260101000000-cccccccc.jsonl"
    _os.symlink(victim, link)
    # 給 symlink 檔一個合法 header 內容繞前置驗證?——symlink 指向的 victim 無 header,寫前驗證先拒;
    # 直接測 _ledger_append 對 symlink 的 O_NOFOLLOW(底層合約)
    try:
        lm._ledger_append(link, {"event": "transition", "x": 1})
        check("硬化 CX1:symlink 被 O_NOFOLLOW 拒", False, "未拒")
    except OSError:
        check("硬化 CX1:symlink 被 O_NOFOLLOW 拒(OSError)", True, "")
    check("硬化 CX1:victim 未被污染", victim.read_text(encoding="utf-8") == "勿附加", "")
    # B1 行為測試(r2 折入:取代文字錨——錨會被無害重構誤翻紅、也擋不住邏輯被搬進死碼):
    #   monkeypatch os.write 模擬 ENOSPC 短寫 → 必須 RuntimeError、不得靜默成功
    _real_write = lm.os.write
    try:
        lm.os.write = lambda fd, data: len(data) - 1
        try:
            lm._ledger_append(p, {"event": "transition", "t": 1})
            check("硬化 B1:短寫→RuntimeError(行為)", False, "未 raise")
        except RuntimeError as e:
            check("硬化 B1:短寫→RuntimeError(行為)", "短寫" in str(e), str(e))
    finally:
        lm.os.write = _real_write


# ══ M2/P0 typed-edge 反向索引 ══

def t_typed_index_contracts():
    v = mkvault()
    write(v, "Systems/A.md",
          "type: system\nstatus: done\n"
          "verified_by:\n  - \"[[Verification/V1]]\"\n  - \"[[Verification/V1]]\"\n"   # 重複→去重
          "plan_refs:\n  - \"[[Projects/P1]]\"\n"
          "related:\n  - \"[[Ghost不存在]]\"\n  - \"殘留scalar非wikilink\"")
    write(v, "Verification/V1.md", "type: verification\nstatus: pass\ndate: 2026-01-01")
    write(v, "Projects/P1.md", "type: project\nstatus: done")
    # 同名歧義:兩篇都叫 Dup,B 用無路徑 [[Dup]] 指
    write(v, "Systems/Dup.md", "type: system\nstatus: done")
    write(v, "Projects/Dup.md", "type: project\nstatus: done")
    write(v, "Systems/B.md", "type: system\nstatus: done\nrelated:\n  - \"[[Dup]]\"")
    from importlib.machinery import SourceFileLoader
    lm = SourceFileLoader("lumos_m2", GRAPHCTL).load_module()
    env = lm.Env(v)
    idx = lm.build_typed_index(env)
    rv = idx["rev"]
    check("M2 反向:V1 ← A(verified_by) 且去重成 1 筆",
          rv.get("Verification/V1.md") == [("Systems/A.md", "verified_by")], str(dict(rv)))
    check("M2 反向:P1 ← A(plan_refs)",
          rv.get("Projects/P1.md") == [("Systems/A.md", "plan_refs")], str(dict(rv)))
    check("M2 正反向對稱", idx["fwd"]["Systems/A.md"]["verified_by"] == ["Verification/V1.md"]
          and idx["fwd"]["Systems/A.md"]["plan_refs"] == ["Projects/P1.md"], str(dict(idx["fwd"])))
    check("M2 ghost 不靜默丟(標進 ghosts)",
          ("Systems/A.md", "Ghost不存在", "related") in idx["ghosts"], str(idx["ghosts"]))
    check("M2 scalar 拒斥進 warnings 不進索引",
          ("Systems/A.md", "related", "殘留scalar非wikilink") in idx["scalars"]
          and not any("殘留" in t for t in rv), str(idx["scalars"]))
    amb = idx["ambiguous"]
    check("M2 同名歧義不靜默指第一篇(記候選清單)",
          len(amb) == 1 and amb[0][0] == "Systems/B.md" and amb[0][1] == "Dup"
          and sorted(amb[0][3]) == ["Projects/Dup.md", "Systems/Dup.md"]
          and not any(p == ("Systems/B.md", "related") for pairs in rv.values() for p in pairs),
          str(amb))
    # 投影比較:每條 resolved typed edge 必存在於 Env.edges(超集,不做集合等價)
    out_e, _ = env.edges
    proj_ok = all(t in out_e.get(s, []) for t, pairs in rv.items() for (s, _e) in pairs)
    check("M2 投影比較:resolved typed edge ⊆ Env.edges", proj_ok, str(dict(rv)))


def t_check_e3_intent_chain():
    v = mkvault()
    # 目標節點 D:d1 已翻案、d2 有效
    write(v, "Projects/D.md",
          "type: project\nstatus: done\n"
          "decisions:\n"
          "  - content: 舊路線\n    id: d1\n    decided: 2026-05-01\n    valid: false\n"
          "    superseded_by: 新路線\n    ended: 2026-06-10\n"
          "  - content: 新路線\n    id: d2\n    decided: 2026-06-10\n    valid: true", body="# D\n")
    # 正例:指向已翻案的 d1 → 斷義
    write(v, "Verification/VA.md",
          "type: verification\nstatus: pass\ndate: 2026-05-02\ndecision_refs:\n  - \"Projects/D.md#d1\"", body="# VA\n")
    # 反例:指向有效的 d2 → 不報
    write(v, "Verification/VB.md",
          "type: verification\nstatus: pass\ndate: 2026-06-11\ndecision_refs:\n  - \"Projects/D.md#d2\"", body="# VB\n")
    # dangling:指向未指派的 d9 + 不存在節點
    write(v, "Verification/VC.md",
          "type: verification\nstatus: pass\ndate: 2026-06-11\ndecision_refs:\n"
          "  - \"Projects/D.md#d9\"\n  - \"Projects/Nope.md#d1\"", body="# VC\n")
    r = run(v, "doctor")
    check("E3 抓斷義 1 條(指 d1 翻案)", "發現 1 條意圖鏈斷義" in r.stdout and "Verification/VA" in r.stdout, r.stdout)
    check("E3 不報有效 d2", "Verification/VB.md → " not in r.stdout, r.stdout)
    check("E3 dangling 2 條浮出(未指派 id+節點不存在)", "發現 2 條 dangling" in r.stdout, r.stdout)


def t_check_e2_decision_refs_refinement():
    v = mkvault()
    write(v, "Projects/D.md",
          "type: project\nstatus: done\n"
          "decisions:\n"
          "  - content: 被翻的\n    id: d1\n    decided: 2026-05-01\n    valid: false\n"
          "    superseded_by: 新\n    ended: 2026-06-10\n"
          "  - content: 別條有效\n    id: d2\n    decided: 2026-05-01\n    valid: true", body="# D\n")
    # A:有 decision_refs 且指到「那條」d1、updated 早於 ended → 標
    write(v, "Systems/A.md",
          "type: system\nstatus: done\nupdated: 2026-06-01\nverified_by:\n  - \"[[Projects/D]]\"\n"
          "decision_refs:\n  - \"Projects/D.md#d1\"", body="# A\n")
    # B:有 decision_refs 但指到別條 d2、updated 也早 → 精化不冤枉,不標
    write(v, "Systems/B.md",
          "type: system\nstatus: done\nupdated: 2026-06-01\nverified_by:\n  - \"[[Projects/D]]\"\n"
          "decision_refs:\n  - \"Projects/D.md#d2\"", body="# B\n")
    # C:無 decision_refs、updated 早 → 退回節點級,照標(相容不退化)
    write(v, "Systems/C.md",
          "type: system\nstatus: done\nupdated: 2026-06-01\nverified_by:\n  - \"[[Projects/D]]\"", body="# C\n")
    r = run(v, "doctor")
    check("E2 精化:A(指到那條)+C(無 refs)共 2 條,B(指別條)不冤枉",
          "發現 2 條可能建在被推翻決策上" in r.stdout, r.stdout)
    check("E2 精化點名 A 與 C", "Systems/A.md --" in r.stdout and "Systems/C.md --" in r.stdout, r.stdout)
    check("E2 精化不報 B", "Systems/B.md --" not in r.stdout, r.stdout)


# ══ 第二輪審計回歸 ══

# ── NEW-A: 跨資料夾同 basename append 不該誤 dedup / 不該 rc=2 ──
def t_append_cross_folder_same_basename():
    v = mkvault()
    write(v, "Systems/X.md", "type: system\nstatus: done")  # 另一篇,同 basename X
    p = write(v, "Systems/S.md",
              "type: system\nstatus: done\nverified_by:\n  - \"[[Verification/X]]\"")
    r = run(v, "append", "S", "verified_by", "[[Systems/X]]")
    check("NEW-A 跨資料夾同名 append 成功(非 rc=2 自驗失敗)", r.returncode == 0, r.stderr)
    check("NEW-A [[Systems/X]] 真的被加(與 [[Verification/X]] 並存)",
          "[[Systems/X]]" in read(p) and "[[Verification/X]]" in read(p), read(p))


# ── append path 式 vs basename 式同篇 → 視為重複(dedup) ──
def t_append_path_vs_basename_dedup():
    v = mkvault()
    p = write(v, "Systems/S.md",
              "type: system\nstatus: done\nverified_by:\n  - \"[[Verification/X]]\"")
    # 注意: link_target 保留路徑,故 [[X]] 與 [[Verification/X]] target 不同字串 →
    # 會新增(可接受的冗餘,非錯誤)。本案僅鎖定「完全相同 target 不重複」。
    run(v, "append", "S", "verified_by", "[[Verification/X]]", expect_rc=0)
    check("完全相同 target 不重複加", read(p).count("[[Verification/X]]") == 1, read(p))


# ── NEW-B: Check 3 跨資料夾同 basename 不該假通過 ──
def t_check3_cross_folder_no_false_pass():
    v = mkvault()
    write(v, "Systems/S.md",
          "type: system\nstatus: done\nverified_by:\n  - \"[[Projects/MyV]]\"")
    write(v, "Projects/MyV.md", "type: project\nstatus: done")  # 不同篇,同 basename
    write(v, "Verification/MyV.md", "type: verification\nstatus: pass\ndate: 2026-01-01",
          body="# MyV\n驗 [[S]]\n")
    r = run(v, "doctor", "--ci")
    missed = set()
    for line in r.stdout.splitlines():
        if "漏:" in line:
            missed |= {t.strip() for t in line.split("漏:", 1)[1].split("|")}
    check("NEW-B Check3 跨資料夾: Verification/MyV 漏寫被報(非被 Projects/MyV 同 basename 誤判)",
          r.returncode == 1 and "MyV" in missed, f"missed={missed}\n{r.stdout}")


# ── Check 3 path 式 vs basename 式同篇 → 視為已同步(不誤報漏) ──
def t_check3_path_basename_equiv():
    v = mkvault()
    # verified_by 用 path 式,Verification 也在 Verification/ → 同篇,不該報漏
    write(v, "Systems/S.md",
          "type: system\nstatus: done\nverified_by:\n  - \"[[Verification/MyV]]\"")
    write(v, "Verification/MyV.md", "type: verification\nstatus: pass\ndate: 2026-01-01",
          body="# MyV\n驗 [[S]]\n")
