# ── export 逸出節點名中的 " (R3 latent bug) ──
def t_export_quote_escape():
    if sys.platform == "win32":
        check("export quote: NTFS 禁 \" 字元,Windows skip", True)
        return
    v = mkvault()
    write(v, 'Systems/A"B.md', "type: system\nstatus: done")
    rm = run(v, "export", "--format", "mermaid", "--folders", "Systems", expect_rc=0)
    check('export mermaid: " 逸出成 &quot;(不破語法)',
          '&quot;' in rm.stdout and 'A"B"]' not in rm.stdout, rm.stdout)
    rd = run(v, "export", "--format", "dot", "--folders", "Systems", expect_rc=0)
    check('export dot: " 逸出成 \\"(不破語法)',
          '\\"' in rd.stdout, rd.stdout)


# ── search 全文搜尋 ──
def t_search():
    v = mkvault()
    write(v, "Systems/A.md", "type: system\nstatus: done", body="# A\nServiceType 代碼說明\n")
    write(v, "Verification/B.md", "type: verification\nstatus: pass\ndate: 2026-01-01",
          body="# B\n無關內容\n")
    r = run(v, "search", "ServiceType", "--files-only", expect_rc=0)
    check("search 命中 A 不命中 B", "Systems/A.md" in r.stdout and "Verification/B.md" not in r.stdout, r.stdout)
    r2 = run(v, "search", "servicetype", "--files-only", expect_rc=0)
    check("search 大小寫不敏感", "Systems/A.md" in r2.stdout, r2.stdout)
    r3 = run(v, "search", "ServiceType", "--path", "Verification", "--files-only", expect_rc=0)
    check("search --path 限定資料夾(Systems 命中被排除)", "Systems/A.md" not in r3.stdout, r3.stdout)
    r4 = run(v, "search", "Service.*代碼", "--regex", "--files-only", expect_rc=0)
    check("search --regex", "Systems/A.md" in r4.stdout, r4.stdout)
    # ★架構圖先行注入(2026-08-14)★:有命中 → stderr 提醒「用 show 讀全文再下結論」。
    # 防的失效模式=search 命中卻只掃摘要就判「架構圖沒記」(金鑰事故實證)。
    r5 = run(v, "search", "ServiceType", expect_rc=0)
    check("search 有命中 → stderr 提醒 show 全文", "命中≠查完" in r5.stderr and "lumos show" in r5.stderr, r5.stderr)
    check("search 提醒走 stderr 不污染 stdout", "命中≠查完" not in r5.stdout, r5.stdout)
    r6 = run(v, "search", "ServiceType", "--files-only", expect_rc=0)
    check("search --files-only(機器消費端)不印提醒", "命中≠查完" not in r6.stderr, r6.stderr)
    r7 = run(v, "search", "zzz_不存在的詞", expect_rc=0)
    check("search 0 命中不印提醒(該走換詞重查而非 show)", "命中≠查完" not in r7.stderr, r7.stderr)
    r8 = run(v, "search", "ServiceType", "--legacy", expect_rc=0)
    check("search legacy 模式同樣提醒", "命中≠查完" in r8.stderr, r8.stderr)


# ── search 尊重標籤哲學: 排除 code block + 標記區域(option A) ──
def t_search_structure_aware():
    v = mkvault()
    write(v, "Systems/C.md",
          "type: system\nstatus: done\nsummary: |-\n  KEY:★INVARIANT★ widget 不可改",
          body="# C\n正文提到 widget\n```\nwidget in code block\n```\n")
    # 預設排除 code block: 只命中 frontmatter ★INVARIANT★ + body 正文,不含 code 那行
    r = run(v, "search", "widget", expect_rc=0)
    check("search 排除 code block(預設)", "widget in code block" not in r.stdout, r.stdout)
    check("search 區域標記 ★INVARIANT★", "[★INVARIANT★]" in r.stdout, r.stdout)
    check("search 區域標記 body", "[body]" in r.stdout, r.stdout)
    # --code 才含 code block 那行
    rc = run(v, "search", "widget", "--code", expect_rc=0)
    check("search --code 含 code block 內容", "widget in code block" in rc.stdout, rc.stdout)


# ── gov 去噪:同日同類 advisory 折疊+大群組摘要+--full 逃生(帳不動只動呈現) ──
def t_gov_denoise():
    import json as _j
    # 私有巢狀結構(root/docs/x-knowledge):gov 讀 vault.parent 當帳目錄——
    # 不可用 mkvault()(standalone,parent=共用系統 tmp,寫帳會污染他測跨執行讀的同名檔)
    root = Path(tempfile.mkdtemp(prefix="gctl-gov-"))
    v = root / "docs" / "x-knowledge"
    for sub in ("Systems", "MOC"):
        (v / sub).mkdir(parents=True)
    (v / "MOC" / "idx.md").write_bytes("---\ntype: moc\n---\n# idx\n".encode("utf-8"))
    write(v, "Systems/A.md", "type: system\nstatus: done", body="# A\n")
    docs = v.parent
    rows = []
    # 3 次 doctor 各記同一批 10 節點的 check-s(不同 commit)→ 舊版 30 行噪音
    for c in ("c1", "c2", "c3"):
        for i in range(10):
            rows.append({"ts": "2026-07-24T10:00:00+08:00", "commit": c, "gate": "check-s",
                         "kind": "warned", "hard": False, "nodes": [f"node{i}"]})
    (docs / ".governance-log.jsonl").write_text(
        "\n".join(_j.dumps(r) for r in rows) + "\n", encoding="utf-8")
    (docs / ".canary-log.jsonl").write_text(_j.dumps(
        {"ts": "2026-07-24T11:00:00+08:00", "kind": "caught", "token": "tk1",
         "loop": "demo", "severity": "minor", "auditor": "sonnet", "note": "r1"}) + "\n",
        encoding="utf-8")
    r = run(v, "gov", expect_rc=0)
    body = [l for l in r.stdout.splitlines() if l.startswith("2026-")]
    check("gov 去噪: 30 筆 advisory 折成 1 摘要行+1 canary", len(body) == 2, f"{len(body)} 行\n" + r.stdout[:400])
    check("gov 去噪: 摘要行含節點數與次數", "10 節點" in r.stdout and "×3" in r.stdout, r.stdout[:300])
    check("gov 去噪: canary 逐筆保留(不折)", "loop=demo" in r.stdout, r.stdout[:300])
    # --full 逃生:回完整帳(30 advisory+1 canary=31 行)
    rf = run(v, "gov", "--full", expect_rc=0)
    bodyf = [l for l in rf.stdout.splitlines() if l.startswith("2026-")]
    check("gov --full: 完整帳 31 行", len(bodyf) == 31, f"{len(bodyf)} 行")
    # 少量同類(≤6 節點)不收摘要、但同日跨 commit 仍折 ×N
    (docs / ".governance-log.jsonl").write_text(
        "\n".join(_j.dumps({"ts": "2026-07-24T10:00:00+08:00", "commit": c, "gate": "check-s",
                            "kind": "warned", "hard": False, "nodes": ["only1"]})
                  for c in ("c1", "c2")) + "\n", encoding="utf-8")
    r2 = run(v, "gov", expect_rc=0)
    check("gov 去噪: 小群組逐節點列+×2 計次", "only1" in r2.stdout and "×2" in r2.stdout, r2.stdout[:300])


# ── 真遺忘第二刀:doctor 對 superseded 驗證三面一致(不索回掛/判死背書/不補回) ──
def t_doctor_superseded_verification_consistency():
    v = mkvault()
    write(v, "Systems/S.md", "type: system\nstatus: done", body="# S\n")
    # 作廢驗證連到 S,但 S.verified_by 沒掛它
    write(v, "Verification/VDead.md",
          "type: verification\nstatus: superseded\ndate: 2026-01-01",
          body="# VDead\n驗過 [[Systems/S]]\n")
    r = run(v, "doctor", expect_rc=0)
    check("超越②Check3: superseded 驗證不索回掛(無 missing 報)",
          "VDead" not in r.stdout.split("[E1]")[0], r.stdout[:600])
    rs = run(v, "sync-verified-by")
    check("超越③sync: 不提議補回 superseded 驗證", "VDead" not in rs.stdout, rs.stdout[:300])
    # S 真的掛著作廢驗證 → E1 判死背書
    write(v, "Systems/S2.md",
          "type: system\nstatus: done\nverified_by:\n  - \"[[Verification/VDead2]]\"",
          body="# S2\n")
    write(v, "Verification/VDead2.md",
          "type: verification\nstatus: superseded\ndate: 2026-01-01",
          body="# VDead2\n驗過 [[Systems/S2]]\n")
    r2 = run(v, "doctor", expect_rc=0)
    check("超越①E1: 掛著 superseded 驗證=死背書警告",
          "S2" in r2.stdout and "superseded" in r2.stdout, r2.stdout[-800:])
    # stale 迴歸:行為不變(Check3 跳過、E1 警)
    write(v, "Systems/S3.md",
          "type: system\nstatus: done\nverified_by:\n  - \"[[Verification/VStale]]\"",
          body="# S3\n")
    write(v, "Verification/VStale.md",
          "type: verification\nstatus: stale\ndate: 2026-01-01",
          body="# VStale\n驗過 [[Systems/S3]]\n")
    r3 = run(v, "doctor", expect_rc=0)
    check("stale 迴歸: E1 照警", "VStale" in r3.stdout, r3.stdout[-600:])


