# ── pre-commit 閘:vendored 工具白名單豁免(lumos update 例行更新不該撞架構圖閘) ──
def _precommit_run(root, staged_rel):
    """fixture repo 內 stage 指定檔後跑 pre-commit hook,回 subprocess result。"""
    import subprocess, os
    hook = Path(GRAPHCTL).resolve().parent / "hooks" / "pre-commit"
    subprocess.run(["git", "-C", str(root), "init", "-q"], capture_output=True)
    (root / "docs" / "x-knowledge").mkdir(parents=True)   # Gate 0:有 vault 閘才啟用
    (root / "docs" / "x-knowledge" / ".keep").write_text("", encoding="utf-8")
    for rel in staged_rel:
        p = root / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text("x = 1\n", encoding="utf-8")
    subprocess.run(["git", "-C", str(root), "add", "-A"], capture_output=True)
    return subprocess.run(["bash", str(hook)], cwd=str(root), capture_output=True, text=True,
                          env=dict(os.environ, GIT_DIR=str(root / ".git")))


def t_precommit_vendored_exempt():
    """vendored 工具檔(_VENDORED_TOOLKIT+兩夾)豁免架構圖閘;使用者自有 code 仍照擋。"""
    import subprocess
    if not hasattr(__import__("os"), "setsid"):
        print("  - skip(非 POSIX)")
        return
    # ① 只 stage vendored .py → 放行(rc0;lumos update 例行更新情境)
    r1 = Path(tempfile.mkdtemp(prefix="gctl-pcv1-"))
    res1 = _precommit_run(r1, ["scripts/test_lumos.py", "scripts/merge-claude-settings.py",
                               "scripts/hooks/claude/impact-hook.py"])
    check("precommit 豁免: vendored .py 更新放行", res1.returncode == 0,
          f"rc={res1.returncode} {res1.stderr[-150:]}{res1.stdout[-150:]}")
    # ② 使用者自有 code(scripts/ 下非白名單)無架構圖 → 仍擋(rc1;豁免不能過寬)
    r2 = Path(tempfile.mkdtemp(prefix="gctl-pcv2-"))
    res2 = _precommit_run(r2, ["scripts/my_tool.py"])
    check("precommit 豁免: 使用者 scripts/my_tool.py 仍被擋(不過寬)", res2.returncode != 0,
          f"rc={res2.returncode}")
    # ③ 一般 src code 無架構圖 → 仍擋(既有行為迴歸)
    r3 = Path(tempfile.mkdtemp(prefix="gctl-pcv3-"))
    res3 = _precommit_run(r3, ["app/Main.kt"])
    check("precommit 豁免: 一般 code 無架構圖仍擋(迴歸)", res3.returncode != 0, f"rc={res3.returncode}")
    # ④ ★源 repo 守門★:有 skills/lumos-project-notes(=Lumos 源)→ 豁免失效,vendored 檔仍擋
    #    (否則源 repo 自家改 scripts/lumos 不帶架構圖會靜默放行=弄弱自家閘)
    r4 = Path(tempfile.mkdtemp(prefix="gctl-pcv4-"))
    (r4 / "skills" / "lumos-project-notes").mkdir(parents=True)
    res4 = _precommit_run(r4, ["scripts/test_lumos.py"])
    check("precommit 豁免: 源 repo 內豁免失效、仍擋", res4.returncode != 0, f"rc={res4.returncode}")


def t_precommit_whitelist_drift_guard():
    """漂移守衛:pre-commit+post-commit 的豁免清單都必須涵蓋 _VENDORED_TOOLKIT 每項+兩夾+源守門
    (post-commit 是 bypass 記帳端,漏對齊=例行 update 被記假 bypass 灌水;2026-07-25 實測踩過)。
    [終審 fix I3]同源第三份清單:delguard 的 _DELGUARD_EXCLUDE_DIRS/lockfile 排除規則
    也要對齊 pre-commit should_exclude,免得兩處各自漂。"""
    # 尾段直讀來源 repo 架構圖節點(pitfalls-code-loop.md)——消費端沒有,整支轉 skip
    # ([[Issues/vendored自測3紅_來源repo專用測試漏標skip]] 2026-08-17 Landmark 實錘)
    _need_src("docs/lumos-toolchain-knowledge/Systems/pitfalls-code-loop.md")
    m = _load_lumos()
    hooks_dir = Path(GRAPHCTL).resolve().parent / "hooks"
    for hook in ("pre-commit", "post-commit"):
        txt = (hooks_dir / hook).read_text(encoding="utf-8")
        for rel in m._VENDORED_TOOLKIT:
            check(f"{hook} 漂移守衛: 豁免清單含 {rel}", rel in txt, rel)
        for d in ("scripts/hooks/", "scripts/templates/"):
            check(f"{hook} 漂移守衛: 豁免清單含 {d}*", f"{d}*" in txt, d)
        check(f"{hook} 漂移守衛: 含源 repo 守門", "skills/lumos-project-notes" in txt, hook)

    # delguard 排除域對齊 pre-commit should_exclude(第三份同源清單)
    precommit_txt = (hooks_dir / "pre-commit").read_text(encoding="utf-8")
    case_line = [l for l in precommit_txt.splitlines() if "node_modules" in l and "case" not in l][0]
    for d in m._DELGUARD_EXCLUDE_DIRS:
        check(f"delguard 漂移守衛: 排除域 {d} 對齊 pre-commit should_exclude",
              d.rstrip("/") in case_line, case_line)
    # ★跨檔斷言★:三個 lockfile 名都要出現在 pre-commit 的**那一行** lock 排除規則裡。
    # (code-loop r1 L:原本還有一條「lf 出現在 scripts/lumos 源碼」——lf 本來就是從
    #  scripts/lumos 讀出來的常數值,恆真、零鑑別力,已刪。)
    lock_line = [l for l in precommit_txt.splitlines() if "package-lock.json" in l][0]
    for lf in m._DELGUARD_EXCLUDE_LOCKFILES:
        check(f"delguard 漂移守衛: lockfile {lf} 見於 pre-commit lock 排除行",
              lf in lock_line, lock_line)

    # delguard/UI 證據路徑同源(2026-08-11,Android UI 工作流 r2-F11):
    # pitfalls --diff 的排除規則與架構圖節點寫的路徑必須是同一個字串前綴
    lumos_src = Path(GRAPHCTL).read_text(encoding="utf-8")
    excl = "governance/review-reports/"
    check("delguard 證據路徑排除規則仍在 scripts/lumos", excl in lumos_src, excl)
    node = (Path(GRAPHCTL).resolve().parent.parent / "docs" / "lumos-toolchain-knowledge"
            / "Systems" / "pitfalls-code-loop.md").read_text(encoding="utf-8")
    # ★先切出「UI 層驗收慣例」那一行再驗★(2026-08-11 終審 F2:原寫法對整檔驗,
    # 正面被另一條無關 KEY 行滿足、負面只認逐字舊寫法 → 刪整行/換措辭都不會紅=近乎恆真)
    ui_lines = [l for l in node.splitlines() if "UI 層驗收慣例" in l]
    check("pitfalls-code-loop 仍有 UI 層驗收慣例那條 KEY(整行被刪要紅)", len(ui_lines) == 1,
          f"命中 {len(ui_lines)} 行")
    ui = ui_lines[0] if ui_lines else ""
    check("UI 驗收慣例的證據路徑帶 governance/ 前綴(換措辭掉前綴也要紅)",
          excl in ui and "review-reports/" not in ui.replace(excl, ""),
          ui[:160])
    check("UI 驗收慣例含 Android(maestro)通道", "maestro" in ui, ui[:160])


# ── Check T dart profile:test('id')/testWidgets('id') 字串名錨+檔名錨 *_test.dart ──
def t_dart_profile_discovery():
    m = _load_lumos()
    root = Path(tempfile.mkdtemp(prefix="gctl-dartprof-"))
    (root / "test").mkdir()
    (root / "test" / "order_test.dart").write_text(
        "void main() {\n"
        "  test('alpha_check', () {});\n"
        "  testWidgets('widget_flow', (tester) async {});\n"
        "  test('has spaces not bindable', () {});\n"
        "  /* test('dead_commented', () {}); */\n"
        "  // test('line_commented', () {});\n"
        "}\n", encoding="utf-8")
    (root / "test" / "helper.dart").write_text(   # 非 *_test.dart → 檔名錨排除
        "void main() { test('in_helper', () {}); }\n", encoding="utf-8")
    prof = dict(m.TEST_PROFILES["dart"])
    got = m.discover_test_methods(root, prof)
    check("dart: test('id') 認得", "alpha_check" in got, f"{got}")
    check("dart: testWidgets('id') 認得", "widget_flow" in got, f"{got}")
    check("dart: 含空白名不可綁(識別字錨,同 playwright)", not any("spaces" in g for g in got), f"{got}")
    check("dart: 塊註解內測試被剝(c-style)", "dead_commented" not in got, f"{got}")
    check("dart: 行註解內測試被剝", "line_commented" not in got, f"{got}")
    check("dart: 非 *_test.dart 檔名錨排除", "in_helper" not in got, f"{got}")
    import fnmatch as _fn
    fname = prof["scaffold_name"].format(m="pay_guard") + prof["scaffold_ext"]
    check("dart: scaffold 產物檔名命中檔名錨",
          any(_fn.fnmatch(fname, g) for g in prof["file_name_match"]), fname)


# ── Check T python profile:comment_strip=none+行首錨+檔名錨(CheckT-Python-profile_計劃) ──
def t_python_profile_discovery():
    m = _load_lumos()
    root = Path(tempfile.mkdtemp(prefix="gctl-pyprof-"))
    # 1) r1 實測炸點 fixture:status/* 註解+遠處 **/ 字面,中間的 t_mid 不得被吃
    (root / "test_x.py").write_text(
        "# set status 同步 tags 的 status/* 標籤\n"
        "def t_mid():\n    pass\n"
        "PAT = 'glob:**/'\n"
        "def test_a():\n    pass\n"
        "def t_b():\n    pass\n"
        "class TC:\n    def t_nested(self):\n        pass\n"
        "# def t_commented():\n", encoding="utf-8")
    # 2) 檔名錨:非測試檔名的 t_c 不認
    (root / "helper.py").write_text("def t_c():\n    pass\n", encoding="utf-8")
    prof = dict(m.TEST_PROFILES["python"])
    got = m.discover_test_methods(root, prof)
    check("pyprof: 炸點中間 t_mid 不被吃(comment_strip=none)", "t_mid" in got, f"{got}")
    check("pyprof: 行首 test_a/t_b 認得", {"test_a", "t_b"} <= got, f"{got}")
    check("pyprof: 類內縮排 t_nested 不認(行首錨)", "t_nested" not in got, f"{got}")
    check("pyprof: 被註解 # def t_commented 不認", "t_commented" not in got, f"{got}")
    check("pyprof: 非測試檔名 helper.py 的 t_c 不認(檔名錨)", "t_c" not in got, f"{got}")
    # 3) scaffold 欄位齊全且產物檔名命中檔名錨(std F2)
    import fnmatch as _fn
    check("pyprof: scaffold_ext 存在(guard scaffold 不 KeyError)", prof.get("scaffold_ext") == ".py")
    fname = prof["scaffold_name"].format(m="PayGuard") + prof["scaffold_ext"]
    check("pyprof: scaffold 產物檔名命中檔名錨",
          any(_fn.fnmatch(fname, g) for g in prof["file_name_match"]), fname)
    # 4) c-style 對照組(std F5:必須用 .cs fixture,拿 .py 掛 csharp 會被 exts 濾掉假綠)
    root2 = Path(tempfile.mkdtemp(prefix="gctl-csprof-"))
    (root2 / "Tests").mkdir()
    (root2 / "Tests" / "FooTests.cs").write_text(
        "/* 註解掉的舊測試\n[Fact]\npublic void OldGuard() {}\n*/\n"
        "[Fact]\npublic void RealGuard() {}\n", encoding="utf-8")
    got2 = m.discover_test_methods(root2, dict(m.TEST_PROFILES["csharp-xunit"]))
    check("csprof 對照: 註解內 OldGuard 照舊被剝", "OldGuard" not in got2, f"{got2}")
    check("csprof 對照: RealGuard 認得", "RealGuard" in got2, f"{got2}")


