def _mk_delguard_bookkeeping_repo():
    """[2026-08-26]簿記檔(.jsonl 帳本 / anchor-baseline.json)的刪除行不得被抽成 token。
    這些檔的內容是**紀錄**不是宣告,刪掉一行從來不代表「某個符號沒了」;不排除的話
    治理帳的欄位名(commit/gate/kind/nodes…)會被當成被刪符號拿去 git grep 全 repo,
    輸出爆量再逐行配 40 個 regex——實測 2 檔/63 刪除行的 commit 因此跑逾 5 分鐘未完成。
    fixture 讓帳本刪除行帶一個在 vault 有提及的獨特符號,排除生效則零命中。"""
    import subprocess as sp
    root = Path(tempfile.mkdtemp(prefix="gctl-delg-bk-"))
    sp.run(["git", "-C", str(root), "init", "-q"], capture_output=True)
    sp.run(["git", "-C", str(root), "config", "user.email", "t@t.t"], capture_output=True)
    sp.run(["git", "-C", str(root), "config", "user.name", "t"], capture_output=True)
    gr = root / "docs" / "kg-knowledge"
    (gr / "Systems").mkdir(parents=True)
    (root / "governance").mkdir()
    (root / "docs" / ".governance-log.jsonl").write_text(
        '{"gate": "check-s", "nodes": ["zzLedgerTok"]}\n'
        '{"gate": "check-e1", "nodes": ["zzLedgerTok"]}\n', encoding="utf-8")
    (root / "governance" / "anchor-baseline.json").write_text(
        '{"scripts/zzBaselineTok.py": "abc123"}\n', encoding="utf-8")
    (gr / "Systems" / "sys.md").write_text(
        "---\ntype: system\n---\n# sys\n講 zzLedgerTok 也講 zzBaselineTok。\n", encoding="utf-8")
    sp.run(["git", "-C", str(root), "add", "-A"], capture_output=True)
    sp.run(["git", "-C", str(root), "commit", "-qm", "init"], capture_output=True)
    # staged 刪除:帳本與 baseline 各清空 → 兩個獨特符號都「消失」了
    (root / "docs" / ".governance-log.jsonl").write_text("", encoding="utf-8")
    (root / "governance" / "anchor-baseline.json").write_text("{}\n", encoding="utf-8")
    sp.run(["git", "-C", str(root), "add", "-A"], capture_output=True)
    return root, "docs/kg-knowledge"


def _mk_delguard_capflood_repo():
    """delguard 終審 fix I2 fixture:staged 刪除 45 個獨特符號(超 DELGUARD_TOKEN_CAP=40),
    僅 capTok0 在 vault 有命中,但**分佈在 12 個節點**(> DELGUARD_TOP_N=10)——
    用來釘 cap 截斷後 dropped>0、且 top-10 截斷真的有鑑別力(命中數 12 > 上限 10,
    舊 fixture 只有 1 個命中,`<= TOP_N` 斷言恆真、刪掉截斷邏輯也不翻紅;code-loop r1 J)。"""
    import subprocess as sp
    root = Path(tempfile.mkdtemp(prefix="gctl-delg-cap-"))
    sp.run(["git", "-C", str(root), "init", "-q"], capture_output=True)
    sp.run(["git", "-C", str(root), "config", "user.email", "t@t.t"], capture_output=True)
    sp.run(["git", "-C", str(root), "config", "user.name", "t"], capture_output=True)
    gr = root / "docs" / "kg-knowledge"
    (gr / "Systems").mkdir(parents=True)
    (root / "app").mkdir()
    calls = "\n".join(f"    capTok{i}()" for i in range(45))
    (root / "app" / "Foo.kt").write_text(f"fun x() {{\n{calls}\n}}\n", encoding="utf-8")
    for n in range(12):  # 12 > DELGUARD_TOP_N,讓 top-10 截斷有東西可截
        (gr / "Systems" / f"sys{n}.md").write_text(
            f"---\ntype: system\n---\n# sys{n}\n用到 capTok0 做事。\n", encoding="utf-8")
    sp.run(["git", "-C", str(root), "add", "-A"], capture_output=True)
    sp.run(["git", "-C", str(root), "commit", "-qm", "init"], capture_output=True)
    (root / "app" / "Foo.kt").write_text("fun x() {\n}\n", encoding="utf-8")
    sp.run(["git", "-C", str(root), "add", "app/Foo.kt"], capture_output=True)
    return root, "docs/kg-knowledge"


def _mk_delguard_capflood_repo_single():
    """[r2 N4]capflood 姊妹 fixture:同樣 45 個獨特符號超 cap(dropped>0),但僅 **1 個節點**
    命中(rest=0)——釘 `if rest or dropped` 的 or 語意:12 節點版(rest>0)測不到「rest=0 但
    dropped>0 仍要印統計行」這格,若被誤改成 `if rest and dropped` 兩版舊 fixture 都測不出來
    (12 節點版 rest>0∧dropped>0 對 and/or 皆真,無鑑別力),必須靠這支單節點版翻紅。"""
    import subprocess as sp
    root = Path(tempfile.mkdtemp(prefix="gctl-delg-cap1-"))
    sp.run(["git", "-C", str(root), "init", "-q"], capture_output=True)
    sp.run(["git", "-C", str(root), "config", "user.email", "t@t.t"], capture_output=True)
    sp.run(["git", "-C", str(root), "config", "user.name", "t"], capture_output=True)
    gr = root / "docs" / "kg-knowledge"
    (gr / "Systems").mkdir(parents=True)
    (root / "app").mkdir()
    calls = "\n".join(f"    capTok{i}()" for i in range(45))
    (root / "app" / "Foo.kt").write_text(f"fun x() {{\n{calls}\n}}\n", encoding="utf-8")
    (gr / "Systems" / "sys0.md").write_text(
        "---\ntype: system\n---\n# sys0\n用到 capTok0 做事。\n", encoding="utf-8")
    sp.run(["git", "-C", str(root), "add", "-A"], capture_output=True)
    sp.run(["git", "-C", str(root), "commit", "-qm", "init"], capture_output=True)
    (root / "app" / "Foo.kt").write_text("fun x() {\n}\n", encoding="utf-8")
    sp.run(["git", "-C", str(root), "add", "app/Foo.kt"], capture_output=True)
    return root, "docs/kg-knowledge"


def t_delguard():
    """[delguard Task 1]LINK_KEYS 常數＋子集守衛斷言:
    ①LINK_KEYS 常數存在且值正確
    ②子集守衛:LINK_KEYS ⊆ LIST_KEYS ∪ {core_refs}
    翻紅釘:刪 LINK_KEYS 常數 → ①翻紅;LINK_KEYS 值偏離 → ①翻紅;
           破壞子集關係 → ②翻紅。"""
    print("t_delguard")
    import re as _re
    src = Path(GRAPHCTL).read_text(encoding="utf-8")
    m = _re.search(r"^LINK_KEYS\s*=\s*\(([^)]*)\)", src, _re.M)
    check("delguard LINK_KEYS 常數存在", m is not None, "LINK_KEYS not found")
    keys = set(_re.findall(r'"(\w+)"', m.group(1))) if m else set()
    check("delguard LINK_KEYS 值正確", keys == {"verified_by", "plan_refs", "related", "core_refs"}, str(keys))
    lm = _re.search(r"^LIST_KEYS\s*=\s*\{([^}]*)\}", src, _re.M)
    listk = set(_re.findall(r'"(\w+)"', lm.group(1))) if lm else set()
    check("delguard 子集守衛 LINK_KEYS ⊆ LIST_KEYS∪{core_refs}", keys <= (listk | {"core_refs"}), f"{keys} vs {listk}")

    # [delguard Task 2]_delguard_parse_diff:staged diff 抽被刪識別字＋vault 檔 diff 分流
    from importlib import machinery, util as _u
    # 以 exec 載入 scripts/lumos 取函式(本檔既有慣例:直接 subprocess 打 CLI 或 exec 模組;此處走 exec)
    spec_ = machinery.SourceFileLoader("lumos_mod", GRAPHCTL)
    mod = _u.module_from_spec(_u.spec_from_loader("lumos_mod", spec_))
    spec_.exec_module(mod)
    DIFF = """diff --git a/app/Login.kt b/app/Login.kt
--- a/app/Login.kt
+++ b/app/Login.kt
@@ -10,3 +9,2 @@
-        refreshPaywayCredentials()
-        val keep = renamedHelper(x)
+        val keep = renamedHelperV2(x)
diff --git a/docs/lumos-toolchain-knowledge/Systems/pay.md b/docs/lumos-toolchain-knowledge/Systems/pay.md
--- a/docs/lumos-toolchain-knowledge/Systems/pay.md
+++ b/docs/lumos-toolchain-knowledge/Systems/pay.md
@@ -3,1 +3,2 @@
 verified_by:
+  - "[[Verification/x]]"
"""
    out = mod._delguard_parse_diff(DIFF, "docs/lumos-toolchain-knowledge")
    check("delguard 抽到被刪 token", "refreshPaywayCredentials" in out["tokens"], str(out["tokens"]))
    # 修正(brief 原斷言結構性不可能為真,見 task-2-report.md):tokens 依 spec 只從 `-` 行收,
    # "renamedHelperV2" 只出現在 `+` 行故永不可能進 tokens——"...or renamedHelperV2 in tokens" 恆假,
    # 使整條斷言退化成「renamedHelper not in tokens」,但同一 spec 又明文只回收「字面相同」的 token,
    # renamedHelper≠renamedHelperV2 字面不同,不得回收,故該分支恆假、整條斷言對任何合規實作恆假。
    # 改測真正該釘的兩面:相同字面(keep 同時在 - / + 行原樣出現)→回收剔除;
    # 不同字面改名(renamedHelper→renamedHelperV2)→已知低信心誤報源,spec 明文 v1 不解,仍留在 tokens。
    check("delguard +行回收:同字面(keep)濾除、不同字面改名(renamedHelper)留為已知誤報",
          "keep" not in out["tokens"] and "renamedHelper" in out["tokens"], str(out["tokens"]))
    check("delguard stopword 剔除", "val" not in out["tokens"], str(out["tokens"]))
    check("delguard vault diff 不進 tokens 且收進 vault_diffs", "verified_by" not in out["tokens"] and any(p.endswith("pay.md") for p in out["vault_diffs"]), str(out))

    # [delguard Task 3]_delguard_confidence:staged-index 兩檔信心(單次 git grep)
    root, gr = _mk_delguard_repo()
    conf = mod._delguard_confidence(["refreshPaywayCredentials", "helperStillUsed"], str(root), gr)
    check("delguard 全域消失=high", conf.get("refreshPaywayCredentials") == "high", str(conf))
    check("delguard 仍有呼叫點=low", conf.get("helperStillUsed") == "low", str(conf))
    # 快照契約:worktree 加回不影響(index 為準)
    (root / "app" / "Login.kt").write_text("fun login() { refreshPaywayCredentials() }\n", encoding="utf-8")
    conf2 = mod._delguard_confidence(["refreshPaywayCredentials"], str(root), gr)
    check("delguard 快照=index 不被 worktree 救回", conf2.get("refreshPaywayCredentials") == "high", str(conf2))

    # [delguard Task 4]_delguard_vault_scan:三件套 alternation 掃 vault＋型別排序
    hits = mod._delguard_vault_scan(["refreshPaywayCredentials", "helperStillUsed"], conf,
                                    str(root / gr))
    check("delguard vault 命中 Systems 原句", any(h["node"] == "Systems/憑證.md" and "撈一次" in h["line"] for h in hits), str(hits))
    check("delguard CJK 緊貼命中(re.ASCII)", any("還在講" in h["line"] and "helperStillUsed" in h["tokens"] for h in hits), str(hits))
    check("delguard Projects 也報(型別只排序不壓低)", any(h["folder"] == "Projects" for h in hits), str(hits))
    sys_idx = min(i for i, h in enumerate(hits) if h["folder"] == "Systems")
    proj_idx = min(i for i, h in enumerate(hits) if h["folder"] == "Projects")
    check("delguard Systems 排前", sys_idx < proj_idx, str([(h["folder"], h["conf"]) for h in hits]))
    # 詞界:蓋 refreshPaywayCredentialsV2 不誤配
    (root / gr / "Systems" / "V2.md").write_text("---\ntype: system\n---\n用 refreshPaywayCredentialsV2 取代。\n", encoding="utf-8")
    hits2 = mod._delguard_vault_scan(["refreshPaywayCredentials"], conf, str(root / gr))
    check("delguard \\b 詞界不誤配 V2", not any(h["node"] == "Systems/V2.md" for h in hits2), str(hits2))

    # [delguard Task 5]_delguard_purelink:S2 純連結 diff 判定(保守朝不報)
    pl = mod._delguard_purelink(['+  - "[[Verification/2026-08-03_x]]"'])
    check("delguard S2 純掛連結=True", pl is True, str(pl))
    check("delguard S2 動 body=False", mod._delguard_purelink(['+  - "[[V/x]]"', "+登入不再撈憑證"]) is False, "")
    check("delguard S2 pitfall_when 不算連結", mod._delguard_purelink(["+pitfall_when:", '+  - "撈憑證"']) is False, "")
    check("delguard S2 鍵頭+列表項=True", mod._delguard_purelink(["+verified_by:", '+  - "[[V/x]]"']) is True, "")
    check("delguard S2 空 diff=False(無變更不算純連結)", mod._delguard_purelink([]) is False, "")

    # [delguard Task 6]cmd_delguard_check 組裝＋子命令 CLI 整合測試
    import subprocess as sp
    import json

    def dg(*a, cwd=None, env=None):
        import os as _os
        e = dict(_os.environ); e.update(env or {})
        return sp.run([sys.executable, GRAPHCTL, "delguard", *a],
                      capture_output=True, text=True, cwd=cwd or str(root), env=e)
    r = dg("--staged", "--json")
    check("delguard CLI rc0", r.returncode == 0, r.stderr)
    data = json.loads(r.stdout.strip().splitlines()[-1])
    check("delguard 抓到 aff2329 形狀(高信心命中)", any(h["conf"] == "high" for h in data["hits"]), str(data)[:400])
    r = dg("--staged")
    check("delguard 警告走 stdout+S3 問句", "退場前自問" in r.stdout and r.returncode == 0, r.stdout[:400])
    # 假同步嫌疑:vault 節點只掛連結+S1 命中
    p = root / gr / "Systems" / "憑證.md"
    p.write_text(p.read_text(encoding="utf-8").replace("---\n# 憑證",
        '---\n# 憑證').replace("type: system\n", 'type: system\nverified_by:\n  - "[[Verification/x]]"\n'), encoding="utf-8")
    sp.run(["git", "-C", str(root), "add", "-A"], capture_output=True)
    r = dg("--staged", "--json")
    fs = json.loads(r.stdout.strip().splitlines()[-1])["fake_sync"]
    check("delguard S2 假同步嫌疑(純連結∧S1命中)", "Systems/憑證.md" in fs, str(fs))
    # 超時降級:env 注 0 → rc0+降級訊息在 stdout
    r = dg("--staged", env={"LUMOS_DELGUARD_DEADLINE": "0"})
    check("delguard 超時 fail-open rc0", r.returncode == 0, str(r.returncode))
    check("delguard 降級訊息在 stdout", "超時降級" in r.stdout, f"out={r.stdout!r} err={r.stderr!r}")
    # 內部錯誤 fail-open:env 注入測試鉤子
    r = dg("--staged", env={"LUMOS_DELGUARD_RAISE": "1"})
    check("delguard 內部錯誤 fail-open rc0+訊息", r.returncode == 0 and "內部錯誤" in r.stdout, r.stdout[:200])
    # 效能 benchmark:<1s(254 檔級 vault 用本 repo 真 vault 跑,40 token;
    # 一併連 _delguard_confidence 計時,合計仍要 <1s——單看 vault_scan 會漏掉 git grep 那段成本)
    # [code-loop r1 K]git grep 也改對**真 repo** 的 staged index 跑:原本打在 3 檔玩具 repo 上,
    # 量級與現場差幾個數量級,等於沒量到 confidence 這段成本
    import time as _t
    toks = [f"zzNoSuchTok{i}" for i in range(40)]
    real_root = str(Path(GRAPHCTL).parent.parent)
    real_gr = str(Path(GRAPHCTL).parent.parent / "docs" / "lumos-toolchain-knowledge")
    t0 = _t.monotonic()
    mod._delguard_confidence(toks, real_root, "docs/lumos-toolchain-knowledge")
    mod._delguard_vault_scan(toks, {}, real_gr)
    check("delguard benchmark(confidence+vault 掃)<1s", _t.monotonic() - t0 < 1.0, f"{_t.monotonic()-t0:.2f}s")

    # [終審 fix I1]subprocess timeout 契約:_delguard_confidence 傳極小 timeout 應拋例外(fail-open 前提)
    ok = False
    try:
        mod._delguard_confidence(["x"], str(root), gr, timeout=0.000001)
    except Exception:
        ok = True
    check("delguard _delguard_confidence timeout= 逾時拋例外", ok, "no exception raised")

    # [終審 fix I2]刷屏降級:45 個獨特被刪符號(超 cap=40)→ --json dropped>0;文字模式印「超 cap」統計行、
    # 逐條列出不超過 top-10
    root_cap, _gr_cap = _mk_delguard_capflood_repo()
    r_cap = sp.run([sys.executable, GRAPHCTL, "delguard", "--staged", "--json"],
                   capture_output=True, text=True, cwd=str(root_cap))
    data_cap = json.loads(r_cap.stdout.strip().splitlines()[-1])
    check("delguard --json cap 截斷後 dropped>0", data_cap.get("dropped", 0) > 0, str(data_cap)[:200])
    r_cap_txt = sp.run([sys.executable, GRAPHCTL, "delguard", "--staged"],
                        capture_output=True, text=True, cwd=str(root_cap))
    check("delguard 文字模式含「超 cap」統計行", "超 cap" in r_cap_txt.stdout, r_cap_txt.stdout[:300])
    # [code-loop r1 J]前置斷言:命中數必須真的超過 top-10,否則下面的截斷斷言恆真(無鑑別力)
    check("delguard top-10 前置:fixture 命中數 > TOP_N",
          len(data_cap["hits"]) > mod.DELGUARD_TOP_N, f"hits={len(data_cap['hits'])}")
    n_hit_lines = sum(1 for ln in r_cap_txt.stdout.splitlines() if ln.strip().startswith("["))
    check("delguard 逐條列出剛好截到 top-10", n_hit_lines == mod.DELGUARD_TOP_N, r_cap_txt.stdout[:500])
    rest_expect = len(data_cap["hits"]) - mod.DELGUARD_TOP_N
    check("delguard 統計行報出被截掉的 rest(>0)",
          rest_expect > 0 and f"另有 {rest_expect} 處命中" in r_cap_txt.stdout, r_cap_txt.stdout[:500])

    # [delguard fix r1] --json 降級契約:超時/內部錯誤兩條路徑都要印合法單行 JSON+degraded=True(rc0)
    r = dg("--staged", "--json", env={"LUMOS_DELGUARD_DEADLINE": "0"})
    check("delguard 超時降級 --json rc0", r.returncode == 0, str(r.returncode))
    dj = json.loads(r.stdout.strip().splitlines()[-1])
    check("delguard 超時降級 --json degraded=True", dj.get("degraded") is True, str(dj))
    check("delguard 超時降級 --json 形狀完整(tokens/hits/fake_sync)",
          isinstance(dj.get("tokens"), int) and dj.get("hits") == [] and dj.get("fake_sync") == [], str(dj))
    r = dg("--staged", "--json", env={"LUMOS_DELGUARD_RAISE": "1"})
    check("delguard 內部錯誤 --json rc0", r.returncode == 0, str(r.returncode))
    dj = json.loads(r.stdout.strip().splitlines()[-1])
    check("delguard 內部錯誤 --json degraded=True", dj.get("degraded") is True, str(dj))
    check("delguard 內部錯誤 --json 形狀完整(tokens/hits/fake_sync)",
          isinstance(dj.get("tokens"), int) and dj.get("hits") == [] and dj.get("fake_sync") == [], str(dj))

    # [2026-08-26]★超時必須落 reason=timeout,不得混進 error★
    # 現場實例:358 檔 commit 的 pre-commit 兩次都印「內部錯誤(TimeoutExpired),放行」——
    # subprocess 逾時(git diff / _delguard_confidence 的 git grep)拋 TimeoutExpired,
    # 原本落進通用 except → --json reason="error"、文字說「內部錯誤」。這既違反本函式自己
    # 宣告的 reason:"timeout"|"error" 契約,也讓「這道閘沒跑完」讀起來像「程式壞了」。
    r = dg("--staged", "--json", env={"LUMOS_DELGUARD_RAISE": "timeout"})
    check("delguard TimeoutExpired --json rc0", r.returncode == 0, str(r.returncode))
    dj = json.loads(r.stdout.strip().splitlines()[-1])
    check("delguard TimeoutExpired --json reason=timeout(非 error)",
          dj.get("reason") == "timeout", str(dj))
    check("delguard TimeoutExpired --json degraded=True", dj.get("degraded") is True, str(dj))
    r = dg("--staged", env={"LUMOS_DELGUARD_RAISE": "timeout"})
    check("delguard TimeoutExpired 文字不得說「內部錯誤」",
          "內部錯誤" not in r.stdout, r.stdout[:300])
    check("delguard TimeoutExpired 文字歸類為超時降級",
          "超時降級" in r.stdout, r.stdout[:300])

    # ★降級輸出必須自陳「這輪沒守」★:原文字僅「…放行;本輪掃描不完整」,
    # 與正常通過(靜默)混在一起看不出差別,實測被誤讀為正常通過。
    for _env in ({"LUMOS_DELGUARD_DEADLINE": "0"},
                 {"LUMOS_DELGUARD_RAISE": "timeout"},
                 {"LUMOS_DELGUARD_RAISE": "1"}):
        r = dg("--staged", env=_env)
        check(f"delguard 降級輸出自陳未實際守衛({list(_env)[0]}={list(_env.values())[0]})",
              "未實際守衛" in r.stdout, r.stdout[:300])

    # [2026-08-26]★簿記檔不抽 token★:帳本/baseline 的刪除行是紀錄不是宣告
    root_bk, _gr_bk = _mk_delguard_bookkeeping_repo()
    r = sp.run([sys.executable, GRAPHCTL, "delguard", "--staged", "--json"],
               capture_output=True, text=True, cwd=str(root_bk))
    d_bk = json.loads(r.stdout.strip().splitlines()[-1])
    check("delguard 簿記檔 .jsonl/baseline 刪除行不抽 token", d_bk["tokens"] == 0, str(d_bk)[:400])
    check("delguard 簿記檔零命中(不誤報 vault 提及)", d_bk["hits"] == [], str(d_bk)[:400])
    check("delguard 簿記檔案例未降級(排除後成本低,跑得完)",
          d_bk.get("degraded") is False, str(d_bk)[:400])

    # [delguard fix r1] 標頭行計數=實際命中的 distinct 符號數,不是被刪符號總數
    root_hc, _gr_hc = _mk_delguard_headcount_repo()
    r = sp.run([sys.executable, GRAPHCTL, "delguard", "--staged"],
               capture_output=True, text=True, cwd=str(root_hc))
    check("delguard 標頭計數=命中符號數(1個,非刪除總數2個)",
          "1 個被刪符號" in r.stdout and "2 個被刪符號" not in r.stdout, r.stdout[:300])

    # [delguard Task 7]pre-commit Gate DG 掛載＋排除域對齊斷言
    hook = Path(GRAPHCTL).parent / "hooks" / "pre-commit"
    ht = hook.read_text(encoding="utf-8")
    cond = "delguard --staged" in ht and "|| true" in ht.split("delguard --staged")[1][:40]
    check("delguard Gate DG 已掛 pre-commit", cond, "gate missing")
    # 排除域對齊:python 排除清單每一項都出現在 should_exclude 的 case 行裡
    case_line = [l for l in ht.splitlines() if "node_modules" in l and "case" not in l][0]
    for d in mod._DELGUARD_EXCLUDE_DIRS:
        check(f"delguard 排除域對齊 pre-commit({d})", d.rstrip("/") in case_line, case_line)
    # [code-loop r1 M]Gate DG 條件必須連 scripts/lumos 存在也檢(未 vendored 的 repo 只有 python 也會跑)
    dg_block = ht.split("Gate DG")[1][:400]
    check("delguard Gate DG 條件含 -f scripts/lumos",
          '-f "$REPO_ROOT/scripts/lumos"' in dg_block, dg_block[:200])

    # ── [code-loop r1 修復波]釘測 ──────────────────────────────────────────
    # [r1 A]排除域是路徑段比對,不是子字串:src/robin/ 不得被 bin/ 誤殺
    DIFF_EXCL = """diff --git a/src/robin/Handler.kt b/src/robin/Handler.kt
--- a/src/robin/Handler.kt
+++ b/src/robin/Handler.kt
@@ -1,2 +1,1 @@
-    robinOnlySymbol()
diff --git a/node_modules/x/a.js b/node_modules/x/a.js
--- a/node_modules/x/a.js
+++ b/node_modules/x/a.js
@@ -1,2 +1,1 @@
-    nodeRootSymbol()
diff --git a/app/node_modules/y.js b/app/node_modules/y.js
--- a/app/node_modules/y.js
+++ b/app/node_modules/y.js
@@ -1,2 +1,1 @@
-    nodeNestedSymbol()
diff --git a/app/bin/z.kt b/app/bin/z.kt
--- a/app/bin/z.kt
+++ b/app/bin/z.kt
@@ -1,2 +1,1 @@
-    binNestedSymbol()
"""
    ex = mod._delguard_parse_diff(DIFF_EXCL, "docs/kg-knowledge")["tokens"]
    check("delguard 排除域路徑段:src/robin/ 不被 bin/ 誤殺", "robinOnlySymbol" in ex, str(ex))
    check("delguard 排除域:根層 node_modules/ 仍排除", "nodeRootSymbol" not in ex, str(ex))
    check("delguard 排除域:巢狀 app/node_modules/ 仍排除", "nodeNestedSymbol" not in ex, str(ex))
    check("delguard 排除域:巢狀 app/bin/ 仍排除", "binNestedSymbol" not in ex, str(ex))

    # [r1 C]回收表 per-file:別檔(CHANGELOG.md)提一句不得讓 code 檔的真刪除滅聲
    DIFF_XFILE = """diff --git a/app/Risk.kt b/app/Risk.kt
--- a/app/Risk.kt
+++ b/app/Risk.kt
@@ -1,3 +1,2 @@
-    computeUserRiskScore()
diff --git a/CHANGELOG.md b/CHANGELOG.md
--- a/CHANGELOG.md
+++ b/CHANGELOG.md
@@ -1,1 +1,2 @@
+- 移除 computeUserRiskScore 這支
"""
    xf = mod._delguard_parse_diff(DIFF_XFILE, "docs/kg-knowledge")["tokens"]
    check("delguard 回收表 per-file:別檔 + 行不滅聲(computeUserRiskScore 仍在)",
          "computeUserRiskScore" in xf, str(xf))

    # [r1 O①]binary 檔段整段跳過,且不破壞後續檔案解析
    DIFF_BIN = """diff --git a/assets/img.png b/assets/img.png
Binary files a/assets/img.png and b/assets/img.png differ
diff --git a/app/A.kt b/app/A.kt
--- a/app/A.kt
+++ b/app/A.kt
@@ -1,2 +1,1 @@
-    afterBinarySymbol()
"""
    bt = mod._delguard_parse_diff(DIFF_BIN, "docs/kg-knowledge")["tokens"]
    check("delguard binary 段跳過後續檔照抽", "afterBinarySymbol" in bt, str(bt))
    check("delguard binary 段本身不抽 token", not any(t in bt for t in ("Binary", "differ", "png")), str(bt))

    # [r1 O②]檔頭判定只認 `--- a/`/`--- /dev/null`:內容為 `-- SQL 註解` 的被刪行要抽
    DIFF_SQL = """diff --git a/db/schema.sql b/db/schema.sql
--- a/db/schema.sql
+++ b/db/schema.sql
@@ -1,3 +1,1 @@
--- legacyAuditTrigger 記錄用
-DROP TABLE oldAuditTable;
"""
    st = mod._delguard_parse_diff(DIFF_SQL, "docs/kg-knowledge")["tokens"]
    check("delguard SQL `--` 註解型被刪行照抽(不當檔頭吃掉)", "legacyAuditTrigger" in st, str(st))
    check("delguard 一般被刪行照抽", "oldAuditTable" in st, str(st))
    check("delguard 檔頭行不當內容抽(schema/sql 不進 tokens)",
          "schema" not in st and "sql" not in st, str(st))

    # [r1 N / spec C5]S2 純連結:同一連結行只改縮排(-舊/+新 strip 後同內容)= 動過內容,不算純掛連結
    check("delguard S2 重縮排同內容=False(不判純連結)",
          mod._delguard_purelink(['-  - "[[V/x]]"', '+    - "[[V/x]]"']) is False, "")

    # [r1 O⑥]metachar token 直餵 vault_scan 不炸(regex 一律 re.escape)
    try:
        mod._delguard_vault_scan(["a.b{c", "x)y"], {}, str(root / gr))
        meta_ok = True
    except Exception as _e:
        meta_ok = False
    check("delguard metachar token 不炸 vault_scan", meta_ok, "regex escape missing")

    # ── CLI 級釘測(fixture repo)──
    tmp_repos = []

    def _mkrepo(prefix):
        p = Path(tempfile.mkdtemp(prefix=prefix))
        for a in (["init", "-q"], ["config", "user.email", "t@t.t"], ["config", "user.name", "t"]):
            sp.run(["git", "-C", str(p), *a], capture_output=True)
        tmp_repos.append(p)
        return p

    def _cli(cwd, *a, env=None):
        import os as _os
        e = dict(_os.environ); e.update(env or {})
        return sp.run([sys.executable, GRAPHCTL, "delguard", "--staged", *a],
                      capture_output=True, text=True, cwd=str(cwd), env=e)

    # [r1 B]confidence 只配內容域:檔名撞 token(app/Login.kt)不得把 Login 降級成 low
    rb = _mkrepo("gctl-delg-name-")
    (rb / "docs" / "kg-knowledge" / "Systems").mkdir(parents=True)
    (rb / "app").mkdir()
    (rb / "app" / "Login.kt").write_text("fun doIt() {\n    helperStillUsed()\n}\n", encoding="utf-8")
    sp.run(["git", "-C", str(rb), "add", "-A"], capture_output=True)
    sp.run(["git", "-C", str(rb), "commit", "-qm", "init"], capture_output=True)
    cb = mod._delguard_confidence(["Login", "helperStillUsed"], str(rb), "docs/kg-knowledge")
    check("delguard confidence 檔名撞名不誤降級(Login=high)", cb.get("Login") == "high", str(cb))
    check("delguard confidence 內容真命中仍 low(helperStillUsed)",
          cb.get("helperStillUsed") == "low", str(cb))

    # [r1 D]diff 前綴設定(diff.noprefix)不得打破解析
    rd = _mkrepo("gctl-delg-noprefix-")
    (rd / "docs" / "kg-knowledge" / "Systems").mkdir(parents=True)
    (rd / "docs" / "kg-knowledge" / "Systems" / "s.md").write_text(
        "---\ntype: system\n---\n用 noPrefixVictimSymbol 做事。\n", encoding="utf-8")
    (rd / "app").mkdir()
    (rd / "app" / "P.kt").write_text("fun x() {\n    noPrefixVictimSymbol()\n}\n", encoding="utf-8")
    sp.run(["git", "-C", str(rd), "add", "-A"], capture_output=True)
    sp.run(["git", "-C", str(rd), "commit", "-qm", "init"], capture_output=True)
    sp.run(["git", "-C", str(rd), "config", "diff.noprefix", "true"], capture_output=True)
    (rd / "app" / "P.kt").write_text("fun x() {\n}\n", encoding="utf-8")
    sp.run(["git", "-C", str(rd), "add", "-A"], capture_output=True)
    r = _cli(rd, "--json")
    dd = json.loads(r.stdout.strip().splitlines()[-1])
    check("delguard diff.noprefix=true 仍抽得到 token", dd.get("tokens", 0) > 0, r.stdout[:300])
    check("delguard diff.noprefix=true 仍命中 vault",
          any("noPrefixVictimSymbol" in h["tokens"] for h in dd.get("hits", [])), r.stdout[:300])

    # [r1 E]standalone vault repo(整個 repo 就是 vault)→ 靜默 rc0,不炸
    rv = _mkrepo("gctl-delg-vaultonly-")
    for sub in ("MOC", "Systems"):
        (rv / sub).mkdir()
    # 節點內文帶 ASCII 識別字:少了這個,graph_root="." 誤判時也抽不到 token、測試會恆綠
    (rv / "Systems" / "s.md").write_text(
        "---\ntype: system\n---\n用 legacyVaultSymbol 做事。\n", encoding="utf-8")
    (rv / "MOC" / "m.md").write_text(
        "---\ntype: moc\n---\n索引也提 legacyVaultSymbol。\n", encoding="utf-8")
    sp.run(["git", "-C", str(rv), "add", "-A"], capture_output=True)
    sp.run(["git", "-C", str(rv), "commit", "-qm", "init"], capture_output=True)
    (rv / "Systems" / "s.md").write_text("---\ntype: system\n---\n改過的說明。\n", encoding="utf-8")
    sp.run(["git", "-C", str(rv), "add", "-A"], capture_output=True)
    r = _cli(rv)
    check("delguard standalone vault repo rc0 且靜默",
          r.returncode == 0 and r.stdout.strip() == "", f"rc={r.returncode} out={r.stdout[:300]}")
    r = _cli(rv, "--json")
    check("delguard standalone vault repo --json 不炸(rc0)",
          r.returncode == 0 and "Traceback" not in r.stderr, f"rc={r.returncode} err={r.stderr[:300]}")

    # [r1 F]LUMOS_DELGUARD_DEADLINE 非數值 → fallback 2.0,不是 rc1 traceback
    r = _cli(root, "--json", env={"LUMOS_DELGUARD_DEADLINE": "abc"})
    check("delguard env deadline 非數值 fail-open rc0", r.returncode == 0, f"rc={r.returncode} err={r.stderr[:300]}")
    dfl = json.loads(r.stdout.strip().splitlines()[-1])
    check("delguard env deadline 非數值後行為如常(未降級)", dfl.get("degraded") is False, str(dfl)[:200])

    # [r1 G]非 UTF-8 staged 檔不得炸整支,正常檔照抽
    rg = _mkrepo("gctl-delg-enc-")
    (rg / "docs" / "kg-knowledge" / "Systems").mkdir(parents=True)
    (rg / "docs" / "kg-knowledge" / "Systems" / "s.md").write_text(
        "---\ntype: system\n---\n用 encVictimSymbol 做事。\n", encoding="utf-8")
    (rg / "app").mkdir()
    (rg / "app" / "Big5.kt").write_bytes(b"// \xa4\xa4\xa4\xe5\nfun legacyBig5Fun() {}\n")
    (rg / "app" / "Ok.kt").write_text("fun x() {\n    encVictimSymbol()\n}\n", encoding="utf-8")
    sp.run(["git", "-C", str(rg), "add", "-A"], capture_output=True)
    sp.run(["git", "-C", str(rg), "commit", "-qm", "init"], capture_output=True)
    (rg / "app" / "Big5.kt").write_bytes(b"// \xa4\xa4\n")
    (rg / "app" / "Ok.kt").write_text("fun x() {\n}\n", encoding="utf-8")
    sp.run(["git", "-C", str(rg), "add", "-A"], capture_output=True)
    r = _cli(rg, "--json")
    de = json.loads(r.stdout.strip().splitlines()[-1])
    check("delguard 非 UTF-8 staged 檔:rc0 不降級", r.returncode == 0 and de.get("degraded") is False,
          f"rc={r.returncode} out={r.stdout[:300]} err={r.stderr[:200]}")
    check("delguard 非 UTF-8 staged 檔:正常檔 token 照抽",
          any("encVictimSymbol" in h["tokens"] for h in de.get("hits", [])), r.stdout[:300])

    # [r1 O③]initial commit(無 HEAD、只有 staged)→ rc0 不炸
    ri = _mkrepo("gctl-delg-initial-")
    (ri / "docs" / "kg-knowledge" / "Systems").mkdir(parents=True)
    (ri / "docs" / "kg-knowledge" / "Systems" / "s.md").write_text(
        "---\ntype: system\n---\n內容\n", encoding="utf-8")
    (ri / "app").mkdir()
    (ri / "app" / "New.kt").write_text("fun brandNewSymbol() {}\n", encoding="utf-8")
    sp.run(["git", "-C", str(ri), "add", "-A"], capture_output=True)
    r = _cli(ri, "--json")
    check("delguard initial commit(無 HEAD)rc0 不炸(僅煙霧;initial commit 無先前內容可刪)",
          r.returncode == 0 and "Traceback" not in r.stderr, f"rc={r.returncode} err={r.stderr[:300]}")

    # [r1 O④]CJK 路徑/檔名照抽(core.quotePath=off)
    rc = _mkrepo("gctl-delg-cjk-")
    (rc / "docs" / "kg-knowledge" / "Systems").mkdir(parents=True)
    (rc / "docs" / "kg-knowledge" / "Systems" / "s.md").write_text(
        "---\ntype: system\n---\n用 cjkPathSymbol 做事。\n", encoding="utf-8")
    (rc / "app" / "登入模組").mkdir(parents=True)
    (rc / "app" / "登入模組" / "登入.kt").write_text("fun x() {\n    cjkPathSymbol()\n}\n", encoding="utf-8")
    sp.run(["git", "-C", str(rc), "add", "-A"], capture_output=True)
    sp.run(["git", "-C", str(rc), "commit", "-qm", "init"], capture_output=True)
    (rc / "app" / "登入模組" / "登入.kt").write_text("fun x() {\n}\n", encoding="utf-8")
    sp.run(["git", "-C", str(rc), "add", "-A"], capture_output=True)
    r = _cli(rc, "--json")
    dc = json.loads(r.stdout.strip().splitlines()[-1])
    check("delguard CJK 路徑檔名照抽 token",
          any("cjkPathSymbol" in h["tokens"] for h in dc.get("hits", [])), r.stdout[:300])

    # [r1 O⑤]純 rename(git mv 未 commit)→ 沒有內容被刪,tokens=0
    # [r2 N2]先關 diff.renames(有些環境的 ~/.gitconfig 全域開著,會讓「有 -M 才抓得到 rename」
    # 這件事悄悄失去鑑別力——關掉後只剩 CLI 自己下的 `-M` 撐著偵測,拿掉 -M 才會翻紅
    rr = _mkrepo("gctl-delg-rename-")
    sp.run(["git", "-C", str(rr), "config", "diff.renames", "false"], capture_output=True)
    (rr / "docs" / "kg-knowledge" / "Systems").mkdir(parents=True)
    (rr / "docs" / "kg-knowledge" / "Systems" / "s.md").write_text(
        "---\ntype: system\n---\n用 renameOnlySymbol 做事。\n", encoding="utf-8")
    (rr / "app").mkdir()
    (rr / "app" / "Old.kt").write_text("fun x() {\n    renameOnlySymbol()\n}\n", encoding="utf-8")
    sp.run(["git", "-C", str(rr), "add", "-A"], capture_output=True)
    sp.run(["git", "-C", str(rr), "commit", "-qm", "init"], capture_output=True)
    sp.run(["git", "-C", str(rr), "mv", "app/Old.kt", "app/New.kt"], capture_output=True)
    r = _cli(rr, "--json")
    dr = json.loads(r.stdout.strip().splitlines()[-1])
    check("delguard 純 rename tokens=0(-M 認得搬檔)", dr.get("tokens") == 0, r.stdout[:300])

    # [r1 O⑦]S2 negative:節點只掛連結但**無 S1 命中** → 不進 fake_sync
    rn = _mkrepo("gctl-delg-s2neg-")
    grn = rn / "docs" / "kg-knowledge" / "Systems"
    grn.mkdir(parents=True)
    (grn / "無關.md").write_text("---\ntype: system\n---\n這裡完全沒提被刪的符號。\n", encoding="utf-8")
    (rn / "app").mkdir()
    (rn / "app" / "A.kt").write_text("fun x() {\n    s2NegSymbol()\n}\n", encoding="utf-8")
    sp.run(["git", "-C", str(rn), "add", "-A"], capture_output=True)
    sp.run(["git", "-C", str(rn), "commit", "-qm", "init"], capture_output=True)
    (rn / "app" / "A.kt").write_text("fun x() {\n}\n", encoding="utf-8")
    (grn / "無關.md").write_text(
        '---\ntype: system\nverified_by:\n  - "[[Verification/x]]"\n---\n這裡完全沒提被刪的符號。\n',
        encoding="utf-8")
    sp.run(["git", "-C", str(rn), "add", "-A"], capture_output=True)
    r = _cli(rn, "--json")
    dn = json.loads(r.stdout.strip().splitlines()[-1])
    check("delguard S2 negative:純連結但無 S1 命中 → 不進 fake_sync",
          dn.get("fake_sync") == [], r.stdout[:300])

    # ── [code-loop r2 修復波]釘測 ──────────────────────────────────────────
    # [r2 N1]vault 前綴無路徑邊界:graph_root="docs/kg" 不得誤配手足目錄 docs/kg-legacy/
    # (字首相同、不同目錄)。★注意★:手足目錄的 notes.md 本身仍是非 vault 的 .md,依 N5
    # 修復(見下)一律不產 token——故本測的鑑別力落在 vault_diffs 路由(修復前是 True 誤判、
    # 混進 vault_diffs;修復後正確排除),另搭一個真 code 檔的刪除證明同一 diff 其餘檔案
    # 的抽取不受影響。
    DIFF_SIBLING = """diff --git a/app/Real.kt b/app/Real.kt
--- a/app/Real.kt
+++ b/app/Real.kt
@@ -1,2 +1,1 @@
-    boundaryCodeSymbol()
diff --git a/docs/kg-legacy/notes.md b/docs/kg-legacy/notes.md
--- a/docs/kg-legacy/notes.md
+++ b/docs/kg-legacy/notes.md
@@ -1,1 +0,0 @@
-siblingVaultSymbol 這裡提過
"""
    sib = mod._delguard_parse_diff(DIFF_SIBLING, "docs/kg")
    check("delguard vault 前綴路徑邊界:手足目錄 docs/kg-legacy 不進 vault_diffs",
          not sib["vault_diffs"], str(sib))
    check("delguard vault 前綴路徑邊界:同一 diff 其餘 code 檔 token 正常抽到(不受牽連)",
          "boundaryCodeSymbol" in sib["tokens"], str(sib))

    # [r2 N3②]git diff rc!=0 不得靜默假成功:production 端要 raise 落 degraded/內部錯誤,
    # 不能回報「tokens=0」假裝掃描乾淨(有 vault 佈局但 cwd 不是 git repo,逼 git diff 失敗)
    # [code-loop r3 P2]釘環境依賴:TMPDIR 若恰好落在某個外層 git repo 之下,git 會沿目錄樹往上
    # 找到那個外層 .git,讓「cwd 非 git repo」的前提失守 → 本測假紅。用 GIT_CEILING_DIRECTORIES
    # 擋在 fixture 目錄的父層,禁止 git 往上跨出去找 .git。
    import os as _os_n3
    rz = Path(tempfile.mkdtemp(prefix="gctl-delg-nogit-"))
    tmp_repos.append(rz)
    (rz / "docs" / "kg-knowledge" / "Systems").mkdir(parents=True)  # vault 佈局但**無 .git**
    (rz / "docs" / "kg-knowledge" / "Systems" / "s.md").write_text(
        "---\ntype: system\n---\n內容\n", encoding="utf-8")
    env_n3 = dict(_os_n3.environ, GIT_CEILING_DIRECTORIES=str(rz.parent))
    r = sp.run([sys.executable, GRAPHCTL, "delguard", "--staged", "--repo", "/nonexistent-zzz", "--json"],
               capture_output=True, text=True, cwd=str(rz), env=env_n3)
    check("delguard git diff 失敗(非 git repo cwd)rc0 fail-open", r.returncode == 0,
          f"rc={r.returncode} err={r.stderr[:200]}")
    dz = json.loads(r.stdout.strip().splitlines()[-1])
    check("delguard git diff 失敗:--json degraded=True(不是假成功 tokens=0)", dz.get("degraded") is True, str(dz))
    r_txt = sp.run([sys.executable, GRAPHCTL, "delguard", "--staged", "--repo", "/nonexistent-zzz"],
                    capture_output=True, text=True, cwd=str(rz), env=env_n3)
    check("delguard git diff 失敗:文字模式印「內部錯誤」", "內部錯誤" in r_txt.stdout, r_txt.stdout[:200])

    # [r2 N4]capflood rest=0∧dropped>0:統計行仍要印(釘 `if rest or dropped` 的 or 語意,
    # 別被誤改成 and——舊 12 節點版 rest>0∧dropped>0 對 and/or 皆真,測不出這格)
    root_cap1, _gr_cap1 = _mk_delguard_capflood_repo_single()
    r_cap1 = sp.run([sys.executable, GRAPHCTL, "delguard", "--staged", "--json"],
                     capture_output=True, text=True, cwd=str(root_cap1))
    data_cap1 = json.loads(r_cap1.stdout.strip().splitlines()[-1])
    check("delguard capflood 單節點版:dropped>0", data_cap1.get("dropped", 0) > 0, str(data_cap1)[:200])
    r_cap1_txt = sp.run([sys.executable, GRAPHCTL, "delguard", "--staged"],
                         capture_output=True, text=True, cwd=str(root_cap1))
    rest1 = len(data_cap1["hits"]) - min(len(data_cap1["hits"]), mod.DELGUARD_TOP_N)
    check("delguard capflood 單節點版:rest=0 前置(否則本測無鑑別力)", rest1 == 0, str(rest1))
    expect1 = f"另有 {rest1} 處命中/{data_cap1['dropped']} 個符號超 cap 未展開"
    check("delguard capflood 單節點版:rest=0∧dropped>0 統計行仍印(or 語意)",
          expect1 in r_cap1_txt.stdout, r_cap1_txt.stdout[:300])

    # [r2 N5]per-file 回收表 .md 不對稱:第二遍抽 token 時同樣跳過所有 .md(與第一遍一致),
    # 非 vault 的 .md(如 README.md)不是 code,重排 diff 不該把散文詞彙當 token 抽出去
    DIFF_README = """diff --git a/README.md b/README.md
--- a/README.md
+++ b/README.md
@@ -1,2 +1,2 @@
-alphaLine betaLine
-gammaLine deltaLine
+gammaLine deltaLine
+alphaLine betaLine
"""
    rmd = mod._delguard_parse_diff(DIFF_README, "docs/kg-knowledge")
    check("delguard 非 vault .md 重排 diff:tokens=[]", rmd["tokens"] == [], str(rmd))

    # 收尾:清 tempdir(同 t_cochange 慣例;code-loop r1 I 洩漏修復)
    import shutil as _sh
    for d in (root, root_cap, root_hc, root_cap1, *tmp_repos):
        _sh.rmtree(d, ignore_errors=True)


def t_canary_record_persist():
    """[S1] record 落盤自驗:印絕對路徑/token 讀回相符/readback 失敗 rc2 不印 ✓。"""
    import json as _json
    v = mkvault()
    log = v.parent / ".canary-log.jsonl"
    r = run(v, "canary", "record", "caught", "--loop", "L1", "--auditor", "sonnet")
    check("record rc0", r.returncode == 0, r.stderr)
    check("輸出含 log 絕對路徑", str(log) in r.stdout, r.stdout)
    tok = [w for w in r.stdout.split() if w.startswith("CANARY-")][0].rstrip(":")
    rows = [_json.loads(l) for l in log.read_text(encoding="utf-8").splitlines() if l.strip()]
    check("token 落盤且相符", any(x.get("token") == tok for x in rows), rows)
    r = run(v, "canary", "record", "caught", "--loop", "L1")
    check("--auditor 未給時無 auditor 段", "auditor=" not in r.stdout, r.stdout)
    # 2b. readback 失敗誘發:log 指向 /dev/null(append 成功、讀回恆空)
    log.unlink()
    log.symlink_to("/dev/null")
    r = run(v, "canary", "record", "missed", "--loop", "L1", "--auditor", "x")
    check("readback 失敗 rc2", r.returncode == 2, f"rc={r.returncode} {r.stdout}")
    check("readback 失敗訊息", "落盤自驗失敗" in r.stderr, r.stderr)
    check("readback 失敗不印 ✓", "✓" not in r.stdout, r.stdout)


def t_canary_second():
    """[S2] 第二判者:自身 token/ref/gov 可見/不進 gate/參數守衛。"""
    import json as _json
    v = mkvault()
    log = v.parent / ".canary-log.jsonl"
    r = run(v, "canary", "record", "caught", "--loop", "L2", "--round", "r1",
            "--auditor", "sonnet", "--severity", "minor", "--findings", "0",
            "--capture-counts", "1")
    tok = [w for w in r.stdout.split() if w.startswith("CANARY-")][0].rstrip(":")
    base_status = run(v, "loop", "status", "L2", "--gate", "--panel", "--min-seats", "1")
    r = run(v, "canary", "second", "--id", tok, "--verdict", "agree",
            "--auditor", "opus", "--note", "覆核同意")
    check("second rc0", r.returncode == 0, f"{r.returncode} {r.stderr}")
    rows = [_json.loads(l) for l in log.read_text(encoding="utf-8").splitlines() if l.strip()]
    sec = [x for x in rows if x.get("kind") == "second"]
    check("second 一次寫一行(單源不雙寫)", len(sec) == 1, sec)
    check("second 帶自身 token 且 != ref", sec[0].get("token", "").startswith("CANARY-")
          and sec[0]["token"] != tok and sec[0].get("ref") == tok, sec[0])
    check("second note 落盤", sec[0].get("note") == "覆核同意", sec[0])
    check("second 成功行印自身 token", sec[0]["token"] in r.stdout, r.stdout)
    after = run(v, "loop", "status", "L2", "--gate", "--panel", "--min-seats", "1")
    check("second 不影響 gate(輸出+rc 逐字節同)",
          after.stdout == base_status.stdout and after.returncode == base_status.returncode,
          f"{after.returncode}/{base_status.returncode}")
    # 多筆 second 不被 gov dedup 吞 + verdict 可見
    run(v, "canary", "second", "--id", tok, "--verdict", "overturn", "--auditor", "codex")
    g = run(v, "gov")
    check("gov 見得到 second 且不吞(2 筆)", g.stdout.count("second") >= 2, g.stdout[-400:])
    check("gov 見得到 verdict", "overturn" in g.stdout and "agree" in g.stdout, g.stdout[-400:])
    # 守衛
    r = run(v, "canary", "second", "--id", "CANARY-nope", "--verdict", "agree", "--auditor", "x")
    check("second --id 不存在 rc2", r.returncode == 2, str(r.returncode))
    r = run(v, "canary", "second", "--id", tok, "--verdict", "maybe", "--auditor", "x")
    check("second verdict 亂值 rc2", r.returncode == 2, str(r.returncode))
    r = run(v, "canary", "second", "--id", tok, "--verdict", "agree")
    check("second 缺 --auditor rc2", r.returncode == 2, str(r.returncode))
    # second 不得同人自覆核(分權核心;終審 Codex 抓到)
    r0 = run(v, "canary", "record", "caught", "--loop", "L3", "--auditor", "opus")
    tok3 = [w for w in r0.stdout.split() if w.startswith("CANARY-")][0].rstrip(":")
    r = run(v, "canary", "second", "--id", tok3, "--verdict", "agree", "--auditor", "opus")
    check("second 同判者自覆核 rc2", r.returncode == 2 and "分權" in r.stderr,
          f"{r.returncode} {r.stderr[:120]}")
    r = run(v, "canary", "second", "--id", tok3, "--verdict", "agree", "--auditor", "codex")
    check("second 不同判者放行", r.returncode == 0, r.stderr)
    # second 走同一自驗 helper 的證據:壞行(半截多位元組)不炸、仍能寫入並讀回
    with open(log, "ab") as fh:
        fh.write(b'{"kind":"record","token":"CANARY-broken","note":"\xe4\xb8')
        fh.write(b"\n")
    r = run(v, "canary", "second", "--id", tok3, "--verdict", "overturn", "--auditor", "qwen")
    check("second 對壞行容錯不炸(rc0)", r.returncode == 0, f"{r.returncode} {r.stderr[:150]}")


def _mk_attr_env(runner_body, method="TestLimitFive"):
    """合成 kill 環境但 run_cmd 指向可控輸出的假 runner(歸因測試用)。"""
    import subprocess as sp
    root, v = _mk_kill_env()
    (root / "fake_runner.py").write_text(runner_body, encoding="utf-8")
    (root / ".lumos" / "config.json").write_text(
        '{"test": {"run_cmd": "python3 fake_runner.py"}}', encoding="utf-8")
    sp.run(["git", "-C", str(root), "add", "-A"], capture_output=True)
    sp.run(["git", "-C", str(root), "commit", "-qm", "fake"], capture_output=True)
    return root, v


def t_guard_kill_rc_precedence():
    """[合約] rc 優先序三格窮盡 + 混批次優先(審計打回:原綁定只覆蓋 1/3 格)。"""
    import subprocess as sp, os, json as _json
    def lum(root, v, *a):
        e = dict(os.environ); e["LUMOS_KILL_TIMEOUT_FLOOR"] = "5"
        return sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *a],
                      capture_output=True, text=True, cwd=root, env=e)
    # survived → rc1
    root, v = _mk_attr_env("print('ok')\n")   # 永遠綠=殺不掉
    lum(root, v, "guard", "kill-add", "Systems/Limit", "上限恆為5",
        "--file", "prod.py", "--old", "LIMIT = 5", "--new", "LIMIT = 99")
    r = lum(root, v, "guard", "kill", "Systems/Limit")
    check("rc格1 survived→rc1", r.returncode == 1, f"{r.returncode} {r.stdout}")
    # drifted → rc2
    root, v = _mk_attr_env("import prod, sys\nsys.exit(0 if prod.LIMIT == 5 else 1)\n")
    lum(root, v, "guard", "kill-add", "Systems/Limit", "上限恆為5",
        "--file", "prod.py", "--old", "NOT_THERE", "--new", "X")
    r = lum(root, v, "guard", "kill", "Systems/Limit")
    check("rc格2 drifted→rc2", r.returncode == 2, f"{r.returncode} {r.stdout}")
    # 混批次:survived + drifted 同批 → survived 優先 rc1
    root, v = _mk_attr_env("print('ok')\n")
    lum(root, v, "guard", "kill-add", "Systems/Limit", "上限恆為5",
        "--file", "prod.py", "--old", "LIMIT = 5", "--new", "LIMIT = 99")
    lum(root, v, "guard", "kill-add", "Systems/Limit", "上限恆為5",
        "--file", "prod.py", "--old", "NOT_THERE", "--new", "X")
    r = lum(root, v, "guard", "kill", "Systems/Limit")
    check("rc優先序 survived勝drifted→rc1", r.returncode == 1, f"{r.returncode} {r.stdout}")
    # 弱證據不放行執行錯誤:timeout + drifted 同批 → rc2
    root, v = _mk_attr_env("import prod, time\nif prod.LIMIT != 5:\n    time.sleep(60)\nprint('ok')\n")
    lum(root, v, "guard", "kill-add", "Systems/Limit", "上限恆為5",
        "--file", "prod.py", "--old", "LIMIT = 5", "--new", "LIMIT = 99")
    lum(root, v, "guard", "kill-add", "Systems/Limit", "上限恆為5",
        "--file", "prod.py", "--old", "NOT_THERE", "--new", "X")
    r = lum(root, v, "guard", "kill", "Systems/Limit")
    check("rc優先序 弱證據不蓋過drifted→rc2", r.returncode == 2, f"{r.returncode} {r.stdout}")


def t_guard_kill_json_purity():
    """[合約] --json 成功路徑 stdout 恰一行純 JSON:dirty repo/多平台 legacy 警告兩情境。"""
    import subprocess as sp, os, json as _json
    def lum(root, v, *a):
        e = dict(os.environ); e["LUMOS_KILL_TIMEOUT_FLOOR"] = "5"
        return sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *a],
                      capture_output=True, text=True, cwd=root, env=e)
    def one_line(r, label):
        lines = [l for l in r.stdout.splitlines() if l.strip()]
        check(f"{label} stdout 恰一行", len(lines) == 1, r.stdout[:300])
        if len(lines) == 1:
            check(f"{label} 該行合法 JSON", bool(_json.loads(lines[0])), lines[0][:120])
    # 情境1:dirty worktree
    root, v = _mk_attr_env("import prod, sys\nsys.exit(0 if prod.LIMIT == 5 else 1)\n")
    lum(root, v, "guard", "kill-add", "Systems/Limit", "上限恆為5",
        "--file", "prod.py", "--old", "LIMIT = 5", "--new", "LIMIT = 99")
    (root / "dirty.txt").write_text("x", encoding="utf-8")
    one_line(lum(root, v, "guard", "kill", "Systems/Limit", "--json"), "dirty")
    # 情境2:多平台 config 同時留 legacy test.run_cmd(審計打回的漏網分支)
    root, v = _mk_attr_env("import prod, sys\nsys.exit(0 if prod.LIMIT == 5 else 1)\n")
    (root / ".lumos" / "config.json").write_text(_json.dumps({
        "test": {"run_cmd": "python3 fake_runner.py"},
        "platforms": {"py": {"run_cmd": "python3 fake_runner.py", "profile": "python"}}},
        ensure_ascii=False), encoding="utf-8")
    sp.run(["git", "-C", str(root), "add", "-A"], capture_output=True)
    sp.run(["git", "-C", str(root), "commit", "-qm", "mp"], capture_output=True)
    lum(root, v, "guard", "kill-add", "Systems/Limit", "上限恆為5",
        "--file", "prod.py", "--old", "LIMIT = 5", "--new", "LIMIT = 99", "--platform", "py")
    one_line(lum(root, v, "guard", "kill", "Systems/Limit", "--json"), "multiplatform-legacy")
    # 情境3:--keep-worktree 現場保留訊息(複審指出的第三個 gate 點)
    one_line(lum(root, v, "guard", "kill", "Systems/Limit", "--json", "--keep-worktree"),
             "keep-worktree")


def t_guard_kill_attribution():
    """[S3] 歸因四型 + rc 優先序 + json 純度 + 名字偽強殺反例。"""
    import subprocess as sp, json as _json, os

    def lum(root, v, *a):
        e = dict(os.environ); e["LUMOS_KILL_TIMEOUT_FLOOR"] = "5"
        return sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *a],
                      capture_output=True, text=True, cwd=root, env=e)

    def prep(root, v):
        r = lum(root, v, "guard", "kill-add", "Systems/Limit", "上限恆為5",
                "--file", "prod.py", "--old", "LIMIT = 5", "--new", "LIMIT = 99")
        assert r.returncode == 0, r.stderr

    # (a) 具名失敗 → killed 強歸因;摘錄含命中段
    root, v = _mk_attr_env(
        "import prod, sys\n"
        "print('collected 1 item')\n"
        "if prod.LIMIT != 5:\n"
        "    print('FAILURES')\n    print('TestLimitFive')\n    print('  x' * 200)\n"
        "    print('E   assert 99 == 5')\n    print('t.py:2: AssertionError')\n    sys.exit(1)\n"
        "print('ok')\n")
    prep(root, v)
    r = lum(root, v, "guard", "kill", "Systems/Limit", "--json")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("(a) killed 強歸因", d["results"][0]["verdict"] == "killed", d)
    check("(a) 帶歸因摘錄", "attr_excerpt" in d["results"][0], d["results"][0])
    check("(a) 摘錄截 200 字", len(d["results"][0].get("attr_excerpt", "")) <= 200,
          len(d["results"][0].get("attr_excerpt", "")))

    # (b) 匿名 crash → killed_unattributed + 警告
    root, v = _mk_attr_env(
        "import prod, sys\n"
        "if prod.LIMIT != 5:\n    print('Traceback: ImportError boom'); sys.exit(1)\n"
        "print('ok')\n")
    prep(root, v)
    r = lum(root, v, "guard", "kill", "Systems/Limit")
    check("(b) unattributed", "killed_unattributed" in r.stdout, r.stdout)
    check("(b) 印警告建議 filter", "filter" in r.stdout + r.stderr, r.stdout)
    check("(b) 非強殺措辭", "咬得住" not in r.stdout, r.stdout)
    check("(b) icon 非 ?", "? killed_unattributed" not in r.stdout, r.stdout)

    # (c) 逾時 → timed_out_weak,不計 killed
    root, v = _mk_attr_env(
        "import prod, time\n"
        "if prod.LIMIT != 5:\n    time.sleep(60)\n"
        "print('ok')\n")
    prep(root, v)
    r = lum(root, v, "guard", "kill", "Systems/Limit")
    check("(c) timed_out_weak", "timed_out_weak" in r.stdout, r.stdout)
    check("(c) 摘要印弱證據", "弱" in r.stdout, r.stdout)
    check("(c) icon timed_out_weak 非 ?", "? timed_out_weak" not in r.stdout, r.stdout)
    check("(c) 全弱證據 rc1(不 fail-open)", r.returncode == 1, str(r.returncode))

    # (c2) 鄰近他測失敗不得誤歸因給綁定測試(終審 Codex 反例)
    root, v = _mk_attr_env(
        "import prod, sys\n"
        "print('TestLimitFive PASSED')\n"
        "if prod.LIMIT != 5:\n    print('TestOther FAILED'); sys.exit(1)\n"
        "print('ok')\n")
    prep(root, v)
    sp.run(["git", "-C", str(root), "add", "-A"], capture_output=True)
    sp.run(["git", "-C", str(root), "commit", "-qm", "c2"], capture_output=True)
    r = lum(root, v, "guard", "kill", "Systems/Limit")
    check("(c2) 鄰近他測失敗→unattributed", "killed_unattributed" in r.stdout, r.stdout)

    # (d) 名字自帶標記 → 不得偽造強殺
    root, v = _mk_attr_env(
        "import prod, sys\n"
        "print('running TestFAILEDCase')\n"
        "if prod.LIMIT != 5:\n    sys.exit(1)\n"
        "print('ok')\n")
    sp.run(["git", "-C", str(root), "add", "-A"], capture_output=True)
    (v / "Systems" / "Limit.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n"
        "  KEY:★INVARIANT★ 上限恆為5,超過必拒 [test:TestFAILEDCase]\n---\n# Limit\n",
        encoding="utf-8")
    prep(root, v)
    r = lum(root, v, "guard", "kill", "Systems/Limit")
    check("(d) 名字自帶 FAILED 不算強殺", "killed_unattributed" in r.stdout, r.stdout)

    # (e) json 純度:dirty worktree 下 stdout 恰一行合法 JSON
    root, v = _mk_attr_env("import prod, sys\nsys.exit(0 if prod.LIMIT == 5 else 1)\n")
    prep(root, v)
    (root / "dirty.txt").write_text("x", encoding="utf-8")
    r = lum(root, v, "guard", "kill", "Systems/Limit", "--json")
    lines = [l for l in r.stdout.splitlines() if l.strip()]
    check("(e) dirty×json stdout 恰一行", len(lines) == 1, r.stdout[:300])
    check("(e) 該行可 parse", _json.loads(lines[0]) if lines else False, "")


def _mk_kill_env():
    """合成 git repo + vault + 一條綁 [test:] 的 INVARIANT + python run_cmd。
    prod.py 的 LIMIT 是被守衛行為;test_guard.py 斷言之。"""
    import subprocess as sp
    root = Path(tempfile.mkdtemp(prefix="gctl-kill-"))
    def g(*a):
        sp.run(["git", "-C", str(root), *a], capture_output=True, text=True)
    g("init", "-q"); g("config", "user.email", "t@t.t"); g("config", "user.name", "t")
    (root / "prod.py").write_text("LIMIT = 5\n\ndef check(n):\n    return n <= LIMIT\n", encoding="utf-8")
    (root / "test_guard.py").write_text(
        "import sys, prod\n"
        "def TestLimitFive():\n"
        "    assert prod.check(5) and not prod.check(6)\n"
        "TestLimitFive()\nprint('ok')\n", encoding="utf-8")
    (root / ".lumos").mkdir()
    (root / ".lumos" / "config.json").write_text(
        '{"test": {"run_cmd": "python3 test_guard.py"}}', encoding="utf-8")
    v = root / "docs" / "kg-knowledge"
    (v / "Systems").mkdir(parents=True)
    (v / "MOC").mkdir()
    (v / "MOC" / "i.md").write_text("---\ntype: moc\n---\n", encoding="utf-8")
    (v / "Systems" / "Limit.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n"
        "  KEY:★INVARIANT★ 上限恆為5,超過必拒 [test:TestLimitFive]\n---\n# Limit\n",
        encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "init")
    return root, v


def t_guard_kill():
    import subprocess as sp, json, os
    root, v = _mk_kill_env()
    def lum(*a, env_extra=None):
        e = dict(os.environ)
        e["LUMOS_KILL_TIMEOUT_FLOOR"] = "3"
        if env_extra:
            e.update(env_extra)
        return sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *a],
                      capture_output=True, text=True, cwd=root, env=e)

    # kill-add:寫後自驗 + KEY 行標記
    r = lum("guard", "kill-add", "Systems/Limit", "上限恆為5",
            "--file", "prod.py", "--old", "LIMIT = 5", "--new", "LIMIT = 99",
            "--note", "上限被放寬,超賣風險")
    check("kill-add rc0", r.returncode == 0, r.stderr)
    txt = (v / "Systems" / "Limit.md").read_text(encoding="utf-8")
    check("kill-add 寫入 kill_recipes+標記", "kill_recipes" in txt and "[kill:recipes]" in txt, txt[:400])
    # 重複配方拒絕
    r = lum("guard", "kill-add", "Systems/Limit", "上限恆為5",
            "--file", "prod.py", "--old", "LIMIT = 5", "--new", "LIMIT = 0")
    check("kill-add 重複拒絕 rc2", r.returncode == 2, str(r.returncode))
    # naked 合約 0 ref → rc2
    (v / "Systems" / "Naked.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n  KEY:★INVARIANT★ 裸合約無綁定\n---\n# N\n",
        encoding="utf-8")
    r = lum("guard", "kill-add", "Systems/Naked", "裸合約",
            "--file", "prod.py", "--old", "x", "--new", "y")
    check("kill-add naked rc2", r.returncode == 2, str(r.returncode))

    # kill:killed happy path(壞法讓測試翻紅)
    r = lum("guard", "kill", "Systems/Limit", "--json")
    check("kill killed rc0", r.returncode == 0, f"rc={r.returncode} {r.stdout[:200]} {r.stderr[:200]}")
    data = json.loads(r.stdout.strip().splitlines()[-1])
    check("kill verdict=killed", data["results"][0]["verdict"] == "killed", str(data))
    # 留痕
    klog = v.parent / ".kill-log.jsonl"
    check("kill-log 留痕", klog.exists() and "killed" in klog.read_text(encoding="utf-8"), "")
    # gov 第 5 支 load
    r = lum("gov")
    check("gov 撈得到 kill", "kill/killed" in r.stdout, r.stdout[-300:])

    # survived:綁一個不斷言的測試
    import subprocess as sp2
    (root / "test_straw.py").write_text("print('ok')\n", encoding="utf-8")
    (v / "Systems" / "Straw.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n"
        "  KEY:★INVARIANT★ 稻草人示範 [test:TestStraw]\n---\n# S\n", encoding="utf-8")
    sp2.run(["git", "-C", str(root), "add", "-A"], capture_output=True)
    sp2.run(["git", "-C", str(root), "commit", "-qm", "straw"], capture_output=True)
    # 用 config 覆寫 run_cmd 指向稻草人測試
    (root / ".lumos" / "config.json").write_text(
        '{"test": {"run_cmd": "python3 test_straw.py"}}', encoding="utf-8")
    r = lum("guard", "kill-add", "Systems/Straw", "稻草人示範",
            "--file", "prod.py", "--old", "LIMIT = 5", "--new", "LIMIT = 99")
    check("straw kill-add rc0", r.returncode == 0, r.stderr)
    r = lum("guard", "kill", "Systems/Straw")
    check("kill survived rc1(稻草人)", r.returncode == 1, f"rc={r.returncode} {r.stdout}")

    # drifted:old 漂移
    (root / ".lumos" / "config.json").write_text(
        '{"test": {"run_cmd": "python3 test_guard.py"}}', encoding="utf-8")
    (v / "Systems" / "Drift.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n"
        "  KEY:★INVARIANT★ 漂移示範 [test:TestLimitFive]\n---\n# D\n", encoding="utf-8")
    r = lum("guard", "kill-add", "Systems/Drift", "漂移示範",
            "--file", "prod.py", "--old", "LIMIT = 42", "--new", "LIMIT = 99")
    check("drift kill-add rc0", r.returncode == 0, r.stderr)
    r = lum("guard", "kill", "Systems/Drift")
    check("kill drifted rc2", r.returncode == 2, f"rc={r.returncode} {r.stdout}")

    # abort:baseline 紅(壞 run_cmd)
    (root / ".lumos" / "config.json").write_text(
        '{"test": {"run_cmd": "python3 -c \\"import sys;sys.exit(1)\\""}}', encoding="utf-8")
    r = lum("guard", "kill", "Systems/Limit")
    check("kill abort rc2(baseline紅)", r.returncode == 2, f"rc={r.returncode} {r.stdout}")

    # timed_out:壞法造成無窮迴圈 → 歸 killed 類 rc0
    (root / ".lumos" / "config.json").write_text(
        '{"test": {"run_cmd": "python3 test_guard.py"}}', encoding="utf-8")
    (v / "Systems" / "Hang.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n"
        "  KEY:★INVARIANT★ 掛死示範 [test:TestLimitFive]\n---\n# H\n", encoding="utf-8")
    r = lum("guard", "kill-add", "Systems/Hang", "掛死示範",
            "--file", "prod.py", "--old", "def check(n):",
            "--new", "import time\ndef check(n):\n    time.sleep(60)")
    check("hang kill-add rc0", r.returncode == 0, r.stderr)
    r = lum("guard", "kill", "Systems/Hang", "--json")
    check("kill timeout-only rc1(S3 刻意變更:全弱證據不 fail-open)", r.returncode == 1, f"rc={r.returncode} {r.stdout[:200]}")
    dd = json.loads(r.stdout.strip().splitlines()[-1])
    check("verdict=timed_out_weak(S3 刻意降級:timeout 不再計 killed)",
          dd["results"][0]["verdict"] == "timed_out_weak", str(dd))

    # 缺 run_cmd rc2
    (root / ".lumos" / "config.json").write_text('{}', encoding="utf-8")
    r = lum("guard", "kill", "Systems/Limit")
    check("kill 缺 run_cmd rc2", r.returncode == 2, str(r.returncode))
    (root / ".lumos" / "config.json").write_text(
        '{"test": {"run_cmd": "python3 test_guard.py"}}', encoding="utf-8")

    # 路徑圍欄:file 逃逸
    (v / "Systems" / "Esc.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n"
        "  KEY:★INVARIANT★ 逃逸示範 [test:TestLimitFive]\n---\n# E\n", encoding="utf-8")
    r = lum("guard", "kill-add", "Systems/Esc", "逃逸示範",
            "--file", "../../etc/hosts", "--old", "localhost", "--new", "evil")
    check("esc kill-add rc0(宣告不擋,跑時擋)", r.returncode == 0, r.stderr)
    r = lum("guard", "kill", "Systems/Esc")
    check("kill 圍欄擋逃逸 rc2(error)", r.returncode == 2 and "逃逸" in r.stdout, f"rc={r.returncode} {r.stdout}")

    # drifted:old 命中 2 次(殺 M1:cnt!=1 弱化成 cnt<1)
    (v / "Systems" / "Multi.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n"
        "  KEY:★INVARIANT★ 多重命中示範 [test:TestLimitFive]\n---\n# M\n", encoding="utf-8")
    r = lum("guard", "kill-add", "Systems/Multi", "多重命中示範",
            "--file", "prod.py", "--old", "n", "--new", "m")
    check("multi kill-add rc0", r.returncode == 0, r.stderr)
    r = lum("guard", "kill", "Systems/Multi", "--json")
    dd2 = json.loads(r.stdout.strip().splitlines()[-1])
    check("kill old 多重命中 → drifted(殺 M1)", dd2["results"][0]["verdict"] == "drifted"
          and "命中" in dd2["results"][0].get("detail", ""), str(dd2))

    # 圍欄:兄弟目錄前綴(../wt-x → startswith 無 sep 會誤放;殺 M2)
    (v / "Systems" / "Sib.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n"
        "  KEY:★INVARIANT★ 兄弟前綴示範 [test:TestLimitFive]\n---\n# Sib\n", encoding="utf-8")
    r = lum("guard", "kill-add", "Systems/Sib", "兄弟前綴示範",
            "--file", "../wt-evil/f.py", "--old", "x", "--new", "y")
    check("sib kill-add rc0", r.returncode == 0, r.stderr)
    r = lum("guard", "kill", "Systems/Sib", "--json")
    dd3 = json.loads(r.stdout.strip().splitlines()[-1])
    check("kill 兄弟前綴 → error 圍欄擋(殺 M2)", dd3["results"][0]["verdict"] == "error"
          and "逃逸" in dd3["results"][0].get("detail", ""), str(dd3))

    # worktree 清理:無殘留
    r = sp.run(["git", "-C", str(root), "worktree", "list"], capture_output=True, text=True)
    check("worktree 無殘留", r.stdout.strip().count("\n") == 0, r.stdout)

    # dirty 警告
    (root / "prod.py").write_text("LIMIT = 5\n\ndef check(n):\n    return n <= LIMIT\n# dirty\n", encoding="utf-8")
    r = lum("guard", "kill", "Systems/Limit")
    check("dirty 警告出現", "未提交變更" in r.stdout, r.stdout[:300])
    import shutil
    shutil.rmtree(root, ignore_errors=True)


def t_spec_trace_and_signoff():
    import subprocess as sp, json
    with tempfile.TemporaryDirectory() as d:
        v = Path(d) / "docs" / "x-knowledge"
        for sub_ in ("Projects", "Verification", "MOC"):
            (v / sub_).mkdir(parents=True)
        (v / "MOC" / "i.md").write_text("---\ntype: moc\n---\n", encoding="utf-8")
        (v / "Projects" / "P_計劃.md").write_text(
            "---\ntype: project\nstatus: doing\n---\n# P\n\n## 變更規格\n"
            "- [S1] 做 A\n- [S2] 做 B\n- [S3] 做 C\n", encoding="utf-8")
        (v / "Verification" / "V1.md").write_text(
            "---\ntype: verification\nstatus: pass\nplan_refs:\n  - \"[[P_計劃]]\"\n---\n"
            "# V1\n驗了 [S1] 與 [S2]。\n", encoding="utf-8")
        # 沒回指的 Verification 提及 S3 → 不算認領
        (v / "Verification" / "V2.md").write_text(
            "---\ntype: verification\nstatus: pass\n---\n# V2\n順帶提到 [S3]。\n", encoding="utf-8")
        def lum(*a):
            return sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *a],
                          capture_output=True, text=True)
        r = lum("spec-trace", "Projects/P_計劃", "--json")
        check("spec-trace 未認領 rc1", r.returncode == 1, f"rc={r.returncode} {r.stderr}")
        dd = json.loads(r.stdout.strip().splitlines()[-1])
        check("spec-trace S3 未認領(無回指不算)", dd["unclaimed"] == ["S3"], str(dd))
        check("spec-trace S1 認領者=V1", dd["clauses"]["S1"] == ["Verification/V1.md"], str(dd))
        # 補認領 → rc0
        (v / "Verification" / "V3.md").write_text(
            "---\ntype: verification\nstatus: pass\nplan_refs:\n  - \"[[P_計劃]]\"\n---\n"
            "# V3\n[S3] 落地。\n", encoding="utf-8")
        r = lum("spec-trace", "Projects/P_計劃")
        check("spec-trace 全認領 rc0", r.returncode == 0, r.stdout)
        # opt-in 未啟用
        (v / "Projects" / "Q_計劃.md").write_text(
            "---\ntype: project\nstatus: doing\n---\n# Q\n無標記。\n", encoding="utf-8")
        r = lum("spec-trace", "Projects/Q_計劃")
        check("spec-trace 無標記 rc0+提示", r.returncode == 0 and "opt-in" in r.stdout, r.stdout)

        # signoff
        r = lum("signoff", "Projects/P_計劃", "--note", "業務規則已對過帳", "--by", "enzo")
        check("signoff rc0", r.returncode == 0, r.stderr)
        txt = (v / "Projects" / "P_計劃.md").read_text(encoding="utf-8")
        check("signoff frontmatter 戳記", "signed_off:" in txt, txt[:200])
        slog = v.parent / ".signoff-log.jsonl"
        check("signoff ledger 一筆", slog.exists() and "enzo" in slog.read_text(encoding="utf-8"), "")
        r = lum("gov")
        check("gov 撈得到 signoff", "signoff/signed" in r.stdout, r.stdout[-300:])
        # 空 note 拒絕(殺 M3:必填弱化)
        r = lum("signoff", "Projects/P_計劃", "--note", "  ")
        check("signoff 空 note rc2(殺 M3)", r.returncode == 2, str(r.returncode))
        # 重簽:ledger 累加
        r = lum("signoff", "Projects/P_計劃", "--note", "第二次確認")
        check("signoff 重簽 rc0", r.returncode == 0, r.stderr)
        check("ledger 兩筆", slog.read_text(encoding="utf-8").count("\n") == 2, "")


def _mk_rank_vault():
    """檢索排序測試 vault:標題命中 vs body 命中、中文 bigram、欄位權重。"""
    d = Path(tempfile.mkdtemp(prefix="gctl-rank-"))
    v = d / "docs" / "r-knowledge"
    for sub_ in ("Systems", "MOC"):
        (v / sub_).mkdir(parents=True)
    (v / "MOC" / "i.md").write_text("---\ntype: moc\n---\n", encoding="utf-8")
    # A:標題含「檢索」;B:只有 body 深處含「檢索」×1;C:body 含「檢索」×5(飽和測試)
    (v / "Systems" / "檢索引擎.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n  KEY:排序核心\ntags:\n  - type/system\n---\n# 檢索引擎\n無關內文。\n",
        encoding="utf-8")
    (v / "Systems" / "Alpha.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n  KEY:別的\n---\n# Alpha\n這裡提到檢索一次。\n",
        encoding="utf-8")
    (v / "Systems" / "Beta.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n  KEY:別的\n---\n# Beta\n"
        + "檢索兩次:檢索。\n", encoding="utf-8")   # tf=2<標題權重4(spec 只保證同 tf 標題勝;洗詞歸評測調參)
    (v / "Systems" / "Mixed.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n  KEY:impact_hook 相關\n---\n# Mixed\nimpact_hook 出現處。\n",
        encoding="utf-8")
    # MOC hub:標題也含「檢索」——A1 型別先驗該把它壓到 system 標題命中之下
    (v / "MOC" / "檢索索引.md").write_text(
        "---\ntype: moc\n---\n# 檢索索引\n檢索相關節點列表。\n", encoding="utf-8")
    return d, v


def t_doctor_flags_unclosed_frontmatter():
    """★2026-08-03 code-loop r4 抓到的既有 major★:`split_frontmatter` 假設 frontmatter
    成對——少一個收尾 `---` 就回 `(None, 整份檔)`,於是★整份檔(含 frontmatter)當 body
    索引★。實測後果有三:

      ① 該節點的 ★INVARIANT★ ★從 contracts 完全消失★(合約登記簿靜默少一條)
      ② block scalar 裡的 `[[wikilink]]` 變成★真的架構圖邊★(frontmatter 鐵則 2 靜默失效)
      ③ `doctor` 輸出★完全不提這個檔★——連 Check S 的清單都沒有它(讀不到 type)

    ★寫入端 `load_raw_for_edit` 對同一狀態明確 `raise ValueError("frontmatter 未閉合")`,
    讀取端卻默默照收★。修法不動解析語意(那會牽動一堆讀取端),而是★把讀取端的沉默
    補成響亮★:doctor 新增一道檢查,且放★硬 issue★——它會讓 pre-push 的 `doctor --ci`
    擋下來,因為「靜默少一條合約」正是本工具最不能接受的事。

    ★翻紅釘★:把該段檢查整段移除 → 三條主斷言翻紅。"""
    import subprocess as sp, tempfile as _tf
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-fmbroken-"))
    v = root / "docs" / "demo-knowledge"
    for sub in ("Systems", "Projects", "Issues", "Verification", "MOC"):
        (v / sub).mkdir(parents=True, exist_ok=True)
    def lum(*a):
        return sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *a],
                      capture_output=True, text=True)

    (v / "Systems/good.md").write_text(
        "---\ntype: system\nstatus: done\ntags:\n  - type/system\n"
        "summary: |-\n  KEY:★INVARIANT★ 正常節點的硬合約 [test:t_ok]\n---\n# good\n正常。\n",
        encoding="utf-8")
    # ★未閉合★:少了收尾的 ---
    (v / "Systems/broken.md").write_text(
        "---\ntype: system\nstatus: done\ntags:\n  - type/system\n"
        "summary: |-\n  KEY:★INVARIANT★ 這條會不會蒸發 [test:t_ghost]\n"
        "# broken\n提到 [[Systems/good]]。\n", encoding="utf-8")

    # ★前置★ 現場成立:三個症狀都要真的發生,否則這條測試在測一個不存在的問題
    rc_ = lum("contracts")
    check("★前置★ 現場成立:broken 的硬合約確實從 contracts 蒸發了",
          "t_ghost" not in rc_.stdout and "t_ok" in rc_.stdout, rc_.stdout)
    rb = lum("backlinks", "Systems/good")
    check("★前置★ 現場成立:block scalar 裡的連結確實變成了真邊",
          "broken" in rb.stdout, rb.stdout)

    rd = lum("doctor")
    check("★doctor 必須指名道姓點出未閉合的那一篇(不得靜默)★",
          "broken.md" in rd.stdout, rd.stdout)
    check("★而且要講清楚後果(不是只說格式錯)★",
          "合約" in rd.stdout and "架構圖邊" in rd.stdout, rd.stdout)
    rci = lum("doctor", "--ci")
    check("★必須是硬 issue——pre-push 的 doctor --ci 要擋得下來★",
          rci.returncode != 0, f"rc={rci.returncode}\n{rci.stdout[-400:]}")

    # 正常 vault 不得誤報
    (v / "Systems/broken.md").unlink()
    rd2 = lum("doctor")
    check("★正常 vault 不得誤報(沒 frontmatter 的檔也不算)★",
          "沒有未閉合的 frontmatter" in rd2.stdout, rd2.stdout)


def t_indented_closing_fence_never_swallows_real_claims():
    """★2026-08-03 code-loop r4 潛伏缺陷獵人席抓到的既有 major★:
    `FENCE_RE = re.compile(r"^```.*?^```", re.S|re.M)` ★錨在第 0 欄★——收尾圍欄
    只要縮排一格,就會跟★下一個區塊的開頭★錯配,把中間的真散文★整段當程式碼吞掉★。

    ★為什麼比未閉合圍欄那條更嚴重★:它餵的是治理機制本身——
      `_refcheck_scan` → `loop status --gate` 的 **G1 硬閘**
      `_impact_reverse_lookup` → **Edit/Write 前自動注入「必看合約」的 hook**
    ★一個縮排的 ``` 就能把某節點的鐵則警告靜默關掉,或讓 G1 對著真的有壞引用的
    spec 宣告通過★。

    ★修法約束(非顯然)★:不能用 `_strip_code_text`——它連 inline code 一起剝,而
    refcheck 要抽的路徑宣稱★正是寫在 inline code 裡★。故另立 `_strip_fences_text`
    (只剝圍欄、留 inline),兩者共用唯一的 `_visible_lines` fence 判定。

    ★翻紅釘★:把 `_refcheck_scan` 改回成對正則 `re.sub(r"(?ms)^```.*?^```","",text)`
    → 「縮排收尾之後的宣稱也要被看到」翻紅(只會抽到第一條)。"""
    import subprocess as sp, tempfile as _tf
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-fence2-"))
    v = root / "docs" / "demo-knowledge"
    for sub in ("Systems", "Projects", "Issues", "Verification", "MOC"):
        (v / sub).mkdir(parents=True, exist_ok=True)
    (root / "scripts").mkdir(parents=True, exist_ok=True)
    (root / "scripts" / "real.py").write_text("x = 1\n", encoding="utf-8")
    sp.run(["git", "init", "-q", "."], cwd=root, capture_output=True)

    # ★關鍵現場★:第一個圍欄開在第 0 欄、★收尾縮排 2 格★
    spec = v / "Systems/payA.md"
    spec.write_text(
        "---\ntype: system\nstatus: done\ntags:\n  - type/system\n---\n"
        "# payA\n正文提到 `scripts/real.py` 這個檔。\n"
        "```\n示範程式碼\n  ```\n"
        "真散文提到 `scripts/ghost.py` 這個不存在的檔。\n"
        "```\n另一段\n```\n", encoding="utf-8")
    r = sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "refcheck", str(spec),
                "--repo", str(root)], capture_output=True, text=True)

    check("★前置★ 現場成立:第一個圍欄的收尾★真的是縮排的★(否則測不到錯配)",
          "\n  ```\n" in spec.read_text(encoding="utf-8"), spec.read_text(encoding="utf-8"))
    check("★前置★ 現場成立:圍欄★之前★那條宣稱本來就抽得到(基準)",
          "scripts/real.py" in r.stdout, r.stdout)
    check("★縮排收尾★之後★的真宣稱也必須被看到(舊實作會整段吞掉)★",
          "scripts/ghost.py" in r.stdout, r.stdout)
    check("★而且要正確判定它 missing(不是靜默略過)★",
          "missing" in r.stdout and "ghost.py" in r.stdout, r.stdout)


def t_unclosed_fence_never_leaks_into_graph_or_evidence():
    """★2026-08-03 code-loop r2 全局哨兵抓到的兩條既有 major★——同一個「未閉合 ``` 圍欄」
    的坑,原本散在四處實作,其中兩處後果比 search 嚴重得多:

    ① `load_vault()`:未閉合圍欄裡的 `[[wikilink]]` 被當成★真的架構圖邊★索引進去
       → 幽靈連結進入持久化的圖結構(`backlinks` 會多報一條)。
    ② `cmd_guard_trace()`:未閉合圍欄裡的測試名被當成★合約的真實佐證★
       → 污染 ★INVARIANT★→[test:]→Verification 證據鏈,打臉該指令自己的保證。

    根因都是 `FENCE_RE` 是成對非貪婪比對,★看不見未閉合的圍欄★。修法=改用
    `_strip_code_text`(與主搜尋共用逐行 toggle 的單一實作)。

    ★爆炸半徑實測=0★:修的當下全庫 220 篇沒有任何一篇有未閉合圍欄,現有的邊與
    證據鏈一個字都不會變——這是純防未來。因此本測試必須★自己造一篇未閉合圍欄的
    節點★當現場,否則什麼都驗不到(第⑤型:fixture 產不出有鑑別力的值)。

    ★翻紅釘★:把兩處改回 `INLINE_CODE_RE.sub("", FENCE_RE.sub("", ...))` → 兩條主斷言各翻紅。"""
    import subprocess as sp, tempfile as _tf
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-fence-"))
    v = root / "docs" / "demo-knowledge"
    for sub in ("Systems", "Projects", "Issues", "Verification", "MOC"):
        (v / sub).mkdir(parents=True, exist_ok=True)
    def lum(*a):
        return sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *a],
                      capture_output=True, text=True)

    (v / "Systems/target.md").write_text(
        "---\ntype: system\nstatus: done\ntags:\n  - type/system\n---\n# target\n目標節點。\n",
        encoding="utf-8")
    # ★未閉合圍欄★——圍欄之後的 [[target]] 只是貼進來的程式碼範例,不是真的連結
    (v / "Systems/leaky.md").write_text(
        "---\ntype: system\nstatus: done\ntags:\n  - type/system\n---\n"
        "# leaky\n下面貼一段範例,忘了收尾:\n```\n這行是範例: [[target]]\n",
        encoding="utf-8")

    r = lum("backlinks", "Systems/target.md")
    check("★前置★ 現場成立:leaky.md 真的有未閉合圍欄(奇數個 ``` 標記)",
          (v / "Systems/leaky.md").read_text(encoding="utf-8").count("```") % 2 == 1,
          (v / "Systems/leaky.md").read_text(encoding="utf-8"))
    check("★① 未閉合圍欄裡的 [[wikilink]] 不得被當成真的架構圖邊(幽靈連結)★",
          "leaky" not in r.stdout, r.stdout)

    # ② guard trace:未閉合圍欄裡的測試名不得被當成合約佐證
    (v / "Systems/guarded.md").write_text(
        "---\ntype: system\nstatus: done\ntags:\n  - type/system\n"
        "summary: |-\n  KEY:★INVARIANT★ 示範用硬合約 [test:t_demo_guard_xyz]\n---\n"
        "# guarded\n內文。\n", encoding="utf-8")
    (v / "Verification/2026-08-03_demo.md").write_text(
        "---\ntype: verification\nstatus: pass\ndate: 2026-08-03\ntags:\n  - type/verification\n---\n"
        "# demo\n這篇★沒有★真的驗過那個守衛,只是貼了一段忘了收尾的 log:\n"
        "```\n某段輸出提到 t_demo_guard_xyz 這個名字\n", encoding="utf-8")
    # ★這裡第一版是假綠(第 13 次),記為教訓★:原本呼叫 `guard trace t_demo_guard_xyz`
    # ——但該指令吃的是★節點★不是測試名,實際回「ERROR: 找不到節點」,Verification
    # 掃描那條路★一次都沒跑到★,把修法還原成 FENCE_RE 照樣全綠。
    # ★通則(第④型的又一個面貌)★:現場不成立的原因可以只是「指令用法就錯了」——
    # 而錯用法的輸出(ERROR)剛好也不含斷言要找的字串,於是斷言「碰巧」成立。
    # 修法:①改用正確的節點參數 ②前置斷言必須確認★那條路真的產出了證據鏈輸出★
    #      (看得到 `[test:...]  →` 這個箭頭),而不只是「fixture 檔案裡有那個字」。
    r2 = lum("guard", "trace", "Systems/guarded")
    check("★前置★ 現場成立:guard trace 真的跑到了證據鏈掃描(輸出有 [test:…] → 這一段)",
          "[test:t_demo_guard_xyz]" in r2.stdout and "→" in r2.stdout, r2.stdout)
    check("★② 未閉合圍欄裡的測試名不得被當成合約的真實佐證★",
          "2026-08-03_demo" not in r2.stdout, r2.stdout)
    check("★② 且必須明講「無 Verification 提到此守衛」(而不是靜默空白)★",
          "無 Verification 提到此守衛" in r2.stdout, r2.stdout)


def t_search_multiword_fallback_scope_message_covers_path_and_superseded():
    """★2026-08-03 code-loop r2(codex minor / seatA major,依規矩取高)★:
    回退訊息宣稱的範圍★不得大於實際檢查的範圍★。

    同一個錯當天被抓到★三次★:
      r1:片語只在作廢節點時說「全庫無命中」(其實有,只是被藏)
      r2:`--path` 限定時仍說「未作廢的節點裡/全庫」(其實只掃了那個子集)
      r2:第二句硬寫的「有詞在★全庫★ 0 命中」同一個毛病
    ★用一個維度描述範圍,另一個維度就不在視野裡★——本測試把兩個維度都釘住。

    ★翻紅釘★:把 `_sc` 的 path_prefix 那半拿掉 → ★只有「必須揭露路徑範圍」那一條翻紅★。
    (原 docstring 寫「那兩條翻紅」是★過度宣稱★,r3 審查員實跑打臉:另一條
    「不得宣稱全庫」在突變後照樣綠——因為拿掉 path 那半之後訊息仍然沒說「全庫」。
    ★同一天第 N 次:宣稱的東西比實際驗過的多。連翻紅釘的條數都要實跑過再寫。★)"""
    import subprocess as sp, tempfile as _tf
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-scope-"))
    v = root / "docs" / "demo-knowledge"
    for sub in ("Systems", "Projects", "Issues", "Verification", "MOC"):
        (v / sub).mkdir(parents=True, exist_ok=True)
    def note(rel, body):
        (v / rel).write_text("---\ntype: system\nstatus: done\ntags:\n  - type/system\n---\n" + body,
                             encoding="utf-8")
    note("Systems/s1.md", "# s1\n這裡談子丑,也談寅卯。\n")
    note("Projects/p1.md", "# p1\n這裡只談子丑。\n")
    def lum(*a):
        return sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *a],
                      capture_output=True, text=True)

    r = lum("search", "子丑 寅卯", "--path", "Projects", "--files-only")
    check("★前置★ 現場成立:限定 Projects 後回退真的觸發了", "多詞回退" in r.stderr, r.stderr)
    check("★前置★ 現場成立:「寅卯」在 Systems 找得到——所以「全庫 0 命中」會是假話",
          "s1.md" in lum("search", "寅卯", "--files-only").stdout, "fixture 壞了")
    check("★--path 限定時,訊息必須揭露路徑範圍★",
          "Projects" in r.stderr, r.stderr)
    check("★--path 限定時不得宣稱「全庫」★", "全庫" not in r.stderr, r.stderr)
    r2 = lum("search", "子丑 寅卯", "--files-only")
    check("★沒有 --path 時,訊息不得憑空冒出路徑範圍★",
          "底下" not in r2.stderr and "未作廢的節點的可見文字裡無命中" in r2.stderr, r2.stderr)

    # ★第四個維度:--code(r3 抓到)★——預設不搜程式碼區塊,說「節點裡無命中」不精確。
    # ★這段第一版是假綠(第 14 次,r4 Codex 實跑打臉)★:原 fixture 讓完整片語在
    # code fence 裡★找得到★,於是加 --code 後根本★不觸發回退★,`(含程式碼區塊)`
    # 那個分支一次都沒執行;斷言只檢查「成功搜尋的 stderr 不含可見文字」——那必然
    # 成立,因為壓根沒有回退訊息。★又是第④型,而且是我為了修上一輪 finding 剛寫的。★
    # 修法:現場改成「即使含程式碼區塊,片語仍不連續」,回退在兩種模式下都會觸發,
    # 只有★範圍措辭★與★逐詞覆蓋數★會變——後者(午未 0→1)是額外的鑑別力來源。
    note("Systems/s2.md", "# s2\n一般文字提到辰巳。\n")
    note("Systems/s3.md", "# s3\n這裡是程式碼:\n```\n午未 只出現在程式碼區塊\n```\n")
    r3 = lum("search", "辰巳 午未", "--files-only")
    check("★前置★ 現場成立:預設時回退觸發", "多詞回退" in r3.stderr, r3.stderr)
    check("★前置★ 現場成立:預設看不見程式碼區塊,故「午未」覆蓋為 0",
          "★午未:0★" in r3.stderr, r3.stderr)
    check("★預設時必須講明範圍是「可見文字」(程式碼區塊不算)★",
          "可見文字" in r3.stderr, r3.stderr)
    r4 = lum("search", "辰巳 午未", "--code", "--files-only")
    check("★前置★ 現場成立:加 --code 後★仍然觸發回退★(片語依然不連續)——"
          "這才走得到 include_code 那個分支", "多詞回退" in r4.stderr, r4.stderr)
    check("★前置★ 現場成立:加 --code 後「午未」看得見了(覆蓋 0→1),證明 --code 真的生效",
          "午未:1" in r4.stderr and "★午未:0★" not in r4.stderr, r4.stderr)
    check("★加 --code 時範圍必須說「(含程式碼區塊)」★",
          "(含程式碼區塊)" in r4.stderr, r4.stderr)
    check("★加 --code 時不得再說「可見文字」★", "可見文字" not in r4.stderr, r4.stderr)


def t_search_multiword_fallback_r1_three_majors():
    """★2026-08-03 code-loop r1 抓到的三條 major,一條一組斷言★。

    ①「全庫無命中」措辭自相矛盾(slot3 major / slot2 minor,依規矩取高):
      預檢刻意跳過 superseded(對的),但片語★只★在一篇作廢節點裡時,舊措辭印
      「整串片語全庫無命中」,緊接著又印「已隱藏 1 筆作廢結果」——★兩行打架★,
      使用者只看第一行會斷定「架構圖沒這東西」→ 可能重造一個已存在的節點。

    ②未閉合 ``` 圍欄下,預檢與主迴圈判斷分岔(slot3,附實測):兩份實作——主迴圈逐行
      toggle(圍欄後全隱形)、預檢整段 regex(剝不掉懸空半段)。後果是★逐詞覆蓋虛報
      非零★,直接打臉 M1.5「告訴你哪個詞 0 命中」的存在理由。修法=抽 `_search_visible_lines`
      給兩邊共用,★不是補正則★。

    ③(在 governance/eval/retrieval_eval_multiword.py,非本檔範圍)對照臂要顯式 --no-any。

    ★翻紅釘★:①把 `_scope_txt` 改回寫死「全庫無命中」→ ① 翻紅;
    ②把預檢改回自己 regex 剝 fence → ② 翻紅。"""
    import subprocess as sp, tempfile as _tf
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-mwr1-"))
    v = root / "docs" / "demo-knowledge"
    for sub in ("Systems", "Projects", "Issues", "Verification", "MOC"):
        (v / sub).mkdir(parents=True, exist_ok=True)
    def note(rel, body, status="done"):
        (v / rel).write_text(f"---\ntype: system\nstatus: {status}\ntags:\n  - type/system\n---\n" + body,
                             encoding="utf-8")
    def lum(*a):
        return sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *a],
                      capture_output=True, text=True)

    # ── ① 片語只在作廢節點 ──
    note("Systems/dead.md", "# dead\n這裡有 壬癸 甲乙 這個片語。\n", status="superseded")
    note("Systems/live1.md", "# live1\n這裡只提到壬癸。\n")
    note("Systems/live2.md", "# live2\n這裡只提到甲乙。\n")
    r = lum("search", "壬癸 甲乙", "--files-only")
    check("★前置★ 現場成立:回退真的觸發了", "多詞回退" in r.stderr, r.stderr)
    check("★前置★ 現場成立:確實有 1 筆被當作廢藏起來(否則①在測不成立的現場)",
          "已隱藏 1 筆作廢結果" in r.stderr, r.stderr)
    check("★① 不得宣稱「全庫無命中」——片語其實存在,只是被歸檔了★",
          "全庫無命中" not in r.stderr, r.stderr)
    check("★① 必須講清楚範圍是「未作廢的節點」★",
          "未作廢的節點" in r.stderr and "無命中" in r.stderr, r.stderr)
    # --include-superseded 時範圍才真的是全庫
    r2 = lum("search", "壬癸 甲乙", "--include-superseded", "--files-only")
    check("★① --include-superseded 時片語找得到,不該回退★",
          "多詞回退" not in r2.stderr and "dead.md" in r2.stdout, f"OUT:{r2.stdout}\nERR:{r2.stderr}")

    # ── ② 未閉合圍欄:覆蓋數必須與逐詞搜尋一致 ──
    root2 = _P(_tf.mkdtemp(prefix="gctl-mwr1b-"))
    v2 = root2 / "docs" / "demo-knowledge"
    for sub in ("Systems", "Projects", "Issues", "Verification", "MOC"):
        (v2 / sub).mkdir(parents=True, exist_ok=True)
    # 未閉合圍欄之後才出現「戊己」——主迴圈視為 code(搜不到)
    (v2 / "Systems/fence.md").write_text(
        "---\ntype: system\nstatus: done\ntags:\n  - type/system\n---\n"
        "# fence\n這裡提到庚辛。\n```\n戊己 在未閉合圍欄之後\n", encoding="utf-8")
    (v2 / "Systems/plain.md").write_text(
        "---\ntype: system\nstatus: done\ntags:\n  - type/system\n---\n"
        "# plain\n這裡提到庚辛。\n", encoding="utf-8")
    def lum2(*a):
        return sp.run([sys.executable, GRAPHCTL, "--vault", str(v2), *a],
                      capture_output=True, text=True)
    n_alone = lum2("search", "戊己", "--files-only").stdout.count(".md")
    check("★前置★ 現場成立:「戊己」在未閉合圍欄之後,單獨搜必須是 0 篇"
          "(否則②在測一個不成立的現場)", n_alone == 0,
          f"單獨搜「戊己」={n_alone} 篇\n{lum2('search','戊己','--files-only').stdout}")
    r3 = lum2("search", "庚辛 戊己", "--files-only")
    check("★前置★ 現場成立:回退觸發了(才有覆蓋可看)", "多詞回退" in r3.stderr, r3.stderr)
    check("★② 覆蓋數不得虛報:單獨搜 0 篇的詞,覆蓋也必須是 0★",
          "★戊己:0★" in r3.stderr, r3.stderr)


def t_search_multiword_fallback_reports_per_term_coverage():
    """★M1.5(2026-08-02,Landmark 284 篇真庫實測逼出來的)★:回退觸發時,把逐詞覆蓋
    印到 stderr。

    ★為什麼需要★:回退之後搜尋★幾乎不可能再回 0★——你永遠會拿到看起來合理的東西,
    而那可能只是常見詞的噪音。今天「0 筆」至少有時候代表「這個概念不在架構圖裡」,
    回退把那個訊號吃掉了。實例:Landmark 上查「續會 門檻 計算」第一名是「停車折抵」,
    看起來像排序爛——其實是「續會」全庫 0 篇(我查詢用詞猜錯),剩下兩個常見詞
    (門檻 50/計算 35)把結果洗走。逐詞覆蓋一印就當場看穿。
    ★這條買的是「把消失的訊號用另一種形式還回來」,不是「排序變準」。★

    ★最強的一條斷言是「覆蓋數必須與逐詞搜尋一致」★:預檢那圈與主迴圈是兩份實作,
    很容易漂移。實測就抓到一次——預檢原本沒套用「隱藏作廢節點」的過濾,覆蓋數
    比實際搜得到的多(門檻 55 vs 50,差在 7 筆 superseded)。★覆蓋數若>實際,使用者
    會以為「這個詞有東西」而其實搜不到,誤導方向與本功能要解的問題正好相反。★

    ★翻紅釘★:拿掉覆蓋輸出 → ①②翻紅;拿掉預檢的 superseded 過濾 → ④翻紅。"""
    import subprocess as sp, tempfile as _tf
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-mwcov-"))
    v = root / "docs" / "demo-knowledge"
    for sub in ("Systems", "Projects", "Issues", "Verification", "MOC"):
        (v / sub).mkdir(parents=True, exist_ok=True)
    def note(rel, body, status="done"):
        (v / rel).write_text(f"---\ntype: system\nstatus: {status}\ntags:\n  - type/system\n---\n" + body,
                             encoding="utf-8")
    # 「戊」出現在 3 篇,★其中 1 篇是 superseded(該被排除)★;「己」1 篇;「庚」0 篇
    note("Systems/n1.md", "# n1\n這裡談戊。\n")
    note("Systems/n2.md", "# n2\n這裡也談戊。\n")
    note("Systems/n3.md", "# n3\n這篇談戊但已作廢。\n", status="superseded")
    note("Systems/n4.md", "# n4\n這裡談己。\n")
    def lum(*a):
        return sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *a],
                      capture_output=True, text=True)

    r = lum("search", "戊 己 庚", "--any", "--files-only")
    check("★前置★ 現場成立:回退真的觸發了(否則以下都在測沒發生的事)",
          "多詞回退" in r.stderr, f"OUT:{r.stdout}\nERR:{r.stderr}")
    # ① 有印覆蓋
    check("★① 回退觸發時要印逐詞覆蓋★", "逐詞覆蓋" in r.stderr, r.stderr)
    # ② 0 命中的詞要標星 + 額外提示
    check("★② 全庫 0 命中的詞要標記出來(這是本功能的核心價值)★",
          "★庚:0★" in r.stderr, r.stderr)
    check("★② 並提醒「多半是用詞不一致」,別把結果當「架構圖沒有」★",
          "用詞與架構圖用語不一致" in r.stderr, r.stderr)
    # ③ 走 stderr,不得污染 stdout
    check("★③ 覆蓋資訊只走 stderr,stdout 一個字都不能有★",
          "逐詞覆蓋" not in r.stdout and "多詞回退" not in r.stdout, r.stdout)
    # ④ ★覆蓋數必須與逐詞搜尋一致(superseded 要被排除)★
    n_wu = lum("search", "戊", "--files-only").stdout.count(".md")
    check("★前置★ 現場成立:「戊」有 superseded 篇存在,逐詞搜尋才會與未過濾版不同",
          n_wu == 2, f"單獨搜「戊」= {n_wu} 篇(期望 2:n1/n2,n3 已作廢被藏)")
    check("★④ 覆蓋數必須與逐詞搜尋完全一致(預檢與主迴圈是兩份實作,會漂移)★",
          f"戊:{n_wu}" in r.stderr, f"逐詞搜尋={n_wu}\nstderr:{r.stderr}")

    # ⑤ 回退沒觸發時不得印(片語存在)
    note("Systems/n5.md", "# n5\n這裡有連續的 辛 壬 片語。\n")
    r2 = lum("search", "辛 壬", "--any", "--files-only")
    check("★前置★ 現場成立:片語「辛 壬」真的找得到(回退不該觸發)",
          "n5.md" in r2.stdout, r2.stdout)
    check("★⑤ 回退沒觸發時,一個字都不該印★",
          "逐詞覆蓋" not in r2.stderr and "多詞回退" not in r2.stderr, r2.stderr)


def t_search_multiword_fallback_is_default_and_only_on_zero():
    """★2026-08-02:多詞查詢回退(Projects/檢索多詞回退_計劃 M1)★。

    背景:候選階段是整串子字串比對,`search "甲 乙 丙"` 只要那三個字沒連在一起出現過
    就是 0 候選——而 BM25F 本身完全會處理多詞,壞的是前面撈候選那道關卡。

    ★2026-08-03 人裁翻預設★:回退改為預設開,`--no-any` 逃生。證據見
    Projects/檢索多詞回退_計劃 M4(nDCG@5 0→0.767、MRR 0.95、第一名必看 7/10;
    對照組 5 題逐檔完全相同)。★本測試的 ② 因此從「預設必須維持 0」改成
    「`--no-any` 必須維持 0」——★方向相反,是刻意的行為變更,不是弱化★。

    ★這條測試守的是三件事,缺一不可★:
    ① 預設能把「原本 0 候選」的多詞查詢救回來(修好了沒)
    ② ★`--no-any` 必須回到舊行為(0 候選)★——逃生口要真的逃得掉
    ③ ★fallback-only:片語真的存在時,回退絕不能觸發★
       這條最重要。若寫成「永遠 OR」,`_rank_score_candidates` 的 N/df/avgdl
       ★以候選集為語料★,擴召回會擾動所有既有查詢的排序——零回歸就不成立了。

    ★翻紅釘★:拿掉回退整段 → ① 翻紅;把 `if not _fb_seen:` 拿掉(變成永遠 OR)
    → ③ 翻紅(存在片語的查詢會多撈到只含單詞的檔);把 `--no-any` 接線拿掉
    → ② 翻紅(逃生口失效)。"""
    import subprocess as sp, tempfile as _tf
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-mwfb-"))
    v = root / "docs" / "demo-knowledge"
    for sub in ("Systems", "Projects", "Issues", "Verification", "MOC"):
        (v / sub).mkdir(parents=True, exist_ok=True)
    def note(rel, body):
        (v / rel).write_text("---\ntype: system\nstatus: done\ntags:\n  - type/system\n---\n" + body,
                             encoding="utf-8")
    # alpha 有「甲」與「乙」但★不相鄰★;beta 只有「甲」(→ ① 的現場)
    # gamma 含★多詞且連續★的片語「丙 丁」;delta 只含「丙」(→ ③ 的現場)
    # ★③ 的現場第一版是錯的,記為教訓(本專案第 12 次撞「測試假綠」)★:原本用「丙丁」
    # (單一 token、中間無空白)當片語,於是 `len(_fb_terms) > 1` 這道閘直接判假、
    # OR 路徑★一次都沒被執行★——把 fallback-only 守衛拿掉(改成永遠 OR)那個翻紅釘
    # ★照樣全綠★。這正是 Systems/測試假綠形態 第④型「現場走不到被測分支」,
    # 而且是這條測試自己犯的。要驗「不得偷偷 OR」,現場必須★真的是多詞★,
    # 而且要存在一個「只含其中一詞」的檔可被誤撈,否則沒有鑑別力。
    note("Systems/alpha.md", "# alpha\n甲的說明在這裡。\n另一段講乙的事。\n")
    note("Systems/beta.md", "# beta\n只提到甲,沒有別的。\n")
    note("Systems/gamma.md", "# gamma\n這裡有連續的 丙 丁 片語。\n")
    note("Systems/delta.md", "# delta\n這裡只提到丙,沒有另一個字。\n")
    def lum(*a):
        return sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *a],
                      capture_output=True, text=True)

    # ★前置★ 現場成立:單詞查詢本來就找得到(否則下面在測一個壞掉的 vault)
    r = lum("search", "甲", "--files-only")
    check("★前置★ 現場成立:單詞「甲」找得到 2 篇", r.stdout.count(".md") == 2, r.stdout)

    # ② --no-any 逃生:回到舊行為
    r = lum("search", "甲 乙", "--no-any", "--files-only")
    check("★--no-any 必須回到舊行為(0 候選)——逃生口要真的逃得掉★",
          "候選 0" in r.stdout or ".md" not in r.stdout, r.stdout)

    # ① 預設就救得回來(2026-08-03 起)
    r = lum("search", "甲 乙", "--files-only")
    check("★預設:原本 0 候選的多詞查詢救得回來★", "alpha.md" in r.stdout, r.stdout)
    check("★用 OR 不是 AND(只含「甲」的 beta 也該進候選)★", "beta.md" in r.stdout, r.stdout)
    r_flag = lum("search", "甲 乙", "--any", "--files-only")
    check("★`--any` 保留相容:帶不帶結果必須一樣(它已是預設,不得變成別的意思)★",
          r_flag.stdout == r.stdout, f"預設:\n{r.stdout}\n--any:\n{r_flag.stdout}")

    # ③ ★fallback-only★:片語真的存在時不得回退
    r_plain = lum("search", "丙 丁", "--no-any", "--files-only")
    check("★前置★ 現場成立:多詞片語「丙 丁」本來就找得到(否則③在測一個不成立的現場)",
          "gamma.md" in r_plain.stdout, r_plain.stdout)
    check("★前置★ 現場成立:它★真的是多詞★——存在一個只含單詞的 delta,"
          "若偷偷 OR 就會被誤撈進來,這樣③才驗得出東西",
          "delta.md" not in r_plain.stdout, r_plain.stdout)
    r_any = lum("search", "丙 丁", "--files-only")
    check("★fallback-only:片語存在時,結果必須與關掉回退完全相同(沒有偷偷擴召回)★",
          sorted(l for l in r_any.stdout.splitlines() if ".md" in l)
          == sorted(l for l in r_plain.stdout.splitlines() if ".md" in l),
          f"plain:\n{r_plain.stdout}\nany:\n{r_any.stdout}")

    # 單詞:無多詞可拆,開關都不影響
    r1 = lum("search", "甲", "--files-only")
    r2 = lum("search", "甲", "--no-any", "--files-only")
    check("★單詞查詢開不開回退都一樣(沒有多詞可拆)★", r1.stdout == r2.stdout,
          f"{r1.stdout}\n---\n{r2.stdout}")

    # --regex 不受影響
    r = lum("search", "甲|乙", "--regex", "--files-only")
    check("★--regex 不得走回退(候選語意不同)★",
          r.returncode == 0 and "多詞回退" not in r.stderr, f"rc={r.returncode}\n{r.stderr[:200]}")


def t_impact_contract_risk_axis():
    """[標籤結構優化 2026-08-05]risk/ 家族接 impact 固定席——risk 標(金流/對外送出/不可逆/
    守衛面)的節點被 diff 碰到時保送必看席(★RISK·值★),light 硬否決的 honor-system 有了
    機械眼線。軸序:IRREVERSIBLE > INVARIANT > RISK(合約仍優先)。
    翻紅釘:拔 risk 軸 → ①翻紅。"""
    m = _load_lumos_module()
    class _N:
        def __init__(self, fields):
            self.fields = fields
            self.stem = "x"
    # 只有 risk 標 → contract=RISK·金流
    n1 = _N({"tags": ["type/system", "risk/金流"], "summary": "KEY:x"})
    c1, _ = m._impact_contract(n1)
    check("★risk 標節點=固定席資格(RISK·金流)★", c1 == "RISK·金流", repr(c1))
    # INVARIANT 優先於 risk
    n2 = _N({"tags": ["type/system", "risk/金流"],
             "summary": "KEY:★INVARIANT★ 某合約 [test:t_x]"})
    c2, _ = m._impact_contract(n2)
    check("合約軸優先於 risk 軸", c2 == "INVARIANT", repr(c2))
    # 無任何標 → None(行為不變)
    n3 = _N({"tags": ["type/system"], "summary": "KEY:x"})
    c3, _ = m._impact_contract(n3)
    check("無標節點行為不變(None)", c3 is None, repr(c3))


def t_context_header_extra_tag_families():
    """[標籤結構優化 2026-08-05,Enzo:「是給你看的」]context 頭部顯示 type/status 以外的
    tag 家族(priority/scope/feature/area/flag/risk)——實測 gap:節點標了 priority/P1,
    進場 context 頭部完全不顯,寫給 AI 看的資訊在 AI 的主要讀路徑上隱形。
    翻紅釘:拔頭部彙總 → ①翻紅。"""
    v = mkvault()
    (v / "Issues").mkdir(exist_ok=True)
    (v / "Issues" / "標籤展示.md").write_text(
        "---\ntype: issue\nstatus: open\ncreated: 2026-08-01\nupdated: 2026-08-01\n"
        "tags:\n  - type/issue\n  - status/open\n  - priority/P1\n  - scope/pointsmall\n"
        "  - flag/do-not-modify\nsummary: |-\n  KEY:x\n---\n# 標籤展示\n", encoding="utf-8")
    r = run(v, "context", "Issues/標籤展示", "--brief")
    head = "\n".join(r.stdout.splitlines()[:4])
    check("★context 頭部顯示 priority/scope/flag 家族★",
          "priority:P1" in head and "scope:pointsmall" in head and "flag:do-not-modify" in head,
          head)
    (v / "Issues" / "素節點.md").write_text(
        "---\ntype: issue\nstatus: open\ncreated: 2026-08-01\nupdated: 2026-08-01\n"
        "tags:\n  - type/issue\n  - status/open\nsummary: |-\n  KEY:x\n---\n# 素節點\n",
        encoding="utf-8")
    r2 = run(v, "context", "Issues/素節點", "--brief")
    check("無額外家族時頭部不變(零噪音)", r2.returncode == 0
          and "priority" not in r2.stdout.splitlines()[1], r2.stdout[:150])


def t_lint_tag_value_enums():
    """[標籤結構優化 2026-08-05]值域執法——Landmark 實測野化(status 13 值/FLAG 50+ 自由文字)。
    cutoff 制(同 aliases 宣告制,created ≥ 2026-08-06 的新節點才擋,舊帳不回溯):
    ①status 依 type 給合法值集 ②summary FLAG: 行收回 TECHNICAL/DECISION/ORIGIN 三值
    ③priority tag 只認 P0-P3 ④risk tag 只認 金流/對外送出/不可逆/守衛面。
    翻紅釘:拔 enum 檢查 → 各斷言翻紅。"""
    v = mkvault()
    def mk(name, fm_extra, summary="  KEY:x"):
        (v / "Systems" / f"{name}.md").write_text(
            f"---\ntype: system\nstatus: doing\ncreated: 2026-08-06\nupdated: 2026-08-06\n"
            f"aliases: []\n{fm_extra}tags:\n  - type/system\nsummary: |-\n{summary}\n---\n# {name}\n",
            encoding="utf-8")
    # status 非法值
    (v / "Systems" / "壞status.md").write_text(
        "---\ntype: system\nstatus: shipping\ncreated: 2026-08-06\nupdated: 2026-08-06\n"
        "aliases: []\ntags:\n  - type/system\nsummary: |-\n  KEY:x\n---\n# 壞status\n", encoding="utf-8")
    r = run(v, "lint", "壞status")
    check("★新節點 status 非法值=lint error★", r.returncode == 1 and "status" in r.stdout, r.stdout[:200])
    # FLAG 野值(issue)
    (v / "Issues").mkdir(exist_ok=True)
    (v / "Issues" / "壞FLAG.md").write_text(
        "---\ntype: issue\nstatus: open\ncreated: 2026-08-06\nupdated: 2026-08-06\n"
        "aliases: []\ntags:\n  - type/issue\nsummary: |-\n  FLAG:P2已解決\n  KEY:x\n---\n# 壞FLAG\n",
        encoding="utf-8")
    r2 = run(v, "lint", "壞FLAG")
    check("★新節點 FLAG 野值=lint error(收回三值,內容移 KEY 行)★",
          r2.returncode == 1 and "FLAG" in r2.stdout, r2.stdout[:200])
    # priority 野值
    mk("壞priority", "")
    p = v / "Systems" / "壞priority.md"
    p.write_text(p.read_text(encoding="utf-8").replace("  - type/system", "  - type/system\n  - priority/urgent"), encoding="utf-8")
    r3 = run(v, "lint", "壞priority")
    check("★priority 只認 P0-P3★", r3.returncode == 1 and "priority" in r3.stdout, r3.stdout[:200])
    # 合法組合全過
    mk("好節點", "")
    g = v / "Systems" / "好節點.md"
    g.write_text(g.read_text(encoding="utf-8").replace("  - type/system", "  - type/system\n  - priority/P1\n  - risk/金流\n  - scope/points"), encoding="utf-8")
    check("合法值全過(priority/P1+risk/金流+scope 自由值)", run(v, "lint", "好節點").returncode == 0, "")
    # 舊帳不回溯
    (v / "Systems" / "舊野值.md").write_text(
        "---\ntype: system\nstatus: shipping\ncreated: 2026-08-01\nupdated: 2026-08-01\n"
        "tags:\n  - type/system\nsummary: |-\n  FLAG:隨便寫\n  KEY:x\n---\n# 舊野值\n", encoding="utf-8")
    check("舊帳(cutoff 前)不回溯", run(v, "lint", "舊野值").returncode == 0, "")


def t_canary_type_probe_fields():
    """[D 前置 2026-08-05,Enzo 裁]植入型別與探針結果結構化——原散文 note 不可重算,
    攢十輪也是考古材料。record 加 --canary-type/--probe 選配欄(T1 慣例:不給不寫鍵、
    行為不變);canary-stats 加型別×探針×caught 表。D 本體開工條件=帶型別記錄攢滿 15 筆
    (可重算,同防浮動條款款式)。翻紅釘:拔欄位寫入 → 落帳斷言翻紅。"""
    import json as _j
    v = mkvault()
    lid = f"ct-{_M1U}"
    run(v, "canary", "record", "caught", "--loop", lid, "--auditor", "s1", "--severity", "minor",
        "--canary-type", "resource", "--probe", "recraft2-fail", expect_rc=0)
    run(v, "canary", "record", "missed", "--loop", lid, "--auditor", "s2", "--severity", "minor",
        "--canary-type", "off-by-one", "--probe", "pass", expect_rc=0)
    run(v, "canary", "record", "caught", "--loop", lid, "--auditor", "s3", "--severity", "minor", expect_rc=0)
    recs = [_j.loads(l) for l in (v.parent / ".canary-log.jsonl").read_text(encoding="utf-8").splitlines()
            if l.strip() and _j.loads(l).get("loop") == lid]
    check("★--canary-type/--probe 落帳★", recs[0].get("canary_type") == "resource"
          and recs[0].get("probe") == "recraft2-fail", str(recs[0])[:200])
    check("★不給不寫鍵(相容鐵則)★", "canary_type" not in recs[2] and "probe" not in recs[2],
          str(recs[2])[:200])
    r = run(v, "loop", "canary-stats", lid)
    check("★canary-stats 型別表:型別×探針×caught 可讀★", r.returncode == 0
          and "resource" in r.stdout and "recraft2-fail" in r.stdout and "off-by-one" in r.stdout,
          r.stdout[:400])


def t_panel_k2_and_probe():
    """[A 案落地](plan:Projects/panel收斂判準改革_計劃;design-loop r1+r2 已收斂)

    ①K=2:cutoff(2026-08-06,env LUMOS_PANEL_K2_CUTOFF 可覆寫)起的新 panel loop,
      收斂=★最後兩輪各自★過三條合取;單一乾淨輪 FAIL(訊息帶 K=2)。
    ②舊帳不回溯:首筆 ts < cutoff 的 loop 沿 K=1(env 拉高 cutoff 模擬)。
    ③抽查判定(e'):PASS 時印決定性判定——sha256(loop_id+判定輪 token 集)%2,
      任何人可重算;兩次呼叫同值(冪等)。
    ④撤銷自動化:PASS 後抽查輪(probe-*)冒 major → 重問 gate 自然 FAIL(K=2 窗滑入髒輪)。
    翻紅釘:拔 K=2 窗 → ①翻紅;拔 cutoff 判定 → ②翻紅。"""
    import subprocess as _sp
    import os as _os
    v = mkvault()
    envK2 = dict(_os.environ, LUMOS_PANEL_K2_CUTOFF="2000-01-01")   # 讓「今天的 loop」吃新制
    def runk2(*a):
        return _sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *a],
                       capture_output=True, text=True, env=envK2)
    lid = f"k2a-{_M1U}"
    def clean_round(rid):
        for aud in ("s1", "s2"):
            r = runk2("canary", "record", "caught", "--loop", lid, "--round", rid,
                      "--auditor", aud, "--severity", "minor",
                      *((("--capture-counts", "1"),)[0] if aud == "s1" else ()))
            assert r.returncode == 0, r.stderr
    clean_round("r1")
    g1 = runk2("loop", "status", lid, "--gate", "--panel", "--repo", str(v.parent))
    check("★K=2:單一乾淨輪 FAIL 且訊息帶 K=2★", g1.returncode == 1 and "K=2" in g1.stdout,
          f"rc={g1.returncode}\n{g1.stdout[:400]}")
    clean_round("r2")
    g2 = runk2("loop", "status", lid, "--gate", "--panel", "--repo", str(v.parent))
    check("★K=2:連續兩乾淨輪 PASS★", g2.returncode == 0, f"rc={g2.returncode}\n{g2.stdout[:400]}")
    check("★PASS 印決定性抽查判定(應抽/免抽)★", "抽查" in g2.stdout, g2.stdout[:400])
    g2b = runk2("loop", "status", lid, "--gate", "--panel", "--repo", str(v.parent))
    line = [l for l in g2.stdout.splitlines() if "抽查" in l]
    lineb = [l for l in g2b.stdout.splitlines() if "抽查" in l]
    check("抽查判定冪等(兩次呼叫同值=可重算)", line and line == lineb, f"{line} vs {lineb}")
    # ④ 撤銷自動化:抽查輪冒 major → 窗滑入 → FAIL
    r = runk2("canary", "record", "caught", "--loop", lid, "--round", "probe-r3",
              "--auditor", "s1", "--severity", "major", "--capture-counts", "1")
    assert r.returncode == 0, r.stderr
    r2 = runk2("canary", "record", "caught", "--loop", lid, "--round", "probe-r3",
               "--auditor", "s2", "--severity", "minor")
    g3 = runk2("loop", "status", lid, "--gate", "--panel", "--repo", str(v.parent))
    check("★抽查輪冒 major → gate 自然撤銷 PASS(FAIL)★", g3.returncode == 1,
          f"rc={g3.returncode}\n{g3.stdout[:300]}")
    # ② 舊帳不回溯(cutoff 拉到未來 → 今天的 loop=舊制 K=1)
    envOld = dict(_os.environ, LUMOS_PANEL_K2_CUTOFF="9999-12-31")
    lid2 = f"k2b-{_M1U}"
    for aud, extra in (("s1", ("--capture-counts", "1")), ("s2", ())):
        _sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "canary", "record", "caught",
                 "--loop", lid2, "--round", "r1", "--auditor", aud, "--severity", "minor", *extra],
                capture_output=True, text=True, env=envOld)
    gold = _sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "loop", "status", lid2,
                    "--gate", "--panel", "--repo", str(v.parent)],
                   capture_output=True, text=True, env=envOld)
    check("★舊帳不回溯:cutoff 前 loop 單乾淨輪照舊 PASS(K=1)★", gold.returncode == 0,
          f"rc={gold.returncode}\n{gold.stdout[:300]}")


def t_pitfalls_diff_skips_review_report_artifacts():
    """[2026-08-05 C 慣例實戰首擋]歸檔的審計證物(governance/review-reports/ 下的席報告與
    canary 快照 .patch——裡面★故意★埋著資源/併發 bug)被 pitfalls --diff 當成代碼掃,
    tier 直接 high、push 被自己的留痕擋下。修=掃描排除 governance/review-reports/ 路徑
    (證物是文字紀錄,不是要合入的碼)。收緊釘:review-reports 外的同型 .patch/.py 照掃。"""
    import subprocess as _sp
    with tempfile.TemporaryDirectory() as d:
        g = lambda *a: _sp.run(["git", *a], cwd=d, capture_output=True, text=True)
        g("init", "-q", "-b", "main")
        g("config", "user.email", "t@t.t")
        g("config", "user.name", "t")
        (Path(d) / "README.md").write_text("init\n", encoding="utf-8")
        g("add", "-A"); g("commit", "-qm", "init")
        g("checkout", "-qb", "feat")
        rr = Path(d) / "governance" / "review-reports" / "code-x"
        rr.mkdir(parents=True)
        (rr / "r1-snapshot.patch").write_text(
            "+++ b/app.py\n+import requests\n+fh = open('x')\n+requests.post('http://x')\n",
            encoding="utf-8")
        g("add", "-A"); g("commit", "-qm", "archive artifacts")
        r = _sp.run([sys.executable, GRAPHCTL, "pitfalls", "--diff", "main..HEAD",
                     "--no-lint", "--json", "--repo", d], capture_output=True, text=True)
        import json as _j
        data = _j.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
        check("★review-reports 下的證物不掃(tier 不因歸檔變 high)★",
              data.get("tier") != "high" and not data.get("claims"),
              f"tier={data.get('tier')} claims={data.get('claims')}")
        # 收緊釘:同內容放在 review-reports 外照掃
        (Path(d) / "app_real.py").write_text("import requests\nrequests.post('http://x')\n",
                                             encoding="utf-8")
        g("add", "-A"); g("commit", "-qm", "real code")
        r2 = _sp.run([sys.executable, GRAPHCTL, "pitfalls", "--diff", "main..HEAD",
                      "--no-lint", "--json", "--repo", d], capture_output=True, text=True)
        data2 = _j.loads([l for l in r2.stdout.splitlines() if l.strip().startswith("{")][0])
        check("★收緊釘:真代碼照掃(排除不外溢)★", data2.get("tier") == "high",
              f"tier={data2.get('tier')}")


def t_pitfalls_diff_skips_bookkeeping_ledgers():
    """[2026-08-11 遞迴誤判實錄]簿記帳(docs/.governance-log.jsonl 等)被 pitfalls --diff
    當代碼掃——治理帳裡記的 skip 理由本身在★描述★「pitfalls 命中 open(...)」,掃描器
    掃到自己的歷史紀錄再次命中,tier 變 high 擋 push,只好再 skip 一次、再寫一行理由進
    治理帳……自我餵食的迴圈,實測已誤觸發 9 次。修=比照 review-reports 排除簿記檔白名單
    (與 code-loop 留痕豁免共用 _BOOKKEEPING_* 常數,避免兩處漂移)。收緊釘:同內容在白名單
    外照掃。"""
    import subprocess as _sp
    with tempfile.TemporaryDirectory() as d:
        g = lambda *a: _sp.run(["git", *a], cwd=d, capture_output=True, text=True)
        g("init", "-q", "-b", "main")
        g("config", "user.email", "t@t.t")
        g("config", "user.name", "t")
        (Path(d) / "README.md").write_text("init\n", encoding="utf-8")
        g("add", "-A"); g("commit", "-qm", "init")
        g("checkout", "-qb", "feat")
        led = Path(d) / "docs"
        led.mkdir(parents=True)
        # 治理帳一行:理由文字裡引用了會觸發 [資源] pattern 的字樣(真實形態)
        (led / ".governance-log.jsonl").write_text(
            '{"gate": "code-loop", "kind": "skipped", "detail": "假陽性:命中 fh = open(\'x\') '
            '——one-shot 程序退出即釋放"}\n', encoding="utf-8")
        (Path(d) / "governance" / "code-loop").mkdir(parents=True)
        (Path(d) / "governance" / "code-loop" / "main.json").write_text(
            '{"note": "fh = open(\'y\') 假陽"}\n', encoding="utf-8")
        g("add", "-A"); g("commit", "-qm", "ledger append")
        r = _sp.run([sys.executable, GRAPHCTL, "pitfalls", "--diff", "main..HEAD",
                     "--no-lint", "--json", "--repo", d], capture_output=True, text=True)
        import json as _j
        data = _j.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])
        check("★簿記帳不掃(治理帳/code-loop 留痕不該把自己的理由掃成新命中)★",
              data.get("tier") != "high" and not data.get("claims"),
              f"tier={data.get('tier')} claims={data.get('claims')}")
        # 收緊釘:同內容在白名單外照掃
        (Path(d) / "app_real.py").write_text("fh = open('x')\n", encoding="utf-8")
        g("add", "-A"); g("commit", "-qm", "real code")
        r2 = _sp.run([sys.executable, GRAPHCTL, "pitfalls", "--diff", "main..HEAD",
                      "--no-lint", "--json", "--repo", d], capture_output=True, text=True)
        data2 = _j.loads([l for l in r2.stdout.splitlines() if l.strip().startswith("{")][0])
        check("★收緊釘:真代碼照掃(排除不外溢)★",
              any(c.get("file") == "app_real.py" for c in (data2.get("claims") or [])),
              f"claims={data2.get('claims')}")


def t_lint_decisions_nested_list_not_false_positive():
    """[Landmark 回填實戰抓到 2026-08-05]lint 的 decisions 結構守衛把 alternatives_considered
    ★巢狀清單★的 - 項也算進原始條數(raw=5 vs parsed=2)→照 ADR 規範寫 alternatives 清單
    反而被誤報「結構壞損」。修=原始計數只認 entry 縮排層(^␣␣-),巢狀(≥4 空格)不計。
    收緊釘:真壞型(sibling 被吞成 content 空)照樣要抓。"""
    v = mkvault()
    (v / "Systems" / "正規ADR.md").write_text(
        "---\ntype: system\nstatus: done\ncreated: 2026-08-01\nupdated: 2026-08-01\n"
        "tags:\n  - type/system\nsummary: |-\n  KEY:x\n"
        "decisions:\n"
        "  - content: 選 A 方案\n"
        "    context: 背景\n"
        "    alternatives_considered:\n"
        "      - B 方案:太貴\n"
        "      - C 方案:太慢\n"
        "      - D 方案:不相容\n"
        "    why_chosen: 便宜\n"
        "    trade_offs: 要維護\n"
        "    decided: 2026-08-01\n"
        "    valid: true\n"
        "  - content: 第二條決策\n"
        "    decided: 2026-08-01\n"
        "    valid: true\n"
        "---\n# 正規ADR\n", encoding="utf-8")
    r = run(v, "lint", "正規ADR")
    check("★照 ADR 規範的巢狀 alternatives 清單不得誤報結構壞損★", r.returncode == 0,
          f"rc={r.returncode}\n{r.stdout[:300]}")
    # 收緊釘:真壞型(id 縮排吞進 content block→content 空)照樣抓
    (v / "Systems" / "真壞型.md").write_text(
        "---\ntype: system\nstatus: done\ncreated: 2026-08-01\nupdated: 2026-08-01\n"
        "tags:\n  - type/system\nsummary: |-\n  KEY:x\n"
        "decisions:\n"
        "  - 純字串不是dict\n"
        "  - content: 好的\n"
        "    decided: 2026-08-01\n"
        "    valid: true\n"
        "---\n# 真壞型\n", encoding="utf-8")
    r2 = run(v, "lint", "真壞型")
    check("★收緊釘:entry 非 dict 被靜默丟(raw 2/parsed 1)照樣報★", r2.returncode == 1
          and "decisions" in r2.stdout, f"rc={r2.returncode}\n{r2.stdout[:200]}")


def t_lint_aliases_declared():
    """[aliases 硬性化 2026-08-05,Enzo 裁定]逼「判過」不逼「有值」——system/issue 新節點
    (created ≥ 2026-08-05)必須★有 aliases 鍵★;`aliases: []`=明示「判過,無同義詞」合法。
    直接逼「必須有別名」會製造湊數別名,而 aliases 吃 3.5 檢索權重,爛別名主動污染排序
    ——同「不確定就不標」精神。舊節點不回溯(created 早於 cutoff 不管);verification/project 豁免。
    翻紅釘:拔檢查 → 缺鍵案例翻紅。"""
    v = mkvault()
    (v / "Systems" / "新缺鍵.md").write_text(
        "---\ntype: system\nstatus: doing\ncreated: 2026-08-05\nupdated: 2026-08-05\n"
        "tags:\n  - type/system\nsummary: |-\n  KEY:x\n---\n# 新缺鍵\n", encoding="utf-8")
    r = run(v, "lint", "新缺鍵")
    check("★新 system 缺 aliases 鍵=lint error(逼判過)★", r.returncode == 1 and "aliases" in r.stdout,
          f"rc={r.returncode}\n{r.stdout[:200]}")
    (v / "Systems" / "新明示空.md").write_text(
        "---\ntype: system\nstatus: doing\ncreated: 2026-08-05\nupdated: 2026-08-05\n"
        "aliases: []\ntags:\n  - type/system\nsummary: |-\n  KEY:x\n---\n# 新明示空\n", encoding="utf-8")
    check("★aliases: [] 明示空=合法(判過無同義詞)★",
          run(v, "lint", "新明示空").returncode == 0, "")
    (v / "Systems" / "舊節點.md").write_text(
        "---\ntype: system\nstatus: done\ncreated: 2026-08-01\nupdated: 2026-08-01\n"
        "tags:\n  - type/system\nsummary: |-\n  KEY:x\n---\n# 舊節點\n", encoding="utf-8")
    check("舊節點(cutoff 前)不回溯", run(v, "lint", "舊節點").returncode == 0, "")
    (v / "Projects" / "新計劃.md").write_text(
        "---\ntype: project\nstatus: doing\ncreated: 2026-08-06\nupdated: 2026-08-06\n"
        "tags:\n  - type/project\n---\n# 新計劃\n", encoding="utf-8")
    check("project 型別豁免", run(v, "lint", "新計劃").returncode == 0, "")
    # 模板起步天然合規
    run(v, "new", "system", "模板起步", expect_rc=0)
    check("★lumos new 模板自帶 aliases 欄→起步即合規★",
          run(v, "lint", "模板起步").returncode == 0, "")


def t_loop_canary_stats():
    """[d4 承諾的後半 2026-08-05]跨輪 canary 累積帳的★讀取面★——record 寫入面 T1-T7 落地後,
    missed 率/席位慣性/連續 missed 一直只能人翻 JSONL(「機制蓋好沒人用」病的入口)。
    `lumos loop canary-stats [<loop-id>]`:席位×caught/missed×尾端連續 missed streak;
    連續 missed ≥2 印升級提示(「連 2 missed 升 opus」規則的機械眼);純唯讀恆 rc0,壞行跳過並註記。
    翻紅釘:把 streak 計算改成總數 → 升級提示斷言翻紅。"""
    import json as _j
    v = mkvault()
    lid = f"cs-{_M1U}"
    for kind, aud in (("caught", "s1"), ("missed", "s2"), ("caught", "s1"),
                      ("missed", "s2"), ("caught", "s3")):
        run(v, "canary", "record", kind, "--loop", lid, "--auditor", aud,
            "--severity", "minor", expect_rc=0)
    (v.parent / ".canary-log.jsonl").open("a", encoding="utf-8").write("{bad\n")
    r = run(v, "loop", "canary-stats", lid)
    check("canary-stats rc0(唯讀觀測)", r.returncode == 0, r.stderr[:200])
    check("★席位分帳:s1=2 caught、s2=2 missed、s3=1 caught★",
          "s1" in r.stdout and "s2" in r.stdout and "s3" in r.stdout
          and "2" in r.stdout, r.stdout[:400])
    check("★連續 missed ≥2 印升級提示(連2missed升opus的機械眼)★",
          "s2" in r.stdout and ("升" in r.stdout or "escalate" in r.stdout), r.stdout[:400])
    check("壞行跳過並註記(不炸不擋)", "壞行" in r.stdout or "1 行不可解析" in r.stdout, r.stdout[:400])
    # 全域視圖(無 loop-id):列出各 loop 摘要
    r2 = run(v, "loop", "canary-stats")
    check("無參數=全 loop 摘要視圖", r2.returncode == 0 and lid in r2.stdout, r2.stdout[:300])


def t_source_repo_reinject_path():
    """[2026-08-05 實戰缺口]來源 repo 自身沒有 reinject 路徑——update 拒跑(ERROR)、
    init 既有 vault 在來源 repo 走「跳過 vendor/hooks」時連 _do_reinject 一起跳過
    (2026-08-04 範本更新後,來源 repo 自己的 CLAUDE.md 只能直呼內部函式才刷新)。
    修:①update 在來源 repo 改走 reinject-only(範本本地即最新,無 pull 之需)
    ②init 既有 vault 的來源-repo 分支照樣 reinject。
    翻紅釘:還原「跳過」分支 → 斷言②翻紅。"""
    import subprocess as sp
    import os
    d = Path(tempfile.mkdtemp(prefix="gctl-src-"))
    repo = d / "srcrepo"
    (repo / "scripts" / "templates").mkdir(parents=True)
    (repo / ".git").mkdir()
    v = repo / "docs" / "kg-knowledge"
    for sub_ in ("Systems", "MOC"):
        (v / sub_).mkdir(parents=True)
    (v / "MOC" / "i.md").write_text("---\ntype: moc\n---\n", encoding="utf-8")
    (repo / "scripts" / "templates" / "graph-discipline.md").write_text(
        "紀律內容 v2(指向 {{KG}})\n", encoding="utf-8")
    (repo / "CLAUDE.md").write_text(
        "<!-- LUMOS:GRAPH-DISCIPLINE:START v1.0 — x -->\n舊內容 v1\n<!-- LUMOS:GRAPH-DISCIPLINE:END -->\n"
        "使用者手寫區(不得動)\n", encoding="utf-8")
    env2 = dict(os.environ, LUMOS_HOME=str(repo))
    # ① update 在來源 repo:reinject-only rc0(原:ERROR rc2)
    r = sp.run([sys.executable, GRAPHCTL, "update"], capture_output=True, text=True,
               cwd=str(repo), env=env2)
    body = (repo / "CLAUDE.md").read_text(encoding="utf-8")
    check("★update 在來源 repo=reinject-only rc0(原:拒跑)★",
          r.returncode == 0 and "紀律內容 v2" in body, f"rc={r.returncode} {r.stderr[:150]}")
    check("sentinel 外使用者內容 byte-equal 保留", "使用者手寫區(不得動)" in body, body[-100:])
    # ② init 既有 vault 在來源 repo:照樣 reinject
    (repo / "scripts" / "templates" / "graph-discipline.md").write_text(
        "紀律內容 v3(指向 {{KG}})\n", encoding="utf-8")
    r2 = sp.run([sys.executable, GRAPHCTL, "init"], capture_output=True, text=True,
                cwd=str(repo), env=env2)
    body2 = (repo / "CLAUDE.md").read_text(encoding="utf-8")
    check("★init 既有 vault 在來源 repo 照樣 reinject(原:跳過分支連 reinject 一起跳)★",
          r2.returncode == 0 and "紀律內容 v3" in body2, f"rc={r2.returncode}\n{r2.stdout[:200]}")


