def t_impact_hook_stack_questions():
    """棧別效能追問 T2:hook 格式化 lumos 輸出的 stack_questions(單源在 lumos,hook 不持有表);
    僅 stack_questions 無 results 也注入;兩者皆空不注入。"""
    import contextlib
    import io
    from importlib.machinery import SourceFileLoader
    from pathlib import Path as _P
    hook_path = str(_P(__file__).resolve().parent / "hooks" / "claude" / "impact-hook.py")
    loader = SourceFileLoader("impact_hook_sq_mod", hook_path)
    import importlib.util as _iu
    spec = _iu.spec_from_loader("impact_hook_sq_mod", loader)
    m = _iu.module_from_spec(spec)
    loader.exec_module(m)

    data = {"results": [], "meta": {},
            "stack_questions": {"kt": ["問一?", "問二?", "問三?"]}}
    txt = m.build_ranked_context(data)
    check("hook 文字含效能檢核段", "效能檢核" in txt and "問二?" in txt, txt)

    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        m.inject_ranked_context(data)
    check("僅 stack_questions 也注入", "additionalContext" in buf.getvalue(), buf.getvalue()[:120])
    check("僅提問時不接「判上列節點」指令(答非所問)", "上列直接/間接節點" not in txt, txt)
    txt_with_nodes = m.build_ranked_context(
        {"results": [{"node": "Systems/x", "kind": "direct", "pinned": False, "score": 0.5}],
         "meta": {}, "stack_questions": {"kt": ["問?"]}})
    check("有節點時仍接指令", "上列直接/間接節點" in txt_with_nodes, txt_with_nodes)

    buf2 = io.StringIO()
    with contextlib.redirect_stdout(buf2):
        m.inject_ranked_context({"results": [], "meta": {}})
    check("兩者皆空不注入", buf2.getvalue() == "", buf2.getvalue()[:80])
    print("  ✓ t_impact_hook_stack_questions")


def t_e2_ledger_tz_boundary():
    """E2 ledger 抑制的時區跨日 bug(2026-07-20 台北凌晨實抓):ledger ts=UTC、ended=本地日期,
    台北 00:00-08:00 窗口 UTC 日期還在昨天 → raw [:10] 比較誤判「判定早於翻案」→ 判過照樣重報。
    修法=比較點把 UTC ts 轉本地日期再比。本測試手造「本地今日 00:00 的 UTC 表示」當 transition ts:
    UTC+N(N>0) 環境必觸發舊 bug;UTC 環境退化為無害通過。"""
    import datetime as _dt
    import json as _json
    v = mkvault()
    write(v, "Projects/D.md", "type: project\nstatus: done")
    run(v, "decision-add", "D", "舊路線", "--decided", "2026-07-01", expect_rc=0)
    write(v, "Systems/A.md",
          "type: system\nstatus: done\nupdated: 2026-07-02\n"
          "summary: |-\n  KEY:★INVARIANT★ 假合約 [test:t_x]\n"
          "verified_by:\n  - \"[[Projects/D]]\"")
    run(v, "decision-supersede", "D", "舊路線", "--by", "新路線", expect_rc=0)
    gid = "Projects/D.md#d1"
    rcd = v / "governance" / "rel-cascade"
    cid_file = sorted(rcd.glob("*.jsonl"))[0]
    run(v, "rel-cascade", "prune", "A", "--cascade-id", cid_file.stem, "--from", gid,
        "--edge", "verified_by", "--by", "human", expect_rc=0)
    # 竄改 transition ts → 本地今日 00:00 的 UTC iso(非 UTC 時區下其日期字串=昨天)
    local_mid = _dt.datetime.now().astimezone().replace(hour=0, minute=0, second=0, microsecond=0)
    utc_ts = local_mid.astimezone(_dt.timezone.utc).isoformat(timespec="seconds")
    out = []
    for ln in cid_file.read_text(encoding="utf-8").splitlines():
        o = _json.loads(ln)
        if o.get("event") == "transition":
            o["ts"] = utc_ts
        out.append(_json.dumps(o, ensure_ascii=False))
    cid_file.write_text("\n".join(out) + "\n", encoding="utf-8")
    r = run(v, "doctor")
    check("E2 時區跨日:本地今日的判定(UTC 表示為昨日)不得重報",
          "無「建在被推翻決策上」的落後邊" in r.stdout, r.stdout)
    print("  ✓ t_e2_ledger_tz_boundary")


import secrets as _sec
_M1U = _sec.token_hex(3)   # m1 測試 loop id 唯一後綴(canary-log 落共用 tempdir,跨執行累積)


def _sha256_of(p):
    import hashlib
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def t_m1_cost_fields():
    """M1包 #4 成本選配欄(Projects/loop機械脊椎M1包_計劃):數值寫入/負值 rc2/不給不寫鍵/status 顯示。"""
    print("t_m1_cost_fields")
    v = mkvault()
    r = run(v, "canary", "record", "caught", "--loop", f"mc-{_M1U}", "--severity", "minor",
            "--findings", "1", "--tokens", "5000", "--wallclock-min", "12", expect_rc=0)
    log = (v.parent / ".canary-log.jsonl") if not (v / ".canary-log.jsonl").exists() else (v / ".canary-log.jsonl")
    import json as _j
    lines = [_j.loads(x) for x in (v.parent / ".canary-log.jsonl").read_text(encoding="utf-8").splitlines() if x.strip()]
    rec = [d for d in lines if d.get("loop") == f"mc-{_M1U}"][-1]
    check("成本欄寫入", rec.get("tokens") == 5000 and rec.get("wallclock_min") == 12)
    r = run(v, "canary", "record", "caught", "--loop", f"mc-{_M1U}", "--severity", "minor", "--tokens", "-3")
    check("負值 rc2", r.returncode == 2, f"rc={r.returncode}")
    run(v, "canary", "record", "caught", "--loop", f"mc2-{_M1U}", "--severity", "minor", "--findings", "0", expect_rc=0)
    lines = [_j.loads(x) for x in (v.parent / ".canary-log.jsonl").read_text(encoding="utf-8").splitlines() if x.strip()]
    rec2 = [d for d in lines if d.get("loop") == f"mc2-{_M1U}"][-1]
    check("不給不寫鍵", "tokens" not in rec2 and "wallclock_min" not in rec2)
    r = run(v, "loop", "status", f"mc-{_M1U}", "--need", "1")
    check("status 顯示成本區", "tokens" in r.stdout or "成本" in r.stdout)
    r = run(v, "loop", "status", f"mc2-{_M1U}", "--need", "1")
    check("全無成本欄不印", "成本" not in r.stdout)


def t_m1_hash_chain():
    """M1包 #3 雙 hash 鏈:同現規則/OSError/收斂窗鏈續性/半帶/同輪 result 分裂/聲明式 FAIL。"""
    print("t_m1_hash_chain")
    v = mkvault()
    spec = v / "Projects" / "hspec.md"
    spec.write_text("v1 內容\n", encoding="utf-8")
    h_v1 = _sha256_of(spec)
    # 同現規則:單給任一 rc2
    r = run(v, "canary", "record", "caught", "--loop", f"hc-{_M1U}", "--severity", "minor", "--spec", str(spec))
    check("--spec 孤給 rc2", r.returncode == 2)
    r = run(v, "canary", "record", "caught", "--loop", f"hc-{_M1U}", "--severity", "minor", "--reviewed", h_v1)
    check("--reviewed 孤給 rc2", r.returncode == 2)
    # --spec 指目錄 rc2(OSError 兜底)
    r = run(v, "canary", "record", "caught", "--loop", f"hc-{_M1U}", "--severity", "minor",
            "--spec", str(v / "Projects"), "--reviewed", h_v1)
    check("--spec 目錄 rc2 無 traceback", r.returncode == 2 and "Traceback" not in r.stderr, r.stderr[:100])
    # 合法鏈:r1 reviewed=hash(v1) → fold → result=hash(v2);r2 reviewed=hash(v2) → result=hash(v3)
    run(v, "canary", "record", "caught", "--loop", f"hc-{_M1U}", "--severity", "minor", "--findings", "2",
        "--reviewed", h_v1, "--spec", str(spec), expect_rc=0)  # r1: 未再改檔,result=hash(v1)
    spec.write_text("v2 折入後\n", encoding="utf-8")
    h_v2 = _sha256_of(spec)
    run(v, "canary", "record", "caught", "--loop", f"hc-{_M1U}", "--severity", "minor", "--findings", "1",
        "--reviewed", h_v1, "--spec", str(spec), expect_rc=0)  # r2: reviewed=result[r1]=h_v1,result=h_v2
    r = run(v, "loop", "status", f"hc-{_M1U}", "--need", "2", "--gate", "--spec", str(spec), "--repo", str(v.parent))
    check("合法鏈 hash 段 ✓", "G3" in r.stdout and "✗" not in [l for l in r.stdout.splitlines() if "G3" in l][0])
    # 審後改檔 → 末筆 result ≠ 當前 → FAIL
    spec.write_text("v3 審後手改\n", encoding="utf-8")
    r = run(v, "loop", "status", f"hc-{_M1U}", "--need", "2", "--gate", "--spec", str(spec), "--repo", str(v.parent))
    check("審後改檔 FAIL", r.returncode == 1 and "改動" in r.stdout)
    spec.write_text("v2 折入後\n", encoding="utf-8")   # 還原
    # 鏈斷:新 loop,r2 reviewed ≠ r1 result
    spec2 = v / "Projects" / "hspec2.md"
    spec2.write_text("A\n", encoding="utf-8")
    hA = _sha256_of(spec2)
    run(v, "canary", "record", "caught", "--loop", f"hc2-{_M1U}", "--severity", "minor", "--findings", "1",
        "--reviewed", hA, "--spec", str(spec2), expect_rc=0)   # r1 result=hA
    spec2.write_text("B 帶外竄改\n", encoding="utf-8")
    hB = _sha256_of(spec2)
    run(v, "canary", "record", "caught", "--loop", f"hc2-{_M1U}", "--severity", "minor", "--findings", "0",
        "--reviewed", hB, "--spec", str(spec2), expect_rc=0)   # r2 reviewed=hB ≠ r1 result=hA → 斷鏈
    r = run(v, "loop", "status", f"hc2-{_M1U}", "--need", "2", "--gate", "--spec", str(spec2), "--repo", str(v.parent))
    check("鏈斷 FAIL", r.returncode == 1 and ("鏈" in r.stdout or "斷" in r.stdout))
    # 窗內半帶 FAIL
    spec3 = v / "Projects" / "hspec3.md"
    spec3.write_text("C\n", encoding="utf-8")
    hC = _sha256_of(spec3)
    run(v, "canary", "record", "caught", "--loop", f"hc3-{_M1U}", "--severity", "minor", "--findings", "1", expect_rc=0)
    run(v, "canary", "record", "caught", "--loop", f"hc3-{_M1U}", "--severity", "minor", "--findings", "0",
        "--reviewed", hC, "--spec", str(spec3), expect_rc=0)
    r = run(v, "loop", "status", f"hc3-{_M1U}", "--need", "2", "--gate", "--spec", str(spec3), "--repo", str(v.parent))
    check("窗內半帶 FAIL", r.returncode == 1 and "半帶" in r.stdout)
    # 聲明式:窗內全無 hash + gate 帶 --spec → FAIL 非 advisory
    run(v, "canary", "record", "caught", "--loop", f"hc4-{_M1U}", "--severity", "minor", "--findings", "1", expect_rc=0)
    run(v, "canary", "record", "caught", "--loop", f"hc4-{_M1U}", "--severity", "clean", "--findings", "0", expect_rc=0)
    r = run(v, "loop", "status", f"hc4-{_M1U}", "--need", "2", "--gate", "--spec", str(spec3), "--repo", str(v.parent))
    check("聲明式無 hash FAIL", r.returncode == 1 and "未綁" in r.stdout)
    # 不帶 --spec 舊用法不變(G1 skip 可 PASS)
    r = run(v, "loop", "status", f"hc4-{_M1U}", "--need", "2", "--gate", "--repo", str(v.parent))
    check("不帶 --spec 舊用法 rc0", r.returncode == 0, f"rc={r.returncode}\n{r.stdout[-200:]}")
    # panel 同輪 result 分裂 FAIL(五席四 B 一 C)
    spec4 = v / "Projects" / "hspec4.md"
    spec4.write_text("D\n", encoding="utf-8")
    hD = _sha256_of(spec4)
    for i in range(4):
        run(v, "canary", "record", "caught", "--loop", f"hp-{_M1U}", "--round", "r1", "--auditor", f"s{i}",
            "--severity", "minor", "--findings", "0", "--reviewed", hD, "--spec", str(spec4), expect_rc=0)
    spec4.write_text("E 分裂\n", encoding="utf-8")
    run(v, "canary", "record", "caught", "--loop", f"hp-{_M1U}", "--round", "r1", "--auditor", "s4",
        "--severity", "minor", "--findings", "0", "--capture-counts", "1,1", "--reviewed", hD,
        "--spec", str(spec4), expect_rc=0)   # result=hash(E) ≠ 前四席 result=hD
    r = run(v, "loop", "status", f"hp-{_M1U}", "--panel", "--gate", "--spec", str(spec4), "--repo", str(v.parent))
    check("panel 同輪 result 分裂 FAIL", r.returncode == 1 and ("分裂" in r.stdout or "一致" in r.stdout))


def t_m1_light_gate():
    """M1包 #2 light K=1 謂詞:真值矩陣/ratchet 永久+分因/欄位互證/hash 強制/互斥。"""
    print("t_m1_light_gate")
    v = mkvault()
    spec = v / "Projects" / "lspec.md"
    spec.write_text("light spec\n", encoding="utf-8")
    h = _sha256_of(spec)
    # --light+--panel 互斥 rc2
    r = run(v, "loop", "status", f"lg-{_M1U}", "--light", "--panel")
    check("--light+--panel rc2", r.returncode == 2)
    # light 缺 --spec rc2(hash 強制需驗證對象)
    run(v, "canary", "record", "caught", "--loop", f"lg-{_M1U}", "--severity", "clean", "--findings", "0",
        "--reviewed", h, "--spec", str(spec), expect_rc=0)
    r = run(v, "loop", "status", f"lg-{_M1U}", "--light", "--gate")
    check("light 缺 --spec rc2", r.returncode == 2)
    # caught+clean+hash → PASS rc0
    r = run(v, "loop", "status", f"lg-{_M1U}", "--light", "--gate", "--spec", str(spec), "--repo", str(v.parent))
    check("light caught+clean PASS", r.returncode == 0, f"rc={r.returncode}\n{r.stdout[-200:]}")
    # 欄位互證:clean+findings=5 → FAIL
    run(v, "canary", "record", "caught", "--loop", f"lg2-{_M1U}", "--severity", "clean", "--findings", "5",
        "--reviewed", h, "--spec", str(spec), expect_rc=0)
    r = run(v, "loop", "status", f"lg2-{_M1U}", "--light", "--gate", "--spec", str(spec), "--repo", str(v.parent))
    check("欄位互證矛盾 FAIL", r.returncode == 1 and "互證" in r.stdout)
    # hash 缺失=FAIL(light 強制)
    run(v, "canary", "record", "caught", "--loop", f"lg3-{_M1U}", "--severity", "clean", "--findings", "0", expect_rc=0)
    r = run(v, "loop", "status", f"lg3-{_M1U}", "--light", "--gate", "--spec", str(spec), "--repo", str(v.parent))
    check("light hash 缺=FAIL", r.returncode == 1 and ("hash" in r.stdout or "綁" in r.stdout))
    # missed → FAIL(retryable 分因,不觸發 ratchet)
    run(v, "canary", "record", "missed", "--loop", f"lg4-{_M1U}", "--severity", "clean", "--findings", "0", expect_rc=0)
    r = run(v, "loop", "status", f"lg4-{_M1U}", "--light", "--gate", "--spec", str(spec), "--repo", str(v.parent))
    check("missed FAIL retryable", r.returncode == 1 and "retryable" in r.stdout)
    run(v, "canary", "record", "caught", "--loop", f"lg4-{_M1U}", "--severity", "clean", "--findings", "0",
        "--reviewed", h, "--spec", str(spec), expect_rc=0)
    r = run(v, "loop", "status", f"lg4-{_M1U}", "--light", "--gate", "--spec", str(spec), "--repo", str(v.parent))
    check("missed 後 caught 乾淨可 PASS", r.returncode == 0)
    # ratchet:caught+major → 永久 FAIL,後續乾淨不洗回
    run(v, "canary", "record", "caught", "--loop", f"lg5-{_M1U}", "--severity", "major", "--findings", "3",
        "--reviewed", h, "--spec", str(spec), expect_rc=0)
    r = run(v, "loop", "status", f"lg5-{_M1U}", "--light", "--gate", "--spec", str(spec), "--repo", str(v.parent))
    check("ratchet FAIL 分因", r.returncode == 1 and "ratchet" in r.stdout)
    run(v, "canary", "record", "caught", "--loop", f"lg5-{_M1U}", "--severity", "clean", "--findings", "0",
        "--reviewed", h, "--spec", str(spec), expect_rc=0)
    r = run(v, "loop", "status", f"lg5-{_M1U}", "--light", "--gate", "--spec", str(spec), "--repo", str(v.parent))
    check("ratchet 永久(乾淨輪不洗回)", r.returncode == 1 and "ratchet" in r.stdout)


def t_loop_next_cluster_hint_only_when_choice_is_open():
    """★機制存在但沒在用★(2026-08-02 量測):M2 的 cluster 三態帳落地至今,316 筆
    canary 記錄裡★只有 1 筆帶 --clusters★,而那一筆是開發它的 `code-m2cluster`
    自己——34 個用過 panel 的 loop 裡有 33 個靜默落回無-cluster 舊帳(單一 max
    severity)。根因不是機制不好,是★沒有任何地方在該選的時候提起它★:
    `loop next` 不提、skill 只描述兩種帳卻不說何時該選。

    ★而模式只有第一輪能選★——由「第一個有效輪」定錨,之後要換只能開新 loop id。
    所以提示必須恰好出現在 N=1,且★不得對已開始記錄的 loop 噴★(那時選擇已經關了,
    提了只是誤導)。

    ★驗行為★:panel 模式(tier=standard/high)零記錄時必須有 hint;有記錄之後
    (N≥2)必須沒有;legacy 與 light 這兩種用不到 cluster 帳的模式也必須沒有。"""
    import json as _j
    v = mkvault()
    spec = v / "Projects" / "chspec.md"
    spec.write_text("cluster hint spec\n", encoding="utf-8")
    h = _sha256_of(spec)
    lid = f"ch-{_M1U}"

    r = run(v, "loop", "next", lid, "--tier", "standard", "--json")
    d = _j.loads(r.stdout)
    check("★前置★ 現場成立:第一輪且為 panel 模式",
          d["phase"] == "plant-canary" and d["round"] == 1 and d["tier"] == "standard", r.stdout[:200])
    check("★N=1(選擇還開著)必須提示 cluster 帳★", "cluster_hint" in d, r.stdout[:300])
    check("★提示要講清楚『只有現在能選』★(不然看到也不知道有時效)",
          "第一輪" in d.get("cluster_hint", "") and "開新 loop id" in d.get("cluster_hint", ""),
          d.get("cluster_hint", "")[:200])
    check("★文字模式也要印出來★(不能只有 --json 看得到)",
          "cluster_hint" in run(v, "loop", "next", lid, "--tier", "standard").stdout, "")

    # 記一輪之後,模式已定錨 → 選擇關了 → 不得再提
    run(v, "canary", "record", "caught", "--loop", lid, "--round", "r1", "--severity", "clean",
        "--findings", "0", "--auditor", "s1", "--reviewed", h, "--spec", str(spec),
        "--tier", "standard", expect_rc=0)
    r2 = run(v, "loop", "next", lid, "--json", "--spec", str(spec), "--repo", str(v.parent))
    d2 = _j.loads(r2.stdout)
    check("★已開始記錄後不得再提★(選擇已關,提了是誤導)", "cluster_hint" not in d2, r2.stdout[:300])

    # legacy 與 light 用不到 cluster 帳 → 不得提(反誤傷)
    dl = _j.loads(run(v, "loop", "next", f"chl-{_M1U}", "--tier", "light", "--json").stdout)
    check("★light 不得提(用不到 cluster 帳)★", "cluster_hint" not in dl, "")


def t_quote_check_normalization_and_verdict():
    """[T2 錨定檢查](spec:Projects/design-loop重設計 三;plan:同名_實作計畫 T2)

    `lumos quote-check <報告> --spec <凍結快照>`:報告內每條「引句：「…」」
    norm 後必須是快照 norm 後的子字串。rc0=全 ok、rc1=有 miss、rc2=IO/零引句。

    ★正規化是本命令的全部價值★:r1 實戰就有一條真引句因原文帶粗體記號被誤判
    錨不到(審 design-loop重設計 時 s3 引「正確性歸下游」,原文是「**正確性歸下游**」)。
    _quote_norm=NFC→剝 */`→空白(含全形)摺疊單空格。

    ★單一實作鐵則★:抽取與比對共用一份 _quote_norm(2026-08-02 教訓:預檢與主迴圈
    兩份實作當場漂移)——機械代理=全檔 `def _quote_norm` 恰一處。
    翻紅釘:把剝記號步驟還原掉 → 粗體案例翻紅。"""
    import json as _j
    v = mkvault()
    snap = v / "Projects" / "qsnap.md"
    snap.write_text(
        "# spec\n**正確性歸下游**：TDD 落地（測試是真 oracle）\n"
        "閘只留可重算的；其餘降級成 `強制留痕` 的觀測，\n分兩行寫的一句話。\n",
        encoding="utf-8")
    rpt = v / "Projects" / "qrpt.md"
    rpt.write_text(
        "[major] 甲\n引句：「正確性歸下游：TDD 落地（測試是真 oracle）」\n"      # 粗體剝除後可對上
        "[minor] 乙\n引句：「閘只留可重算的；其餘降級成 強制留痕 的觀測， 分兩行寫的一句話。」\n",  # 反引號+跨行
        encoding="utf-8")
    r = run(v, "quote-check", str(rpt), "--spec", str(snap))
    check("★粗體/反引號/跨行三種正規化後全 ok(rc0)★", r.returncode == 0,
          f"rc={r.returncode}\n{r.stdout[:300]}{r.stderr[:200]}")

    # 編造引句 → miss → rc1,且 --json 逐條標得出哪條
    bad = v / "Projects" / "qbad.md"
    bad.write_text("引句：「正確性歸下游：TDD 落地」\n引句：「這句話快照裡根本沒有」\n", encoding="utf-8")
    r2 = run(v, "quote-check", str(bad), "--spec", str(snap), "--json")
    check("★前置★ 現場成立:真的抽到 2 條引句", r2.returncode == 1, f"rc={r2.returncode}")
    d = _j.loads(r2.stdout)
    check("編造引句判 miss、真引句判 ok(逐條可讀)",
          [q["ok"] for q in d["quotes"]] == [True, False], r2.stdout[:300])

    # 零引句=rc2(什麼都驗不了要 fail loud,不是靜默 rc0)
    empty = v / "Projects" / "qempty.md"
    empty.write_text("這份報告沒有任何引句樣式\n", encoding="utf-8")
    check("★零引句 rc2(驗不了≠通過)★", run(v, "quote-check", str(empty), "--spec", str(snap)).returncode == 2, "")
    check("快照不存在 rc2", run(v, "quote-check", str(rpt), "--spec", str(v / "no.md")).returncode == 2, "")

    # 單一實作鐵則(機械代理)
    src = (Path(__file__).resolve().parent / "lumos").read_text(encoding="utf-8")
    check("★單一實作:全檔 `def _quote_norm` 恰一處★", src.count("def _quote_norm") == 1, "")


def t_calibration_smoke():
    """[T7](plan:design-loop重設計_實作計畫 T7)離線校準腳本冒煙:判定沿 lumos 的 _quote_norm
    (單一實作,import 不複製);寬判(mentioned≠caught 分開列);不寫累積帳(--no-log)。"""
    _need_src("governance/eval/canary_calibration.py")   # 缺=拋 _SrcOnly 由 runner 記 skip
    import json as _j
    import tempfile as _tf
    d = Path(_tf.mkdtemp(prefix="calib-"))
    (d / "plants.json").write_text(_j.dumps([
        {"id": "P1", "file": "f.md", "type": "b", "token": "--ghost-flag", "nature": "未定義旗標"}]),
        encoding="utf-8")
    rdir = d / "r"; rdir.mkdir()
    (rdir / "sA.md").write_text("[major] `--ghost-flag` 未定義,文中沒有定義它" + chr(10), encoding="utf-8")
    (rdir / "sB.md").write_text("整份看起來不錯" + chr(10), encoding="utf-8")
    src = Path(__file__).resolve().parent.parent / "governance" / "eval" / "canary_calibration.py"
    r = subprocess.run([sys.executable, str(src), "--plants", str(d / "plants.json"),
                        "--reports", str(rdir), "--config", "smoke-test", "--no-log"],
                       capture_output=True, text=True)
    check("★校準冒煙:rc0 且 caught 判定正確(sA ✓/sB ✗)★",
          r.returncode == 0 and "caught 1/1" in r.stdout and "caught 0/1" in r.stdout,
          f"rc={r.returncode} " + r.stdout[:300] + r.stderr[:200])
    check("不進 gate 的誠實聲明在輸出上", "不進任何 gate" in r.stdout, "")


def t_loop_next_disposal_cmd_actually_runs():
    """[T5](plan:design-loop重設計_實作計畫 T5)loop next 的 disposal_cmd 模板★真跑 oracle★
    (沿 t_loop_next_legacy 教訓:工具吐的指令必須跑得動,字串斷言只證長得對)。
    record_cmd 原樣保留(code-loop 不受影響)。"""
    import json as _j
    v = mkvault()
    spec = v / "Projects" / "t5spec.md"
    spec.write_text("t5 spec\n規則甲。\n", encoding="utf-8")
    h = _sha256_of(spec)
    rpt = v / "Projects" / "t5rpt.md"
    rpt.write_text("引句：「規則甲。」\n", encoding="utf-8")
    lid = f"t5-{_M1U}"
    d = _j.loads(run(v, "loop", "next", lid, "--tier", "standard", "--json").stdout)
    check("★前置★ 現場成立:panel tier 吐 disposal_cmd+disposal_gate",
          "disposal_cmd" in d and "disposal_gate" in d and "record_cmd" in d, str(d)[:200])
    filled = (d["disposal_cmd"].replace("caught|missed", "caught").replace("<席>", "s1")
              .replace("<s>", "minor").replace("<id串>", "F1", 1)          # findings-set
              .replace("--folded-set <id串>", "--folded-set F1")
              .replace(" --accepted-set <id串>", "")     # accepted 缺省=空集合(argv 手切,'' 會變字面引號)
              .replace(" --accept-reason <id=理由>", "")
              .replace("<席報告.md>", str(rpt)).replace("<凍結快照.md>", str(spec))
              .replace("<計劃節點.md>", str(spec)).replace("<sha256>", h))
    argv = filled.split()
    check("★前置★ 填完無殘留佔位符", "<" not in filled and argv[0] == "lumos", filled)
    rr = run(v, *argv[1:])
    check("★disposal_cmd 模板真的跑得動(rc0)★", rr.returncode == 0,
          f"rc={rr.returncode} {rr.stderr[:200]}")
    g = (d["disposal_gate"].replace("<計劃節點.md>", str(spec)).replace("<root>", str(v.parent)))
    rg = run(v, *g.split()[1:])
    check("★disposal_gate 模板跑得動且對剛記的帳給出判定(rc0/1 非 rc2)★", rg.returncode in (0, 1),
          f"rc={rg.returncode} {rg.stderr[:200]}")


def t_disposal_loop_requires_provenance():
    """[T6 收緊](plan:design-loop重設計_實作計畫 T6)

    定錨規則(同 M2 cluster 前例):loop ★首筆帶 findings_set 的記錄★定錨為 disposal loop;
    定錨後該 loop 後續 record ★必帶 --report+--snapshot★,缺=rc2(寫側擋)。
    ★舊 loop/未定錨 loop 完全不受影響★(相容鐵則)。
    翻紅釘:把強制檢查還原掉 → 「定錨後缺 report 必 rc2」翻紅。"""
    v = mkvault()
    d = v / "Projects"
    rpt = d / "t6r.md"; rpt.write_text("引句：「x」\n", encoding="utf-8")
    snap = d / "t6s.md"; snap.write_text("x\n", encoding="utf-8")
    lid = f"t6-{_M1U}"
    # 首筆帶 findings_set+留痕 → 定錨
    run(v, "canary", "record", "caught", "--loop", lid, "--auditor", "s1", "--severity", "minor",
        "--findings-set", "a", "--folded-set", "a", "--report", str(rpt), "--snapshot", str(snap),
        expect_rc=0)
    # 定錨後缺留痕 → rc2
    rr = run(v, "canary", "record", "caught", "--loop", lid, "--auditor", "s2", "--severity", "minor")
    check("★定錨後缺 --report/--snapshot 必 rc2(留痕轉強制)★", rr.returncode == 2, f"rc={rr.returncode} {rr.stderr[:150]}")
    # 帶齊就過
    run(v, "canary", "record", "missed", "--loop", lid, "--auditor", "s3", "--severity", "major",
        "--report", str(rpt), "--snapshot", str(snap), expect_rc=0)
    # ★相容:未定錨 loop 照舊自由★
    run(v, "canary", "record", "caught", "--loop", f"t6free-{_M1U}", "--auditor", "s1",
        "--severity", "minor", expect_rc=0)
    check("★前置★ 現場成立:定錨 loop 與自由 loop 同庫共存", True, "")


def t_loop_status_disposal_gate():
    """[T4 處置閘](spec:Projects/design-loop重設計 三;plan:同名_實作計畫 T4)

    `loop status <id> --disposal --spec <真檔> --repo <root>`:新閘走★獨立路徑★,
    四條合取全部讀側可重算:①G3 hash 鏈 ②處置集合(重算,不信寫側)③留痕讀側重驗
    (report/snapshot 存在且 sha256 與帳面一致——record 完刪檔照樣擋)④quote-check
    對帳面 snapshot 重跑全 ok。

    ★d4 合約★:canary kind=missed ★不進合取★——missed 席在場照樣可收斂(觀測非閘)。
    ★相容合約★:同一帳不帶 --disposal 走舊路徑,行為與改動前一致(舊閘一行不動)。
    取捨(plan〈實務隱患〉預告):舊路徑迴歸斷言採「rc+判定行子字串」而非逐字節相同——
    逐字節對提示文字換行過脆;rc+『輪有效』子串足以釘住「走的是舊 panel 判定」。
    翻紅釘:刪掉報告檔 → 條③翻紅(現場成立前置:record 當下檔案在)。"""
    import json as _j
    v = mkvault()
    d = v / "Projects"
    spec = d / "t4spec.md"
    spec.write_text("# spec\n規則甲：只在 0 命中時回退。\n", encoding="utf-8")
    h = _sha256_of(spec)
    snap = d / "t4snap.md"
    snap.write_text(spec.read_text(encoding="utf-8"), encoding="utf-8")
    rpt = d / "t4rpt.md"
    rpt.write_text("[minor] 甲\n引句：「規則甲：只在 0 命中時回退。」\n", encoding="utf-8")
    lid = f"t4-{_M1U}"

    # 判定輪 r1 兩席:席1 帶處置帳+留痕+雙 hash;席2=★missed★(d4:不得影響閘)
    run(v, "canary", "record", "caught", "--loop", lid, "--round", "r1", "--auditor", "s1",
        "--severity", "minor", "--findings-set", "F1,F2", "--folded-set", "F1",
        "--accepted-set", "F2", "--accept-reason", "F2=精度級",
        "--report", str(rpt), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    run(v, "canary", "record", "missed", "--loop", lid, "--round", "r1", "--auditor", "s2",
        "--severity", "major", "--report", str(rpt), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)   # T6:定錨後每席都要留痕(d4 判定留痕)

    # 互斥
    for extra in (["--panel"], ["--light"], ["--need", "3"]):
        rr = run(v, "loop", "status", lid, "--disposal", "--spec", str(spec), "--repo", str(v.parent), *extra)
        check(f"--disposal 與 {extra[0]} 互斥 rc2", rr.returncode == 2, f"rc={rr.returncode} {rr.stderr[:100]}")
    check("--disposal 缺 --spec rc2(fail-closed,同 light 慣例)",
          run(v, "loop", "status", lid, "--disposal", "--repo", str(v.parent)).returncode == 2, "")

    r = run(v, "loop", "status", lid, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★四條合取全過→rc0;missed 席在場照樣收斂(d4:canary=觀測非閘)★",
          r.returncode == 0, f"rc={r.returncode}\n{r.stdout[:400]}{r.stderr[:200]}")

    # 舊路徑迴歸:同一帳不帶 --disposal 走舊 panel 閘(格式帶 round→須 --panel),行為不變
    r_old = run(v, "loop", "status", lid, "--gate", "--panel", "--spec", str(spec), "--repo", str(v.parent))
    check("★相容:同一帳走舊 panel 閘照舊 FAIL(1 caught+1 missed=輪無效)——舊閘一行不動★",
          r_old.returncode == 1 and "輪有效" in r_old.stdout, f"rc={r_old.returncode}\n{r_old.stdout[:200]}")

    # ③留痕讀側:record 完把報告檔改掉 → sha 不符 → FAIL
    check("★前置★ 現場成立:record 當下報告檔在且剛才 rc0", rpt.exists(), "")
    orig = rpt.read_text(encoding="utf-8")
    rpt.write_text(orig + "事後竄改\n", encoding="utf-8")
    r2 = run(v, "loop", "status", lid, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★留痕讀側重驗:報告被改(sha 不符)必 FAIL rc1★", r2.returncode == 1, f"rc={r2.returncode}\n{r2.stdout[:300]}")
    rpt.write_text(orig, encoding="utf-8")

    # ④quote-check 讀側:快照偷換成沒有該句的版本 → miss → FAIL
    snap2 = d / "t4snap2.md"
    snap2.write_text("# 別的內容\n", encoding="utf-8")
    lid2 = f"t4b-{_M1U}"
    run(v, "canary", "record", "caught", "--loop", lid2, "--round", "r1", "--auditor", "s1",
        "--severity", "minor", "--findings-set", "F1", "--folded-set", "F1",
        "--report", str(rpt), "--snapshot", str(snap2),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    r3 = run(v, "loop", "status", lid2, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★quote-check 讀側:引句錨不到快照必 FAIL rc1★", r3.returncode == 1, f"rc={r3.returncode}\n{r3.stdout[:300]}")

    # ②處置集合讀側+blocker 線:blocker 席在場且有 accepted → FAIL(即使寫側當時個別合法)
    lid3 = f"t4c-{_M1U}"
    run(v, "canary", "record", "caught", "--loop", lid3, "--round", "r1", "--auditor", "s1",
        "--severity", "minor", "--findings-set", "F1", "--folded-set", "",
        "--accepted-set", "F1", "--accept-reason", "F1=可放",
        "--report", str(rpt), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    run(v, "canary", "record", "caught", "--loop", lid3, "--round", "r1", "--auditor", "s2",
        "--severity", "blocker", "--report", str(rpt), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)   # T6 同上
    r4 = run(v, "loop", "status", lid3, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★blocker 在別席+本席 accepted:輪級重算必 FAIL(堵 Codex 的寫側盲區)★",
          r4.returncode == 1, f"rc={r4.returncode}\n{r4.stdout[:300]}")


def t_disposal_gate_r1_panel_hardening():
    """[T8 終審 r1 findings 修復](plan:design-loop重設計_實作計畫 T8;loop code-dloop-redesign r1)

    五組缺陷全部先機械 repro 證實(可執行 falsification)才修:
    ①壞行 fail-closed:.canary-log 有壞行 → disposal 閘 rc2(原:壞行靜默跳過,判錯 latest);
      T6 定錨掃描改逐行容錯(原:壞行在定錨行前→any() 短路前炸→整包 fail-open,強制被繞過)。
    ②判定輪守衛:round-id 非連續重現 rc2(reuse panel 守衛;原:OrderedDict 首現序拿錯輪,
      時序最後的遲到 r1 帶壞引句照樣 PASS)。
    ③留痕讀側涵蓋判定輪★全部★帶留痕欄的席(原只驗 carrier;竄改 missed 席報告照樣 PASS)。
    ④report/snapshot 以 repo root 相對路徑落帳與解析(原:相對 cwd;換目錄跑 gate 留痕假失蹤,
      合法 loop 永久 FAIL)。
    ⑤report/snapshot 非 UTF-8 → 讀側 FAIL/rc2,不得 traceback。
    翻紅釘:各條把修法還原必翻紅;各場景附「現場成立」前置斷言。"""
    import json as _j
    v = mkvault()
    d = v / "Projects"
    spec = d / "h8spec.md"
    spec.write_text("# spec\n規則『甲』其實存在,規則乙也在。\n", encoding="utf-8")
    h = _sha256_of(spec)
    snap = d / "h8snap.md"
    snap.write_text(spec.read_text(encoding="utf-8"), encoding="utf-8")
    rptA = d / "h8a.md"
    rptA.write_text("[minor] 甲\n引句：「規則『甲』其實存在,規則乙也在。」\n", encoding="utf-8")
    rptB = d / "h8b.md"
    rptB.write_text("[major] 乙\n引句：「規則『甲』其實存在,規則乙也在。」\n", encoding="utf-8")
    ledger = v.parent / ".canary-log.jsonl"

    # ── ① 讀側:壞行 → disposal rc2 ──
    lid1 = f"h8a-{_M1U}"
    run(v, "canary", "record", "caught", "--loop", lid1, "--round", "r1", "--auditor", "s1",
        "--severity", "minor", "--findings-set", "F1", "--folded-set", "F1",
        "--report", str(rptA), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    r0 = run(v, "loop", "status", lid1, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★前置★ 現場成立:壞行注入前同帳 rc0", r0.returncode == 0, f"rc={r0.returncode}\n{r0.stdout[:200]}")
    good = ledger.read_text(encoding="utf-8")
    ledger.write_text(good + "{broken\n", encoding="utf-8")
    r1 = run(v, "loop", "status", lid1, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★壞行 fail-closed:帳含不可解析行 → disposal rc2★", r1.returncode == 2,
          f"rc={r1.returncode}\n{r1.stdout[:200]}{r1.stderr[:200]}")
    # ── ① 寫側:壞行在定錨行前,T6 強制不得被繞過 ──
    ledger.write_text("{broken\n" + good, encoding="utf-8")
    r2 = run(v, "canary", "record", "caught", "--loop", lid1, "--auditor", "s9", "--severity", "minor")
    check("★T6 定錨掃描逐行容錯:壞行在定錨行前,缺留痕照樣 rc2(原 fail-open rc0)★",
          r2.returncode == 2, f"rc={r2.returncode} {r2.stderr[:150]}")
    ledger.write_text(good, encoding="utf-8")

    # ── ② round-id 非連續重現 → rc2 ──
    lid2 = f"h8b-{_M1U}"
    rptBad = d / "h8bad.md"
    rptBad.write_text("引句：「這句話快照裡根本沒有喔喔喔」\n", encoding="utf-8")
    for rid, rp in (("r1", rptA), ("r2", rptA), ("r1", rptBad)):
        run(v, "canary", "record", "caught", "--loop", lid2, "--round", rid, "--auditor", "sx",
            "--severity", "minor", "--findings-set", "F1", "--folded-set", "F1",
            "--report", str(rp), "--snapshot", str(snap),
            "--spec", str(spec), "--reviewed", h, expect_rc=0)
    raw = [_j.loads(l) for l in ledger.read_text(encoding="utf-8").splitlines()
           if l.strip() and _j.loads(l).get("loop") == lid2]
    check("★前置★ 現場成立:帳面時序 r1,r2,r1(遲到筆引句錨不到)", [x.get("round") for x in raw] == ["r1", "r2", "r1"], str(raw)[:200])
    r3 = run(v, "loop", "status", lid2, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★round-id 非連續重現=帳次序損壞 rc2(原:拿 r2 當判定輪照樣 PASS)★",
          r3.returncode == 2, f"rc={r3.returncode}\n{r3.stdout[:200]}{r3.stderr[:150]}")

    # ── ③ 竄改非 carrier 席(missed)的報告 → FAIL ──
    lid3 = f"h8c-{_M1U}"
    run(v, "canary", "record", "caught", "--loop", lid3, "--round", "r1", "--auditor", "s1",
        "--severity", "minor", "--findings-set", "F1", "--folded-set", "F1",
        "--report", str(rptA), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    run(v, "canary", "record", "missed", "--loop", lid3, "--round", "r1", "--auditor", "s2",
        "--severity", "major", "--report", str(rptB), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    r4 = run(v, "loop", "status", lid3, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★前置★ 現場成立:兩席各自留痕,未竄改時 rc0", r4.returncode == 0, f"rc={r4.returncode}\n{r4.stdout[:300]}")
    origB = rptB.read_text(encoding="utf-8")
    rptB.write_text(origB + "事後竄改 missed 席\n", encoding="utf-8")
    r5 = run(v, "loop", "status", lid3, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★留痕讀側涵蓋全席:竄改 missed 席報告必 FAIL(原只驗 carrier 照樣 PASS)★",
          r5.returncode == 1, f"rc={r5.returncode}\n{r5.stdout[:300]}")
    rptB.write_text(origB, encoding="utf-8")

    # ── ④ 相對路徑:record 於 vault.parent 下用相對路徑,gate 從別的 cwd 跑照樣過 ──
    lid4 = f"h8d-{_M1U}"
    (v.parent / "h8rel-r.md").write_text("引句：「規則『甲』其實存在,規則乙也在。」\n", encoding="utf-8")
    (v.parent / "h8rel-s.md").write_text(spec.read_text(encoding="utf-8"), encoding="utf-8")
    rr = subprocess.run([sys.executable, GRAPHCTL, "--vault", str(v), "canary", "record", "caught",
                         "--loop", lid4, "--round", "r1", "--auditor", "s1", "--severity", "minor",
                         "--findings-set", "F1", "--folded-set", "F1",
                         "--report", "h8rel-r.md", "--snapshot", "h8rel-s.md",
                         "--spec", str(spec), "--reviewed", h],
                        capture_output=True, text=True, cwd=str(v.parent))
    check("★前置★ 現場成立:相對路徑 record rc0(cwd=repo root)", rr.returncode == 0, rr.stderr[:200])
    r6 = run(v, "loop", "status", lid4, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★相對路徑以 repo root 解析:換 cwd 跑 gate 照樣 rc0(原:留痕假失蹤永久 FAIL)★",
          r6.returncode == 0, f"rc={r6.returncode}\n{r6.stdout[:300]}")

    # ── ⑤ 非 UTF-8 報告:FAIL 但不得 traceback ──
    lid5 = f"h8e-{_M1U}"
    rptBin = d / "h8bin.md"
    rptBin.write_bytes(b"\xff\xfe\x00 binary junk \x80\x81")
    run(v, "canary", "record", "caught", "--loop", lid5, "--round", "r1", "--auditor", "s1",
        "--severity", "minor", "--findings-set", "F1", "--folded-set", "F1",
        "--report", str(rptBin), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    r7 = run(v, "loop", "status", lid5, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★非 UTF-8 報告:讀側 FAIL(rc1/2)且無 traceback★",
          r7.returncode in (1, 2) and "Traceback" not in r7.stderr,
          f"rc={r7.returncode}\n{r7.stderr[:300]}")
    r8 = run(v, "quote-check", str(rptBin), "--spec", str(snap))
    check("quote-check 對非 UTF-8 檔 rc2 且無 traceback",
          r8.returncode == 2 and "Traceback" not in r8.stderr, f"rc={r8.returncode}\n{r8.stderr[:300]}")


def t_disposal_gate_r2_panel_hardening():
    """[T8 終審 r2 findings 修復](loop code-dloop-redesign r2)

    r1 修復批自己引入的回歸,r2 panel 抓到、機械 repro 後修:
    ①__legacy 合組回歸(s2+s3):round-less 記錄被併成同一組→較早 carrier 冒充最新判定/
      合法 legacy 第二筆觸發假 rc2。修=回到逐筆 __seq 分組(round-less 每筆自成一輪,
      判定輪=時序最後一筆),round-id 守衛只管顯式 round。
    ②全席留痕缺欄跳過(s5+否決席):判定輪內缺 report_path/snapshot_path 的席被 continue
      靜默略過,「全席重驗」對缺欄席不成立。修=缺欄=留痕缺席 FAIL。
    ③repo root 判定(否決席):真實布局 vault=docs/<slug>-knowledge → vault.parent=docs/
      非 repo root,governance/ 留痕永遠落絕對路徑(可攜性假賣點)。修=寫讀兩側同用
      「從 vault 向上找 .git」的 _vault_repo_root(找不到退 vault.parent,測試假 vault 不變)。
    翻紅釘:各條把修法還原必翻紅;前置斷言證現場成立。"""
    import json as _j
    v = mkvault()
    d = v / "Projects"
    spec = d / "r2spec.md"
    spec.write_text("# spec\n規則丙:留痕全席重驗,一席都不能少。\n", encoding="utf-8")
    h = _sha256_of(spec)
    snap = d / "r2snap.md"
    snap.write_text(spec.read_text(encoding="utf-8"), encoding="utf-8")
    rpt = d / "r2rpt.md"
    rpt.write_text("引句：「規則丙:留痕全席重驗,一席都不能少。」\n", encoding="utf-8")

    # ── ① legacy(round-less):兩筆記錄各自成輪,判定輪=最後一筆 ──
    lid1 = f"r2a-{_M1U}"
    run(v, "canary", "record", "caught", "--loop", lid1, "--auditor", "s1", "--severity", "minor",
        "--findings-set", "F1", "--folded-set", "F1", "--report", str(rpt), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    run(v, "canary", "record", "caught", "--loop", lid1, "--auditor", "s2", "--severity", "minor",
        "--report", str(rpt), "--snapshot", str(snap), "--spec", str(spec), "--reviewed", h, expect_rc=0)
    r1 = run(v, "loop", "status", lid1, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★前置★ 現場成立:legacy 第二筆合法落帳(無假 rc2)且 gate 跑得動",
          r1.returncode in (0, 1), f"rc={r1.returncode}\n{r1.stderr[:200]}")
    check("★legacy 逐筆成輪:判定輪=最後一筆(無處置帳)→FAIL 而非拿早筆 carrier 冒充 PASS★",
          r1.returncode == 1 and "無處置帳" in r1.stdout,
          f"rc={r1.returncode}\n{r1.stdout[:300]}")

    # ── ② 判定輪內缺留痕欄的席=FAIL(不得靜默跳過) ──
    lid2 = f"r2b-{_M1U}"
    run(v, "canary", "record", "missed", "--loop", lid2, "--round", "r1", "--auditor", "s0",
        "--severity", "major", "--spec", str(spec), "--reviewed", h, expect_rc=0)   # 定錨前:合法缺留痕
    run(v, "canary", "record", "caught", "--loop", lid2, "--round", "r1", "--auditor", "s1",
        "--severity", "minor", "--findings-set", "F1", "--folded-set", "F1",
        "--report", str(rpt), "--snapshot", str(snap), "--spec", str(spec), "--reviewed", h, expect_rc=0)
    r2 = run(v, "loop", "status", lid2, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★前置★ 現場成立:判定輪含一席無留痕欄+一席 carrier", r2.returncode in (0, 1), f"rc={r2.returncode}")
    check("★缺留痕欄的席=留痕缺席 FAIL(原 continue 靜默跳過→rc0)★",
          r2.returncode == 1 and "留痕" in r2.stdout, f"rc={r2.returncode}\n{r2.stdout[:300]}")

    # ── ③ repo root=向上找 .git:docs/ 兩層布局下 governance/ 留痕落相對路徑,搬 repo 仍可驗 ──
    import tempfile as _tf
    root = Path(_tf.mkdtemp(prefix="r2root-")) / "repo"
    (root / ".git").mkdir(parents=True)
    vv = root / "docs" / "kg"
    vv.mkdir(parents=True)
    for sub in ("Systems", "Verification", "Projects", "MOC"):
        (vv / sub).mkdir()
    gov = root / "governance"
    gov.mkdir()
    (gov / "g-r.md").write_text("引句：「規則丙:留痕全席重驗,一席都不能少。」\n", encoding="utf-8")
    spec2 = gov / "g-spec.md"
    spec2.write_text(spec.read_text(encoding="utf-8"), encoding="utf-8")
    (gov / "g-s.md").write_text(spec2.read_text(encoding="utf-8"), encoding="utf-8")
    h2 = _sha256_of(spec2)
    lid3 = f"r2c-{_M1U}"
    rr = subprocess.run([sys.executable, GRAPHCTL, "--vault", str(vv), "canary", "record", "caught",
                         "--loop", lid3, "--round", "r1", "--auditor", "s1", "--severity", "minor",
                         "--findings-set", "F1", "--folded-set", "F1",
                         "--report", "governance/g-r.md", "--snapshot", "governance/g-s.md",
                         "--spec", str(spec2), "--reviewed", h2],
                        capture_output=True, text=True, cwd=str(root))
    check("★前置★ 現場成立:docs 兩層布局 record rc0", rr.returncode == 0, rr.stderr[:200])
    ledger = _j.loads((root / "docs" / ".canary-log.jsonl").read_text(encoding="utf-8").splitlines()[-1])
    check("★governance/ 留痕以 repo root 相對路徑落帳(原 vault.parent=docs/ 導致永遠絕對路徑)★",
          ledger.get("report_path") == "governance/g-r.md", str(ledger.get("report_path")))
    r3 = subprocess.run([sys.executable, GRAPHCTL, "--vault", str(vv), "loop", "status", lid3,
                         "--disposal", "--spec", str(spec2), "--repo", str(root)],
                        capture_output=True, text=True)   # cwd=測試預設(≠root):讀側不得靠 cwd
    check("★讀側同根解析:換 cwd 跑 gate 照樣 rc0★", r3.returncode == 0,
          f"rc={r3.returncode}\n{r3.stdout[:300]}{r3.stderr[:200]}")


def t_disposal_gate_r3_panel_hardening():
    """[T8 終審 r3 findings 修復](loop code-dloop-redesign r3)

    ①__ 保留字首(3 席重疊,均實跑 repro):使用者 --round __seq0 撞讀側內部鍵→新輪併入
      舊輪、舊 carrier 冒充最新處置帳偽 PASS。修=寫側 rc2 拒收+讀側防守舊帳。
    ②round 與 round-less 混用=rc2 明確訊息(s4:原樣混排落進「非連續重現」誤導訊息)。
    ③引號開閉型態不符(「…』)的引句原本整條靜默消失=編造引句逃逸口(s2 實跑 repro)。
      修=「引句：」標記數>抽取數的差額以格式 miss 入列。
    翻紅釘:各條還原修法必翻紅;前置斷言證現場成立。"""
    v = mkvault()
    d = v / "Projects"
    spec = d / "r3spec.md"
    spec.write_text("# spec\n規則丁:保留字首不得外用,引號要成對。\n", encoding="utf-8")
    h = _sha256_of(spec)
    snap = d / "r3snap.md"
    snap.write_text(spec.read_text(encoding="utf-8"), encoding="utf-8")
    rpt = d / "r3rpt.md"
    rpt.write_text("引句：「規則丁:保留字首不得外用,引號要成對。」\n", encoding="utf-8")

    # ── ① __ 保留字首寫側 rc2 ──
    lid1 = f"r3a-{_M1U}"
    rr = run(v, "canary", "record", "caught", "--loop", lid1, "--round", "__seq0",
             "--auditor", "s1", "--severity", "minor")
    check("★--round __ 開頭=內部保留字首 rc2(撞鍵可讓舊 carrier 冒充最新處置帳)★",
          rr.returncode == 2 and "保留字首" in rr.stderr, f"rc={rr.returncode} {rr.stderr[:150]}")

    # ── ② 混用守衛:round-less + 帶 round 同 loop → disposal rc2 明確訊息 ──
    lid2 = f"r3b-{_M1U}"
    run(v, "canary", "record", "caught", "--loop", lid2, "--auditor", "s1", "--severity", "minor",
        "--findings-set", "F1", "--folded-set", "F1", "--report", str(rpt), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    run(v, "canary", "record", "caught", "--loop", lid2, "--round", "r1", "--auditor", "s2",
        "--severity", "minor", "--report", str(rpt), "--snapshot", str(snap),
        "--spec", str(spec), "--reviewed", h, expect_rc=0)
    r2 = run(v, "loop", "status", lid2, "--disposal", "--spec", str(spec), "--repo", str(v.parent))
    check("★前置★ 現場成立:同 loop 混有 round-less 與帶 round 記錄", r2.returncode == 2, f"rc={r2.returncode}")
    check("★混用=rc2 明確訊息(不再落進「非連續重現」誤導)★",
          "混用" in r2.stderr, r2.stderr[:200])

    # ── ③ 開閉引號型態不符→格式 miss(不得靜默消失) ──
    bad = d / "r3bad.md"
    bad.write_text("引句：「規則丁:保留字首不得外用,引號要成對。』\n", encoding="utf-8")
    r3 = run(v, "quote-check", str(bad), "--spec", str(snap))
    check("★不成對引句(「…』)以格式 miss 入列 rc1(原:整條靜默消失→零引句 rc2 或漏驗)★",
          r3.returncode == 1, f"rc={r3.returncode}\n{r3.stdout[:200]}{r3.stderr[:150]}")


def t_calibration_readback_hardening():
    """[T8 終審 r2 findings 修復](loop code-dloop-redesign r2;s5/否決席/s3/s4 四路收斂)

    校準帳寫後讀回自驗的三個洞:①末行黏連——舊帳以半行(無換行)結尾時 append 直接
    黏成一行,自驗炸 JSONDecodeError traceback ②末行定位——併發下末行可能是別程序的
    ③秒級 ts 撞同秒誤判。修=每筆帶唯一 run_id、append 前補換行、全檔容錯掃描找自己的行。
    r3 補(s4 席):測試改走 --log 隔離帳,生產帳一字不碰(原版直接改寫生產
    calibration-log.jsonl,與並行寫入者互踩)。
    翻紅釘:還原「append 前補換行」→ 半行案例翻紅。"""
    _need_src("governance/eval/canary_calibration.py")
    import json as _j
    import tempfile as _tf
    d = Path(_tf.mkdtemp(prefix="calib2-"))
    (d / "plants.json").write_text(_j.dumps([
        {"id": "P1", "file": "f.md", "type": "b", "token": "--ghost-flag", "nature": "未定義旗標"}]),
        encoding="utf-8")
    rdir = d / "r"; rdir.mkdir()
    (rdir / "sA.md").write_text("[major] `--ghost-flag` 未定義" + chr(10), encoding="utf-8")
    src = Path(__file__).resolve().parent.parent / "governance" / "eval" / "canary_calibration.py"
    log = d / "isolated-log.jsonl"
    # 現場:帳尾塞半行(無換行)——舊版 append 會黏行、自驗炸 traceback
    log.write_text('{"half":', encoding="utf-8")
    r = subprocess.run([sys.executable, str(src), "--plants", str(d / "plants.json"),
                        "--reports", str(rdir), "--config", "readback-hardening-test",
                        "--log", str(log)],
                       capture_output=True, text=True)
    check("★前置★ 現場成立:帳尾確為半行時仍寫入成功", r.returncode == 0,
          f"rc={r.returncode} {r.stdout[-200:]}{r.stderr[:300]}")
    check("★半行黏連防護:自驗 ✓ 且無 traceback★",
          "讀回自驗 ✓" in r.stdout and "Traceback" not in r.stderr, r.stdout[-200:] + r.stderr[:200])
    tail_lines = log.read_text(encoding="utf-8").splitlines()
    last = _j.loads(tail_lines[-1])
    check("寫入的末行可解析且帶唯一 run_id(全檔掃描定位,非末行定位)",
          bool(last.get("run_id")), str(last)[:150])


def t_quote_check_field_test_gaps():
    """[Landmark 真場實測 2026-08-04 抓到的三個抽取/比對缺口](loop POS櫃位驗證接受RSNO_實作 r3)

    ①標籤帶 markdown 強調/註記:席位自然寫成 `**引句**：「…」`/`**引句（Task 1，已確認）**：「…」`
      ——原 regex 只認裸 `引句：`,三席報告全數抽零條(rc2 假「未遵守格式」)。
    ②CJK 折行空格:快照在句中折行,norm 摺疊出「，␣Size」;報告引句連續無空格→子字串必 miss
      (r3 實況兩條真引句被誤判編造)。修=空白全剝的 fallback 比對。
    ③blockquote 折行:快照 `> …\\n> …` 的續行 `>` 記號進 hay→引句永遠比不中。修=norm 剝行首 >。
    翻紅釘:各條把修法還原必翻紅;前置斷言=快照確為折行/引用格式。"""
    v = mkvault()
    d = v / "Projects"
    snap = d / "fsnap.md"
    snap.write_text(
        "計畫正文:RSNO 負向查詢改用**專用** `MemoryCache` 實例，\n"
        "  `SizeLimit=2048`、每 entry `Size=1` 與正向快取一致。\n"
        "> 對應的殘餘風險由 Task 1 承接：預防交給人，\n"
        "> **但撞了不靜默選錯家**由程式擋。兩者分工明確。\n",
        encoding="utf-8")
    check("★前置★ 現場成立:快照確為句中折行+縮排續行+blockquote 續行",
          "，\n  `SizeLimit" in snap.read_text(encoding="utf-8")
          and "\n> **但撞了" in snap.read_text(encoding="utf-8"), "")
    rpt = d / "frpt.md"
    rpt.write_text(
        "[major] 甲\n**引句**：「RSNO 負向查詢改用專用 MemoryCache 實例，SizeLimit=2048、每 entry Size=1」\n"
        "[major] 乙\n**引句（Task 3，總結）**：「預防交給人，但撞了不靜默選錯家由程式擋。兩者分工明確。」\n",
        encoding="utf-8")
    r = run(v, "quote-check", str(rpt), "--spec", str(snap), "--json")
    import json as _j
    check("★標籤粗體/註記變體抽得出引句(原:抽零條 rc2)★", r.returncode in (0, 1) and r.stdout.strip(),
          f"rc={r.returncode} {r.stderr[:150]}")
    if r.returncode in (0, 1):
        dd = _j.loads(r.stdout)
        check("★兩條引句都抽到★", dd["total"] == 2, r.stdout[:200])
        check("★CJK 折行空格 fallback:連續引句對折行原文判 ok★",
              dd["quotes"][0]["ok"] is True, r.stdout[:300])
        check("★blockquote 續行 > 記號剝除:引句判 ok★",
              dd["quotes"][1]["ok"] is True, r.stdout[:300])
    # 收緊釘:編造引句在新規則下仍 miss(空白剝除不得把不同句黏成命中)
    bad = d / "fbad.md"
    bad.write_text("**引句**：「這句話快照裡根本沒有而且很長喔喔喔」\n", encoding="utf-8")
    check("編造引句照樣 rc1", run(v, "quote-check", str(bad), "--spec", str(snap)).returncode == 1, "")


def t_quote_check_nested_quotes_and_min_length():
    """[T8 終審 r1 findings 修復](loop code-dloop-redesign r1;s1-F2+否決席-F1 機械證實)

    ①巢狀『』截斷:原 regex `[^」』]+` 在引句內的『』就停,「規則『甲」被當前綴錨到
      → 編造的後半永遠沒被驗(錨定紀律被架空)。修:引句止於同型閉引號(「…」內容許『』)。
    ②引句下限:norm 後 <10 字判 miss(否決席:一字引句「的」必然錨得到,gate 照樣「全數錨定」)。
    翻紅釘:①還原 regex → 巢狀編造案例翻紅;②拔下限 → 一字引句案例翻紅。"""
    v = mkvault()
    d = v / "Projects"
    snap = d / "nsnap.md"
    snap.write_text("本規則「規則『甲』其實存在而且一直都存在」云云,而且的確如此。\n", encoding="utf-8")
    # ① 巢狀:真引句(含『』全文)判 ok;編造尾巴判 miss
    ok_rpt = d / "nok.md"
    ok_rpt.write_text("引句：「規則『甲』其實存在而且一直都存在」\n", encoding="utf-8")
    r1 = run(v, "quote-check", str(ok_rpt), "--spec", str(snap))
    check("★前置★ 現場成立:含巢狀『』的真引句全文判 ok(rc0)", r1.returncode == 0,
          f"rc={r1.returncode}\n{r1.stdout[:200]}")
    bad_rpt = d / "nbad.md"
    bad_rpt.write_text("引句：「規則『甲』其實根本不存在,是編出來的」\n", encoding="utf-8")
    r2 = run(v, "quote-check", str(bad_rpt), "--spec", str(snap))
    check("★巢狀『』不截斷:編造尾巴的引句必 miss(rc1;原截成「規則『甲」前綴假 ok)★",
          r2.returncode == 1, f"rc={r2.returncode}\n{r2.stdout[:200]}")
    # ② 下限:一字引句(快照確實含「的」)→ miss
    tiny = d / "ntiny.md"
    tiny.write_text("引句：「的」\n", encoding="utf-8")
    r3 = run(v, "quote-check", str(tiny), "--spec", str(snap))
    check("★引句 norm 後 <10 字判 miss(rc1;錨定紀律的 ≥10 字轉機械)★",
          r3.returncode == 1, f"rc={r3.returncode}\n{r3.stdout[:200]}")


def t_disposal_snapshot_provenance():
    """[T3 凍結快照](spec:Projects/design-loop重設計 三;plan:同名_實作計畫 T3)

    ★釘死反循環場景★:finding 折入真檔後,它的引句在「現檔」裡就存在了——
    對現檔跑 quote-check 會假 ok(循環自證,r1 Codex 折入的洞)。
    ★quote-check 的比對對象必須是派工當下的凍結快照★:同一份報告,
    對快照跑必 miss(引句是審查員指出「該加而沒有」的內容)、對折入後現檔跑會 ok
    ——兩者 rc 不同,就是這條合約的鑑別力所在。"""
    v = mkvault()
    d = v / "Projects"
    snap = d / "t3snap.md"       # 派工當下凍結
    snap.write_text("# spec v1\n規則甲：只在 0 命中時回退。\n", encoding="utf-8")
    rpt = d / "t3rpt.md"
    # 審查員的 finding:引的是它「建議加入」的句子(快照裡沒有)
    rpt.write_text("[major] 缺逃生口\n引句：「規則乙：加 --escape 逃生口。」\n", encoding="utf-8")
    cur = d / "t3cur.md"         # 折入後的現檔:把 finding 建議的句子折進去了
    cur.write_text("# spec v2\n規則甲：只在 0 命中時回退。\n規則乙：加 --escape 逃生口。\n", encoding="utf-8")

    r_snap = run(v, "quote-check", str(rpt), "--spec", str(snap))
    r_cur = run(v, "quote-check", str(rpt), "--spec", str(cur))
    check("★前置★ 現場成立:對折入後現檔跑會假 ok(循環自證真的會發生)", r_cur.returncode == 0,
          f"rc={r_cur.returncode}")
    check("★對凍結快照跑必 miss(rc1)——這就是「必須對快照驗」合約的鑑別力★",
          r_snap.returncode == 1, f"rc={r_snap.returncode}")

    # record 帶 --snapshot 落帳的 sha256 可重算=快照身分可稽核
    import json as _j
    lid = f"t3-{_M1U}"
    run(v, "canary", "record", "caught", "--loop", lid, "--severity", "minor",
        "--auditor", "s1", "--report", str(rpt), "--snapshot", str(snap), expect_rc=0)
    last = _j.loads((v.parent / ".canary-log.jsonl").read_text(encoding="utf-8").strip().splitlines()[-1])
    check("snapshot_sha256 落帳且可重算(快照身分可稽核)",
          last.get("snapshot_sha256") == _sha256_of(snap), str(last)[:200])


def t_canary_record_disposal_fields_optional():
    """[T1 相容雙讀](spec:Projects/design-loop重設計 六;plan:同名_實作計畫 T1)

    record 新增六個★選配★欄(--report/--snapshot/--findings-set/--folded-set/
    --accepted-set/--accept-reason)。鐵則:★全部不給=行為與今日完全相同★——
    這是「相容雙讀先行」的第①包,任何中間版本不得打壞現行 design/code-loop 呼叫。

    寫側驗證(給了才驗,違反 rc2):
      folded∩accepted=∅ ∧ folded∪accepted==findings_set(集合核對,非總數——
      r1 Codex:只核總數可被重複計數/虛構項配平);accepted 逐 id 附非空理由;
      severity==blocker ⇒ accepted 必空(d1);report/snapshot 檔案存在且非空。

    還原翻紅釘:把「聯集==findings_set」檢查還原掉 → 「缺 id 未處置必 rc2」翻紅。"""
    import json as _j
    v = mkvault()
    lid = f"dsp-{_M1U}"
    rpt = v / "Projects" / "rpt.md"
    rpt.write_text("[major] x\n引句：「abc」\n", encoding="utf-8")
    snap = v / "Projects" / "snap.md"
    snap.write_text("spec snapshot abc\n", encoding="utf-8")

    # ★相容鐵則★:零新參的舊呼叫 rc0,且記錄裡無任何新鍵
    r0 = run(v, "canary", "record", "caught", "--loop", lid, "--severity", "minor",
             "--findings", "2", "--auditor", "s1", expect_rc=0)
    log = (v.parent / ".canary-log.jsonl").read_text(encoding="utf-8").strip().splitlines()
    last = _j.loads(log[-1])
    check("★舊呼叫不變★:零新參 rc0 且無新鍵",
          not any(k in last for k in ("report_path", "snapshot_path", "findings_set",
                                      "folded_set", "accepted_set", "accept_reasons")), str(last)[:200])

    # 完整合法寫入:全欄落帳且 sha256 可重算
    r1 = run(v, "canary", "record", "caught", "--loop", lid, "--severity", "major",
             "--auditor", "s1", "--report", str(rpt), "--snapshot", str(snap),
             "--findings-set", "a,b,c", "--folded-set", "a,b", "--accepted-set", "c",
             "--accept-reason", "c=文件精度級,成本不值", expect_rc=0)
    last = _j.loads((v.parent / ".canary-log.jsonl").read_text(encoding="utf-8").strip().splitlines()[-1])
    check("★前置★ 現場成立:六欄全落帳", last.get("findings_set") == ["a", "b", "c"]
          and last.get("folded_set") == ["a", "b"] and last.get("accepted_set") == ["c"]
          and last.get("accept_reasons", {}).get("c") and last.get("report_sha256")
          and last.get("snapshot_sha256"), str(last)[:300])
    check("sha256 可重算(留痕的最低資格)", last["report_sha256"] == _sha256_of(rpt), "")

    # 機械核對逐條 rc2
    bad = [
        # ★b 的理由給齊,讓「缺 b 未處置」成為唯一能 rc2 的路——否則聯集檢查被拔掉時
        # 理由檢查會代打,翻紅釘假紅(2026-08-04 第一版就中了這型:斷言測的不是它宣稱的那條)
        (["--findings-set", "a,b,c", "--folded-set", "a", "--accepted-set", "c",
          "--accept-reason", "c=有理由"],
         "★缺 b 未處置(聯集≠全集)必 rc2★"),
        (["--findings-set", "a,b", "--folded-set", "a,b", "--accepted-set", "b"],
         "folded∩accepted 非空必 rc2"),
        (["--findings-set", "a", "--folded-set", "a", "--accepted-set", "",
          "--accept-reason", "x=y"], "理由鍵集合≠accepted_set 必 rc2"),
        (["--findings-set", "a,a", "--folded-set", "a,a"], "findings_set 重複 id 必 rc2"),
    ]
    for extra, name in bad:
        rr = run(v, "canary", "record", "caught", "--loop", lid, "--severity", "minor",
                 "--auditor", "s1", *extra)
        check(name, rr.returncode == 2, f"rc={rr.returncode} {rr.stderr[:120]}")
    # accepted 有 id 但沒給理由
    rr = run(v, "canary", "record", "caught", "--loop", lid, "--severity", "minor",
             "--auditor", "s1", "--findings-set", "a,b", "--folded-set", "a", "--accepted-set", "b")
    check("accepted 無理由必 rc2(空殼放行擋在寫側)", rr.returncode == 2, rr.stderr[:120])
    # d1:blocker 不得 accepted
    rr = run(v, "canary", "record", "caught", "--loop", lid, "--severity", "blocker",
             "--auditor", "s1", "--findings-set", "a", "--folded-set", "", "--accepted-set", "a",
             "--accept-reason", "a=想放行")
    check("★d1:blocker 輪 accepted 非空必 rc2★", rr.returncode == 2, rr.stderr[:120])
    # 留痕檔不存在
    rr = run(v, "canary", "record", "caught", "--loop", lid, "--severity", "minor",
             "--auditor", "s1", "--report", str(v / "nope.md"))
    check("--report 指向不存在檔必 rc2", rr.returncode == 2, rr.stderr[:120])
    # blocker+全折(accepted 空)合法——d1 只擋 accepted,不擋折
    # (T6 生效後:本 loop 已定錨,須帶留痕——正確行為,非誤傷)
    run(v, "canary", "record", "caught", "--loop", lid, "--severity", "blocker",
        "--auditor", "s1", "--findings-set", "a", "--folded-set", "a",
        "--report", str(rpt), "--snapshot", str(snap), expect_rc=0)


def t_loop_next_legacy_emits_a_command_that_actually_runs():
    """★工具吐給你的指令必須跑得動——不然它會教出錯誤的習慣★(2026-08-04)

    `loop next` 的 `record_cmd` 是「複製貼上用」的模板。但它原本無條件吐
    `--tier {eff_tier}`,而 `legacy` ★不在 `--tier` 的 choices 裡★(只有
    light/standard/high)——所以 legacy loop 拿到的是一條 argparse 當場擋掉的指令。

    ★為什麼這比「一條壞指令」嚴重★:碰到 rc2 之後最自然的修復是「把 --tier 拿掉
    再跑」。拿掉就記不上定錨 → 下一輪 next 又推成 legacy → 又吐一條跑不動的指令。
    ★這個 bug 自己維持自己★。2026-08 三個走循序的 loop 全數 `tier=None`,即此循環
    的產物;其中 code-slim-python 吃到 legacy 的 cap 6(standard 是 3)才被逼停。

    ★驗行為(不是驗字串)★:把 next 吐的 record_cmd 佔位符填掉、★真的跑一次★,
    必須 rc0。字串斷言只證「長得對」,真跑才證「用得了」。
    同時驗 light/standard 仍照舊帶 --tier(修法不得誤傷可宣告的三檔)。"""
    import json as _j
    v = mkvault()
    spec = v / "Projects" / "lgspec.md"
    spec.write_text("legacy tier spec\n", encoding="utf-8")
    h = _sha256_of(spec)
    lid = f"lg-{_M1U}"

    # 造一筆 legacy 格式舊帳(不帶 --round、不帶 --tier)→ next 會推導成 legacy
    run(v, "canary", "record", "caught", "--loop", lid, "--severity", "clean",
        "--findings", "0", "--auditor", "s1", expect_rc=0)
    r = run(v, "loop", "next", lid, "--json", "--spec", str(spec), "--repo", str(v.parent))
    d = _j.loads(r.stdout)
    check("★前置★ 現場成立:確實走到 legacy 推導路徑且吐得出模板(不是別的 tier / 別的 phase 混過去)",
          d["tier"] == "legacy" and d["phase"] == "plant-canary", r.stdout[:300])

    cmd = d["record_cmd"]
    check("★legacy 不得出現在 record_cmd 的 --tier★(它不是可宣告值)",
          "--tier legacy" not in cmd, cmd)

    # ★真跑★:填掉佔位符,原樣執行 next 給的指令
    filled = (cmd.replace("caught|missed", "caught").replace("<席>", "s2")
                 .replace("<s>", "clean").replace("<M>", "0")
                 .replace("<計劃節點.md>", str(spec)).replace("<sha256>", h)
                 .replace("<這輪審了幾行>", "10"))
    argv = filled.split()
    check("★前置★ 現場成立:填完沒有殘留佔位符(不然是在跑別的東西)",
          "<" not in filled and argv[0] == "lumos", filled)
    rr = run(v, *argv[1:])
    check("★next 吐的指令必須真的跑得動★(rc0)", rr.returncode == 0,
          f"rc={rr.returncode} cmd={filled}\n{rr.stderr[:300]}")

    check("★要講清楚這個 loop 補標不了、得開新 id★(不然人只會困惑地把旗標拿掉)",
          "開新 loop id" in d.get("tier_hint", "") and "cap 6" in d.get("tier_hint", ""),
          d.get("tier_hint", "")[:200])

    # 反誤傷:可宣告的三檔仍須照舊帶 --tier
    ds = _j.loads(run(v, "loop", "next", f"lgs-{_M1U}", "--tier", "standard", "--json").stdout)
    check("★standard 仍要帶 --tier★(修法不得誤傷可宣告檔)",
          "--tier standard" in ds["record_cmd"] and "tier_hint" not in ds, ds["record_cmd"])
    dli = _j.loads(run(v, "loop", "next", f"lgl-{_M1U}", "--tier", "light", "--json").stdout)
    check("★light 仍要帶 --tier★", "--tier light" in dli["record_cmd"], dli["record_cmd"])


def t_need_src_guards_cannot_silently_disable_coverage():
    """★守衛的失敗模式是「放行」,所以它自己壞掉時必須大聲★(2026-08-02)

    `_need_src(...)` 讓「來源 repo 專用」的測試在消費端專案乾淨 skip 而非假紅
    （實測 Landmark:vendored 套件更新後 91 紅,全是來源專用產物缺席；本機制後
    降為 0 紅 / 61 skip）。但它有一個致命的失敗模式：★如果來源 repo 自己少了
    某個產物，這些測試會在來源端也靜默 skip，覆蓋率無聲蒸發★——而 skip 不會
    讓任何閘翻紅。

    這正是昨天那條教訓的同型：**失敗模式是放行的守衛，壞掉時不會有人知道**。

    ★驗行為★：直接掃本檔案裡所有 `_need_src("...")` 的實際呼叫參數，逐一斷言
    那個路徑在來源 repo 真的存在。★自我維護★——之後任何人新增一處 `_need_src`，
    這條測試自動涵蓋它，不需要維護第二份清單。

    ★此測試自己也必須在來源 repo 跑得到★（不加 `_need_src` 守門，否則它會在
    消費端 skip 掉，而那正是它該沉默的地方——消費端本來就缺那些產物）。"""
    import re as _re9
    repo = Path(GRAPHCTL).resolve().parent.parent
    src = Path(__file__).resolve().read_text(encoding="utf-8")
    # ★只認「獨立成行的呼叫」★——不然 docstring 裡提到的 `_need_src(...)` 也會被掃進來
    # (第一版就踩到,掃出一個叫 '...' 的假路徑)。
    rels = sorted(set(_re9.findall(r'^\s*_need_src\(\s*"([^"]+)"', src, _re9.M)))
    check("★前置★ 掃得到 _need_src 的呼叫參數(掃不到=這條測試自己失效了)",
          len(rels) >= 5, f"只掃到 {rels}")
    if not (repo / "skills" / "lumos-project-notes").is_dir():
        # 消費端:那些產物本來就沒有,此測試無意義(且下面的斷言必假)
        raise _SrcOnly("需要來源 repo(本測試只在來源端有意義)")
    missing = [r for r in rels if not (repo / r).exists()]
    check("★來源 repo 必須擁有每一個被守門的產物★"
          "(缺了 → 對應測試會在來源端也靜默 skip、覆蓋無聲蒸發)",
          not missing, f"缺: {missing}")


def t_canary_scope_lines_records_review_size():
    """★把缺的變數記下來★(2026-08-02):canary 抓到只證審查員醒著,但外部實測指出
    ★東西越多越抓不到★是最主導的因素(arXiv 2606.15689:抓得到合成缺陷不可靠地
    預測抓得到真實缺陷,且 diff 大小是主導混淆變數)。本專案十輪 code-loop 的 diff
    從 332 到 2770 行——★在帳上長得一模一樣★,等於無法回答「小 diff 上的 caught
    是不是灌水」。

    這一欄★不進任何 gate、不改任何判定★,純 telemetry;目的只有一個:讓
    「caught 率 vs 被審規模」這個問題日後答得出來。

    ★驗行為★:①給了就要真的寫進帳本(不是只收下不存)②不給時★整個鍵不存在★
    (同 --findings 慣例,不寫 null 汙染舊帳)③負數擋下 rc2 ④★不影響 gate★——
    帶不帶這欄,loop status 的判定必須完全一樣。"""
    import json as _j
    v = mkvault()
    spec = v / "Projects" / "scopespec.md"
    spec.write_text("scope spec\n", encoding="utf-8")
    h = _sha256_of(spec)
    log = v.parent / ".canary-log.jsonl"
    lid = f"sc-{_M1U}"

    run(v, "canary", "record", "caught", "--loop", lid, "--severity", "clean", "--findings", "0",
        "--auditor", "s1", "--reviewed", h, "--spec", str(spec), "--scope-lines", "2770", expect_rc=0)
    rows = [_j.loads(l) for l in log.read_text(encoding="utf-8").splitlines() if l.strip()]
    mine = [r for r in rows if r.get("loop") == lid]
    check("★給了就要真的寫進帳本★", mine and mine[-1].get("scope_lines") == 2770,
          str(mine[-1] if mine else None)[:200])

    run(v, "canary", "record", "caught", "--loop", lid, "--severity", "clean", "--findings", "0",
        "--auditor", "s2", "--reviewed", h, "--spec", str(spec), expect_rc=0)
    rows = [_j.loads(l) for l in log.read_text(encoding="utf-8").splitlines() if l.strip()]
    mine = [r for r in rows if r.get("loop") == lid]
    check("★不給時整個鍵不存在(不寫 null 汙染舊帳)★", "scope_lines" not in mine[-1],
          str(mine[-1])[:200])

    r = run(v, "canary", "record", "caught", "--loop", lid, "--severity", "clean", "--findings", "0",
            "--auditor", "s3", "--reviewed", h, "--spec", str(spec), "--scope-lines", "-1")
    check("★負數擋下 rc2★", r.returncode == 2, r.stderr[-150:])

    # ★不影響 gate★:帶與不帶這欄,收斂判定必須一樣
    g = run(v, "loop", "status", lid, "--need", "2", "--gate", "--spec", str(spec),
            "--repo", str(v.parent))
    lid2 = f"sc2-{_M1U}"
    for a in ("t1", "t2"):
        run(v, "canary", "record", "caught", "--loop", lid2, "--severity", "clean", "--findings", "0",
            "--auditor", a, "--reviewed", h, "--spec", str(spec), expect_rc=0)
    g2 = run(v, "loop", "status", lid2, "--need", "2", "--gate", "--spec", str(spec),
             "--repo", str(v.parent))
    check("★純 telemetry:帶了 scope-lines 的 loop 與沒帶的,gate 判定一致★",
          g.returncode == g2.returncode, f"帶={g.returncode} 沒帶={g2.returncode}")

    # ── 軟上限:超標要在帳上留記號並喊出來 ──
    lid3 = f"sc4-{_M1U}"
    ro = run(v, "canary", "record", "caught", "--loop", lid3, "--severity", "clean", "--findings", "0",
             "--auditor", "big", "--reviewed", h, "--spec", str(spec), "--scope-lines", "2778", expect_rc=0)
    rows = [_j.loads(l) for l in log.read_text(encoding="utf-8").splitlines() if l.strip()]
    big = [r for r in rows if r.get("loop") == lid3][-1]
    check("★超過軟上限要在帳上標 scope_oversize★(caught 是弱證據,事後查得到)",
          big.get("scope_oversize") is True, str(big)[:200])
    check("★而且要當場喊出來★(只記不喊等於沒人知道)",
          "scope_oversize" in ro.stderr or "軟上限" in ro.stderr, ro.stderr[-200:])
    check("★仍然照常留痕 rc0★(軟上限不擋——輪已經跑完,擋也來不及)",
          ro.returncode == 0, ro.stderr[-150:])

    # ★反誤傷★:沒超標不得標記、不得喊
    lid4 = f"sc5-{_M1U}"
    rs = run(v, "canary", "record", "caught", "--loop", lid4, "--severity", "clean", "--findings", "0",
             "--auditor", "small", "--reviewed", h, "--spec", str(spec), "--scope-lines", "415", expect_rc=0)
    rows = [_j.loads(l) for l in log.read_text(encoding="utf-8").splitlines() if l.strip()]
    small = [r for r in rows if r.get("loop") == lid4][-1]
    check("★沒超標不得標記(反誤傷)★", "scope_oversize" not in small, str(small)[:200])
    check("★沒超標不得喊(反噪音)★", "軟上限" not in rs.stderr, rs.stderr[-150:])

    # ★預防端★:警告要在派工之前出現,不是記帳之後才喊
    nx0 = run(v, "loop", "next", f"sc6-{_M1U}", "--tier", "standard")
    check("★loop next 必須在派工前就給量尺★(記帳時才喊已經來不及,輪跑完了)",
          "scope_cap" in nx0.stdout and "wc -l" in nx0.stdout, nx0.stdout[-300:])

    # loop next 的模板要提到它(否則沒人知道有這欄——cluster 帳 316:1 的教訓)
    nx = run(v, "loop", "next", f"sc3-{_M1U}", "--tier", "standard")
    check("★loop next 的記帳模板必須帶上它(不然沒人會用)★",
          "--scope-lines" in nx.stdout, nx.stdout[-300:])


def t_m1_loop_next():
    """M1包 #1 loop next:零記錄 rc2/plant-canary/tier 定錨+衝突 rc2/escalate/gate-pending/converged/cap/min-seats/json。"""
    print("t_m1_loop_next")
    import json as _j
    v = mkvault()
    spec = v / "Projects" / "nspec.md"
    spec.write_text("next spec\n", encoding="utf-8")
    h = _sha256_of(spec)
    # 零記錄無 --tier rc2
    r = run(v, "loop", "next", f"nx-{_M1U}")
    check("零記錄無 tier rc2", r.returncode == 2)
    # 零記錄+tier light → plant-canary N=1
    r = run(v, "loop", "next", f"nx-{_M1U}", "--tier", "light", "--json")
    d = _j.loads(r.stdout)
    check("零記錄 plant-canary N=1", d["phase"] == "plant-canary" and d["round"] == 1 and r.returncode == 1)
    check("light width/cap 映射", d["width"] == 1 and d["cap"] == 2)
    # tier 定錨:record 帶 --tier light → next 無 --tier 讀定錨(帶 auditor:空席不計已生效)
    run(v, "canary", "record", "caught", "--loop", f"nx-{_M1U}", "--severity", "clean", "--findings", "0",
        "--auditor", "solo", "--reviewed", h, "--spec", str(spec), "--tier", "light", expect_rc=0)
    r = run(v, "loop", "next", f"nx-{_M1U}", "--json", "--spec", str(spec), "--repo", str(v.parent))
    d = _j.loads(r.stdout)
    check("tier 定錨讀取", d["tier"] == "light")
    check("light 收斂 → converged rc0", d["phase"] == "converged" and r.returncode == 0)
    # 定錨衝突 rc2
    r = run(v, "loop", "next", f"nx-{_M1U}", "--tier", "standard")
    check("tier 衝突 rc2", r.returncode == 2)
    # 資訊不足 → gate-pending(先於 cap)
    r = run(v, "loop", "next", f"nx-{_M1U}", "--json")
    d = _j.loads(r.stdout)
    check("缺 --spec → gate-pending rc1", d["phase"] == "gate-pending" and r.returncode == 1)
    # escalate:light ratchet 最先短路
    run(v, "canary", "record", "caught", "--loop", f"nx2-{_M1U}", "--severity", "major", "--findings", "2",
        "--reviewed", h, "--spec", str(spec), "--tier", "light", expect_rc=0)
    r = run(v, "loop", "next", f"nx2-{_M1U}", "--json", "--spec", str(spec), "--repo", str(v.parent))
    d = _j.loads(r.stdout)
    check("light ratchet → escalate", d["phase"] == "escalate" and r.returncode == 1)
    # cap-reached:light cap=2 兩輪未收斂(資訊充分)
    run(v, "canary", "record", "missed", "--loop", f"nx3-{_M1U}", "--tier", "light", expect_rc=0)
    run(v, "canary", "record", "missed", "--loop", f"nx3-{_M1U}", expect_rc=0)
    r = run(v, "loop", "next", f"nx3-{_M1U}", "--json", "--spec", str(spec), "--repo", str(v.parent))
    d = _j.loads(r.stdout)
    check("cap-reached", d["phase"] == "cap-reached" and r.returncode == 1)
    # min-seats:panel 同席灌筆不計——high 定錨,同一 auditor 5 筆
    for i in range(5):
        run(v, "canary", "record", "caught", "--loop", f"nx4-{_M1U}", "--round", "r1", "--auditor", "same",
            "--severity", "clean", "--findings", "0", "--capture-counts", "1",
            "--reviewed", h, "--spec", str(spec), "--tier", "high", expect_rc=0)
    r = run(v, "loop", "status", f"nx4-{_M1U}", "--panel", "--min-seats", "5", "--spec", str(spec), "--repo", str(v.parent))
    check("同席灌筆 min-seats FAIL", r.returncode == 1 and "席" in r.stdout)


def t_m1_codeloop_r1_fixes():
    """code-loop 補審 r1 折入(loop機械脊椎M1包):cluster 路徑轉發/tier-格式衝突 rc2/
    light 空 auditor 不計席/light 席數委派/panel+light 成本區。"""
    print("t_m1_codeloop_r1_fixes")
    v = mkvault()
    spec = v / "Projects" / "cspec.md"
    spec.write_text("c spec\n", encoding="utf-8")
    h = _sha256_of(spec)
    # 1. cluster 模式不得繞過 min-seats/G3:同席 2 筆 caught+clusters 無 disputed,無 hash
    for i in range(2):
        run(v, "canary", "record", "caught", "--loop", f"cl-{_M1U}", "--round", "r1", "--auditor", "same",
            "--severity", "clean", "--findings", "0",
            *(["--clusters", "x=resolved"] if i == 0 else []), expect_rc=0)
    r = run(v, "loop", "status", f"cl-{_M1U}", "--panel", "--min-seats", "5", "--spec", str(spec), "--repo", str(v.parent))
    check("cluster 模式 min-seats/G3 不被繞過", r.returncode == 1 and ("席" in r.stdout or "hash" in r.stdout or "綁" in r.stdout), r.stdout[-200:])
    # 2. tier=high 定錨但記錄為 legacy 格式(漏 --round) → next rc2 格式衝突,不得走鬆閘
    run(v, "canary", "record", "caught", "--loop", f"tf-{_M1U}", "--severity", "clean", "--findings", "0",
        "--reviewed", h, "--spec", str(spec), "--tier", "high", expect_rc=0)
    r = run(v, "loop", "next", f"tf-{_M1U}", "--spec", str(spec), "--repo", str(v.parent))
    check("high 定錨+legacy 格式 → rc2", r.returncode == 2, f"rc={r.returncode}")
    # 3. light 空 auditor 不計席:無 --auditor 的 caught 乾淨輪,min-seats=1 應 FAIL
    run(v, "canary", "record", "caught", "--loop", f"la-{_M1U}", "--severity", "clean", "--findings", "0",
        "--reviewed", h, "--spec", str(spec), expect_rc=0)
    r = run(v, "loop", "status", f"la-{_M1U}", "--light", "--gate", "--min-seats", "1", "--spec", str(spec), "--repo", str(v.parent))
    check("light 空 auditor 不計席 FAIL", r.returncode == 1 and "席" in r.stdout, r.stdout[-150:])
    # 4. next 對 light 委派 min_seats=1:同上帳但經 next(缺 auditor 不得 converged)
    run(v, "canary", "record", "caught", "--loop", f"ln-{_M1U}", "--severity", "clean", "--findings", "0",
        "--reviewed", h, "--spec", str(spec), "--tier", "light", expect_rc=0)
    r = run(v, "loop", "next", f"ln-{_M1U}", "--json", "--spec", str(spec), "--repo", str(v.parent))
    import json as _j
    d = _j.loads(r.stdout)
    check("next light 委派席數(缺 auditor 不 converged)", d["phase"] != "converged", r.stdout[:150])
    # 5. panel 與 light 路徑也印成本區
    for a in ("p1", "p2"):
        run(v, "canary", "record", "caught", "--loop", f"cp-{_M1U}", "--round", "r1", "--auditor", a,
            "--severity", "clean", "--findings", "0", "--tokens", "100",
            *(["--capture-counts", "1"] if a == "p1" else []), expect_rc=0)
    r = run(v, "loop", "status", f"cp-{_M1U}", "--panel")
    check("panel 路徑印成本區", "成本" in r.stdout, r.stdout[-150:])
    run(v, "canary", "record", "caught", "--loop", f"cli-{_M1U}", "--severity", "clean", "--findings", "0",
        "--reviewed", h, "--spec", str(spec), "--auditor", "solo", "--tokens", "50", expect_rc=0)
    r = run(v, "loop", "status", f"cli-{_M1U}", "--light", "--gate", "--spec", str(spec), "--repo", str(v.parent))
    check("light 路徑印成本區", "成本" in r.stdout, r.stdout[-150:])


def t_m1_codeloop_r2_fixes():
    """code-loop 補審 r2 折入:G3 OSError rc2 對稱/next 損壞守衛/legacy gate min-seats。"""
    print("t_m1_codeloop_r2_fixes")
    v = mkvault()
    spec = v / "Projects" / "r2spec.md"
    spec.write_text("r2\n", encoding="utf-8")
    h = _sha256_of(spec)
    # 1. panel/light 對 --spec 不可讀 → rc2(非 rc1;與 legacy G1 對稱)
    run(v, "canary", "record", "caught", "--loop", f"os-{_M1U}", "--severity", "clean", "--findings", "0",
        "--auditor", "a1", "--reviewed", h, "--spec", str(spec), expect_rc=0)
    r = run(v, "loop", "status", f"os-{_M1U}", "--light", "--gate", "--spec", str(v / "Projects"), "--repo", str(v.parent))
    check("light --spec 目錄 rc2", r.returncode == 2, f"rc={r.returncode}")
    for a in ("a1", "a2"):
        run(v, "canary", "record", "caught", "--loop", f"osp-{_M1U}", "--round", "r1", "--auditor", a,
            "--severity", "clean", "--findings", "0", "--capture-counts", "1",
            "--reviewed", h, "--spec", str(spec), expect_rc=0)
    r = run(v, "loop", "status", f"osp-{_M1U}", "--panel", "--spec", str(v / "Projects"), "--repo", str(v.parent))
    check("panel --spec 目錄 rc2", r.returncode == 2, f"rc={r.returncode}")
    # 2. next 缺 --spec 也要跑帳本損壞守衛:round r1→r2→r1 非連續
    for rid in ("r1", "r2", "r1"):
        run(v, "canary", "record", "caught", "--loop", f"cor-{_M1U}", "--round", rid, "--auditor", "x",
            "--severity", "clean", "--findings", "0", "--tier", "standard", expect_rc=0)
    r = run(v, "loop", "next", f"cor-{_M1U}")
    check("next 損壞帳 rc2(缺 --spec 也擋)", r.returncode == 2, f"rc={r.returncode}")
    # 3. legacy gate 消費 --min-seats(無 auditor → 席數不足 FAIL)
    for i in range(2):
        run(v, "canary", "record", "caught", "--loop", f"lm-{_M1U}", "--severity", "clean", "--findings", "0",
            "--reviewed", h, "--spec", str(spec), expect_rc=0)
    r = run(v, "loop", "status", f"lm-{_M1U}", "--need", "2", "--gate", "--min-seats", "1",
            "--spec", str(spec), "--repo", str(v.parent))
    check("legacy gate min-seats 生效", r.returncode == 1 and "席" in r.stdout, r.stdout[-150:])
    # r3 折入:逐輪驗非空(一有一空不得以聯集過)
    run(v, "canary", "record", "caught", "--loop", f"lw-{_M1U}", "--severity", "minor", "--findings", "1",
        "--auditor", "solo", "--reviewed", h, "--spec", str(spec), expect_rc=0)
    run(v, "canary", "record", "caught", "--loop", f"lw-{_M1U}", "--severity", "clean", "--findings", "0",
        "--reviewed", h, "--spec", str(spec), expect_rc=0)   # 第二輪空席
    r = run(v, "loop", "status", f"lw-{_M1U}", "--need", "2", "--gate", "--min-seats", "1",
            "--spec", str(spec), "--repo", str(v.parent))
    check("legacy 一有一空逐輪驗 FAIL", r.returncode == 1 and "席" in r.stdout, r.stdout[-150:])
    # r3 折入:--min-seats 非正整數 rc2
    r = run(v, "loop", "status", f"lw-{_M1U}", "--need", "2", "--gate", "--min-seats", "-1",
            "--spec", str(spec), "--repo", str(v.parent))
    check("min-seats 負值 rc2", r.returncode == 2, f"rc={r.returncode}")


def t_show():
    """show 讀取入口(Projects/lumos-show讀取入口_計劃 八項):找到全文/找不到 rc2/--body-only/
    模糊名沿 env.find/唯讀(節點檔不變,usage-log 為預期副作用)/派發組迴歸/重開檔失敗 rc2 無
    traceback/無 frontmatter 檔 --body-only 印整檔。"""
    print("t_show")
    v = mkvault()
    write(v, "Systems/秀測試.md", "type: system\nstatus: done", "# 秀測試\nbody-內文-唯一標記\n")
    # 1. 找到 → rc0、含 frontmatter --- 與 body 標題行
    r = run(v, "show", "秀測試", expect_rc=0)
    check("show 找到 rc0 含 frontmatter", r.stdout.startswith("---") and "type: system" in r.stdout)
    check("show 含 body 標題行", "# 秀測試" in r.stdout and "body-內文-唯一標記" in r.stdout)
    # 2. 找不到 → stderr 訊息 + rc2
    r = run(v, "show", "不存在的節點名", expect_rc=2)
    check("show 找不到 rc2+stderr", "找不到筆記" in r.stderr)
    # 3. --body-only → 無 frontmatter 鍵行、有 body
    r = run(v, "show", "秀測試", "--body-only", expect_rc=0)
    check("body-only 無 frontmatter 鍵行", "type: system" not in r.stdout and not r.stdout.startswith("---"))
    check("body-only 含 body", "body-內文-唯一標記" in r.stdout)
    # 4. 模糊名(同名多篇)沿 env.find:stderr 警告、取第一篇、rc0
    write(v, "Projects/秀測試.md", "type: project\nstatus: doing", "# 秀測試P\n")
    r = run(v, "show", "秀測試", expect_rc=0)
    check("模糊名沿 env.find(警告+取第一)", "同名筆記" in r.stderr and r.returncode == 0)
    # 5. 唯讀:節點檔內容不變(usage-log append 為預期副作用,不斷言其無)
    p = v / "Systems" / "秀測試.md"
    before = p.read_bytes()
    run(v, "show", "Systems/秀測試", expect_rc=0)
    check("唯讀:節點檔不變", p.read_bytes() == before)
    # 6. 派發組迴歸:context 照常
    r = run(v, "context", "Systems/秀測試", expect_rc=0)
    check("派發組迴歸 context 不受影響", "Systems/秀測試" in r.stdout)
    # 7. 重開檔失敗:vault 載入後檔案消失 → rc2 無 traceback
    #    (load_vault 在 CLI 進程內先掃;要模擬「解析成功但重開失敗」,用 symlink 指向不存在目標——
    #     rglob 掃得到、read_text 會炸;load_vault 容忍(lint 記讀檔失敗)但 rel 仍可解析)
    broken = v / "Systems" / "斷鏈.md"
    broken.symlink_to(v / "Systems" / "不存在的目標檔.md")
    r = run(v, "show", "斷鏈")
    check("重開檔失敗 rc2", r.returncode == 2, f"rc={r.returncode}")
    check("重開檔失敗 stderr 無 traceback", "讀檔失敗" in r.stderr and "Traceback" not in r.stderr, r.stderr[:120])
    # 8. 無 frontmatter 檔 --body-only → 印整檔
    (v / "Systems" / "裸檔.md").write_bytes("# 裸檔標題\n純內文無fm\n".encode("utf-8"))
    r = run(v, "show", "裸檔", "--body-only", expect_rc=0)
    check("無 frontmatter --body-only 印整檔", "# 裸檔標題" in r.stdout and "純內文無fm" in r.stdout)




def t_docs_enumeration_drift():
    """文件裡的「手寫列舉/數字」對機械事實的漂移守衛(2026-07-29 使用者指出:
    有守衛的當場被咬住、沒守衛的全漏 → 把守衛面從命令數推廣到三類散落事實)。
    通則:凡文件宣稱一個可從碼機械推導的清單/數字,就該有一條這樣的測試。"""
    _need_src("skills/lumos-project-notes")
    import re as _re
    from pathlib import Path as _P
    root = _P(__file__).resolve().parent.parent
    src = (root / "scripts" / "lumos").read_text(encoding="utf-8")

    # ① 治理帳數:cmd_gov 實際 load() 幾支 vs 文件/docstring 宣稱
    gov_body = src[src.index("def cmd_gov("):src.index("def cmd_gov(") + 6000]
    n_sources = len(_re.findall(r"^\s*load\(", gov_body, _re.M))
    zh = "零一二三四五六七八九十"
    claimed = set(_re.findall(r"彙整([一二三四五六七八九十])帳", src))
    claimed |= set(_re.findall(r"讀([一二三四五六七八九十])個本機 JSONL",
                               (root / "README.md").read_text(encoding="utf-8")))
    check("治理帳數:文件宣稱 vs cmd_gov 實際 load 數",
          claimed == {zh[n_sources]}, f"claim={claimed} actual={n_sources}({zh[n_sources]})")

    # ② guard kill verdict 值域:碼裡實際會寫出的 verdict vs reference.md 列舉
    kill_body = src[src.index("def cmd_guard_kill("):src.index("def cmd_guard_audit(")]
    # 抽取要涵蓋三元式:`verdict = "a" if c else "b"` 用舊 regex 只會抓到 "a",
    # 於是 killed_unattributed 整個從值域裡蒸發(2026-07-29:守衛的尺第二次被抓到在漂)。
    # 作法:先取所有 `verdict = <右式>` 整行,再把該行**全部**字串字面量收進來。
    verdicts = set()
    for rhs in _re.findall(r"^\s*verdict\s*=\s*(.+)$", kill_body, _re.M):
        verdicts |= set(_re.findall(r'"([a-z_]+)"', rhs))
    verdicts |= set(_re.findall(r'"verdict": "([a-z_]+)"', kill_body))
    ref = (root / "skills" / "lumos-project-notes" / "reference.md").read_text(encoding="utf-8")
    kill_sec = ref[ref.index("lumos guard kill-add"):ref.index("lumos guard kill-add") + 2000]
    missing = sorted(v for v in verdicts if v not in kill_sec)
    check("kill verdict 值域:碼有的 reference.md 都列了", not missing, f"未列: {missing}")
    # ②b **架構圖節點同受守衛**——只守 skill reference 的舊寫法,讓 Systems/guard-kill.md 一路留著
    # 舊六態與「timed_out 歸 killed」,造出「架構圖錯、code 對」的活例(2026-07-29 外審實錘)。
    gk = root / "docs" / "lumos-toolchain-knowledge" / "Systems" / "guard-kill.md"
    if gk.exists():
        gk_text = gk.read_text(encoding="utf-8")
        gk_missing = sorted(v for v in verdicts if v not in gk_text)
        check("kill verdict 值域:碼有的 Systems/guard-kill.md 都列了",
              not gk_missing, f"未列: {gk_missing}")
        # 態數宣稱也從碼推導(非硬編「七」):文件若寫「N態」而 N≠碼裡的 verdict 數即漂移。
        # 「舊六態」這種標明已作廢的歷史註記合法 → 負向預查排除「舊」。
        want = "零一二三四五六七八九十"[len(verdicts)]
        bad = sorted(set(_re.findall(r"(?<!舊)([一二三四五六七八九十])態", gk_text)) - {want})
        check(f"Systems/guard-kill.md 態數宣稱=碼實際({want}態)",
              not bad, f"文件另寫: {bad}態")

    # ③ Claude hook 生命週期對稱:註冊(HOOK_ENTRIES) ⟺ 複製白名單(_GLOBAL_CLAUDE_HOOKS)
    merge = (root / "scripts" / "merge-claude-settings.py").read_text(encoding="utf-8")
    registered = set(_re.findall(r'_hook_cmd\("([\w.-]+)"\)', merge))
    wl = _re.search(r"_GLOBAL_CLAUDE_HOOKS = \(([^)]*)\)", src)
    copied = set(_re.findall(r'"([\w.-]+)"', wl.group(1) if wl else ""))
    # **雙向**等價,不是單向包含:舊寫法只驗 registered ⊆ copied,「複製了卻沒註冊」的幽靈 hook
    # 照樣過(裝進機器、永不觸發、無人知道它死著)——2026-07-29 外審實錘。
    check("hook 生命週期對稱:註冊的都在複製白名單裡",
          registered <= copied, f"註冊未複製(會被 _prune_dangling 剪掉): {sorted(registered - copied)}")
    check("hook 生命週期對稱:複製白名單裡的都有註冊",
          copied <= registered, f"複製未註冊(幽靈 hook,永不觸發): {sorted(copied - registered)}")
    for name in sorted(registered | copied):
        check(f"hook 檔存在: {name}", (root / "scripts" / "hooks" / "claude" / name).exists(), "")


def t_docs_command_count():
    """文件宣稱的頂層命令數 vs argparse 實數(2026-07-29 外審實錘:ARCHITECTURE 曾停在 44)。"""
    _need_src("skills/lumos-project-notes")
    import re as _re
    from pathlib import Path as _P
    import subprocess as _sp
    root = _P(__file__).resolve().parent.parent
    # 真值取自 **argparse 自己**(`--help` 的 choices),不是對原始碼做 regex 近似:
    # 舊 regex 漏掉迴圈註冊的 links/backlinks,把真數 53 算成 51——**守衛的尺自己在漂**,
    # 於是三份文件寫 51 反而「全綠」(2026-07-29)。reference.md 早寫明「--help 為現行權威」。
    _h = _sp.run([sys.executable, str(root / "scripts" / "lumos"), "--help"],
                 capture_output=True, text=True, timeout=60).stdout
    _m = _re.search(r"\{([a-z0-9,\-]+)\}", _h)
    actual = len(set(_m.group(1).split(","))) if _m else 0
    check("命令數真值取自 --help choices(非原始碼 regex)", actual > 40, f"actual={actual}")
    # 掃**全部活文件**而非手維護清單——固定三檔的舊寫法正是 AGENTS.md(44)與
    # skills/…/reference.md(49)同時漂移卻全綠的原因(2026-07-29 外審實錘)。
    # 排除:外審歸檔(逐字歷史紀錄,不得回改)、架構圖(決策條目會引述當時數字)、.git。
    # golden/ 是凍結語料(過去 loop 的 spec 快照,replay 校準用),與外審歸檔同性質:歷史不得回改。
    skip = ("governance/external-reviews/", "governance/golden/",
            "-knowledge/", "/.git/", "node_modules/")
    scanned = 0
    for p in sorted(root.rglob("*.md")):
        rel = p.relative_to(root).as_posix()
        if any(s.strip("/") in rel for s in skip):
            continue
        text = p.read_text(encoding="utf-8", errors="replace")
        nums = set(_re.findall(r"(\d+) 個頂層命令", text)) | set(
            _re.findall(r"(\d+) top-level commands", text))
        if not nums:
            continue
        scanned += 1
        check(f"{rel} 命令數與 argparse 同步",
              nums == {str(actual)}, f"claim={nums} actual={actual}")
    check("命令數守衛真的掃到活文件(>=4 份)", scanned >= 4, f"scanned={scanned}")


def t_lint_decisions_structure():
    """lint 抓 decisions 結構壞損:id 被吞進 content block(外審實錘型)/entry 非 dict。"""
    v = mkvault()
    # 壞型一:id 縮排進 content 首行(sibling 被吞)
    write(v, "Systems/BadDec.md", """type: system
summary: |-
  KEY:x
decisions:
  - content: |-
    id: d1
      吞掉的內容""", "# b\n")
    r = run(v, "lint", "BadDec")
    check("lint 抓 id-吞進-content", r.returncode != 0 and "decisions" in r.stdout + r.stderr,
          f"{r.returncode} {r.stdout[:150]}")
    # 壞型二:entry 是純字串
    write(v, "Systems/BadDec2.md", """type: system
summary: |-
  KEY:x
decisions:
  - 只是一句話""", "# b\n")
    r = run(v, "lint", "BadDec2")
    check("lint 抓 decisions entry 非 dict", r.returncode != 0
          and "decisions" in r.stdout + r.stderr, f"{r.returncode} {r.stdout[:150]}")
    # 好型:正常結構不誤報
    write(v, "Systems/GoodDec.md", """type: system
summary: |-
  KEY:x
decisions:
  - id: d1
    content: |-
      正常內容
    decided: 2026-07-29""", "# g\n")
    r = run(v, "lint", "GoodDec")
    check("lint 正常 decisions 不誤報", r.returncode == 0, f"{r.returncode} {r.stdout[:150]}")


def _mk_ci_env(gh_body, declare_ci=True, workflow=None):
    """合成 git repo + vault + 假 gh(PATH 攔截) + .lumos/config.json 的 ci 宣告。"""
    import json as _json
    import os as _os
    import subprocess as _sp
    root = Path(tempfile.mkdtemp(prefix="gctl-ci-"))
    def g(*a):
        _sp.run(["git", "-C", str(root), *a], capture_output=True, text=True)
    g("init", "-q"); g("config", "user.email", "t@t"); g("config", "user.name", "t")
    (root / "a.txt").write_text("x", encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "init")
    g("remote", "add", "origin", "https://github.com/acme/demo.git")
    v = root / "docs" / "kg-knowledge"
    (v / "Systems").mkdir(parents=True); (v / "MOC").mkdir()
    (v / "MOC" / "i.md").write_text("---\ntype: moc\n---\n", encoding="utf-8")
    (root / ".lumos").mkdir(exist_ok=True)
    cfg = {}
    if declare_ci:
        cfg["ci"] = {} if workflow is None else {"workflow": workflow}
    (root / ".lumos" / "config.json").write_text(_json.dumps(cfg), encoding="utf-8")
    binp = root / "fakebin"; binp.mkdir()
    gh = binp / "gh"
    gh.write_text(gh_body, encoding="utf-8")
    gh.chmod(0o755)
    env = dict(_os.environ)
    env["PATH"] = f"{binp}:{env['PATH']}"
    return root, v, env


def _ci_run(root, v, env, *args):
    import subprocess as _sp
    return _sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *args],
                   cwd=str(root), capture_output=True, text=True, env=env, timeout=120)


_GH_STUB_HEAD = """#!/usr/bin/env python3
import json, sys, os, pathlib
state = pathlib.Path(os.environ.get("GH_STATE", "/tmp/gh-state"))
n = int(state.read_text()) if state.exists() else 0
state.write_text(str(n + 1))
args = sys.argv[1:]
"""


def t_ci_wait():
    """[S1] ci-wait:綠/紅/no-run/逾時/聚合早退/多run輸出/總開關/fail-open。"""
    import json as _json
    import os as _os
    sha_stub = (
        "\nif args[:2] == [\"run\", \"list\"]:\n"
        "    runs = RUNS_FIRST if n == 0 else RUNS_LATER\n"
        "    print(json.dumps(runs))\n"
        "    sys.exit(0)\n"
        "if args[:2] == [\"run\", \"view\"]:\n"
        "    if \"--log-failed\" in args:\n"
        "        print(chr(10).join(['build' + chr(9) + 'test'] * 60)); sys.exit(0)\n"
        "    print(json.dumps({\"jobs\": [{\"name\": \"build\", \"steps\": ["
        "{\"name\": \"Full test suite\", \"conclusion\": \"failure\"}]}]})); sys.exit(0)\n"
        "sys.exit(0)\n"
    )
    def stub(first, later=None):
        return (_GH_STUB_HEAD + f"RUNS_FIRST = {first!r}\nRUNS_LATER = {(later if later is not None else first)!r}\n"
                .replace("'", '"') + sha_stub)

    green = [{"databaseId": 1, "attempt": 1, "status": "completed", "conclusion": "success",
              "displayTitle": "ok", "url": "u1", "workflowName": "CI"}]
    red = [{"databaseId": 2, "attempt": 1, "status": "completed", "conclusion": "failure",
            "displayTitle": "bad", "url": "u2", "workflowName": "CI"}]

    # 綠
    root, v, env = _mk_ci_env(stub(green))
    _os.environ["GH_STATE"] = str(root / "st1"); env["GH_STATE"] = str(root / "st1")
    r = _ci_run(root, v, env, "ci-wait", "--json")
    check("ci-wait 綠 rc0", r.returncode == 0, f"{r.returncode} {r.stdout[:200]} {r.stderr[:200]}")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("綠 verdict/runs 陣列", d["verdict"] == "green" and isinstance(d["runs"], list)
          and len(d["runs"]) == 1, d)
    log = v.parent / ".ci-log.jsonl"
    check("寫帳", log.exists() and "success" in log.read_text(encoding="utf-8"), "")

    # 紅 → rc1 + 失敗步驟(取自 jobs JSON) + log 尾段
    root, v, env = _mk_ci_env(stub(red))
    env["GH_STATE"] = str(root / "st2")
    r = _ci_run(root, v, env, "ci-wait", "--json")
    check("ci-wait 紅 rc1", r.returncode == 1, f"{r.returncode} {r.stdout[:200]}")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("紅 verdict + failed_step 取自 jobs", d["verdict"] == "red"
          and "Full test suite" in (d["runs"][0].get("failed_step") or ""), d)

    # 聚合:一綠一紅 → 任一紅即紅、早退
    both = green + red
    root, v, env = _mk_ci_env(stub(both))
    env["GH_STATE"] = str(root / "st3")
    r = _ci_run(root, v, env, "ci-wait", "--json")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("聚合 任一紅即紅", r.returncode == 1 and d["verdict"] == "red", f"{r.returncode} {d}")

    # no-run 快速路徑(不等滿 timeout)
    root, v, env = _mk_ci_env(stub([]))
    env["GH_STATE"] = str(root / "st4")
    import time as _t
    t0 = _t.time()
    r = _ci_run(root, v, env, "ci-wait", "--json", "--timeout", "60", "--grace", "1")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("no-run rc0 + verdict", r.returncode == 0 and d["verdict"] == "no-run", f"{r.returncode} {d}")
    check("no-run 不白等(<20s)", _t.time() - t0 < 20, f"{_t.time()-t0:.0f}s")

    # 逾時:恆 in_progress
    inprog = [{"databaseId": 3, "attempt": 1, "status": "in_progress", "conclusion": None,
               "displayTitle": "run", "url": "u3", "workflowName": "CI"}]
    root, v, env = _mk_ci_env(stub(inprog))
    env["GH_STATE"] = str(root / "st5")
    r = _ci_run(root, v, env, "ci-wait", "--json", "--timeout", "1")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("逾時 rc0 + verdict=timeout", r.returncode == 0 and d["verdict"] == "timeout", f"{r.returncode} {d}")

    # 總開關:未宣告 ci 區塊 → 完全不跑
    root, v, env = _mk_ci_env(stub(red), declare_ci=False)
    env["GH_STATE"] = str(root / "st6")
    r = _ci_run(root, v, env, "ci-wait", "--json")
    check("總開關 未宣告 rc0 不跑", r.returncode == 0, f"{r.returncode} {r.stdout[:150]}")
    check("總開關 未宣告 不寫帳", not (v.parent / ".ci-log.jsonl").exists(), "")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("總開關 verdict=disabled", d["verdict"] == "disabled", d)

    # fail-open:gh 缺席(PATH 只放 git,確保 gh 找不到而 git 還在)
    root, v, env = _mk_ci_env(stub(green))
    _onlygit = root / "onlygit"; _onlygit.mkdir()
    import shutil as _sh
    _gitbin = _sh.which("git")
    if _gitbin:
        (_onlygit / "git").symlink_to(_gitbin)
    env["PATH"] = str(_onlygit)
    r = _ci_run(root, v, env, "ci-wait", "--json")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("gh 缺席 fail-open rc0+JSON", r.returncode == 0 and d["verdict"] == "unavailable", f"{r.returncode} {d}")

    # 去重:同 run 同 attempt 同 conclusion 連跑兩次 → 帳一筆
    root, v, env = _mk_ci_env(stub(green))
    env["GH_STATE"] = str(root / "st7")
    _ci_run(root, v, env, "ci-wait")
    _ci_run(root, v, env, "ci-wait")
    lines = [l for l in (v.parent / ".ci-log.jsonl").read_text(encoding="utf-8").splitlines() if l.strip()]
    check("去重 同 run/attempt/conclusion 只一筆", len(lines) == 1, lines)

    # --repo-dir 非目錄 rc2
    r = _ci_run(root, v, env, "ci-wait", "--repo-dir", str(root / "nope"))
    check("--repo-dir 非目錄 rc2", r.returncode == 2, str(r.returncode))

    # ── 假綠:completed 但非成功的 conclusion 不得判綠(2026-07-29 外審實錘) ──
    # 舊碼是「全 completed 且無紅 → green」的二分,cancelled/action_required/stale
    # 與任何未知未來值都會被靜默判綠。計劃 [S1] 矩陣本來就寫了三分類,實作漏跟。
    for concl in ("cancelled", "action_required", "stale", "some_future_value"):
        rows = [{"databaseId": 9, "attempt": 1, "status": "completed", "conclusion": concl,
                 "displayTitle": "x", "url": "u9", "workflowName": "CI"}]
        root, v, env = _mk_ci_env(stub(rows))
        env["GH_STATE"] = str(root / f"stu-{concl}")
        r = _ci_run(root, v, env, "ci-wait", "--json", "--grace", "0")
        d = _json.loads(r.stdout.strip().splitlines()[-1])
        check(f"conclusion={concl} 不得判綠", d["verdict"] == "undetermined", d)
        check(f"conclusion={concl} rc0(不進修復路徑)", r.returncode == 0, str(r.returncode))

    # 混合:一支 success 一支 cancelled → 整體未定(不能被那支綠的蓋過去)
    mixed = green + [{"databaseId": 10, "attempt": 1, "status": "completed",
                      "conclusion": "cancelled", "displayTitle": "x", "url": "u10",
                      "workflowName": "Lint"}]
    root, v, env = _mk_ci_env(stub(mixed))
    env["GH_STATE"] = str(root / "stmix")
    r = _ci_run(root, v, env, "ci-wait", "--json", "--grace", "0")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("一綠一 cancelled → 未定不判綠", d["verdict"] == "undetermined", d)

    # ── 紅燈證據必須進**文字**輸出(不是只塞 --json) ──
    # 外審實錘:README/skill/計劃都承諾會印失敗步驟+log,實作只進 json,
    # 人跑 `lumos ci-wait` 只看得到「紅」跟一個網址,拿不到任何可修的線索。
    root, v, env = _mk_ci_env(stub(red))
    env["GH_STATE"] = str(root / "sttext")
    r = _ci_run(root, v, env, "ci-wait")          # 注意:不帶 --json
    check("紅燈文字輸出含失敗步驟", "Full test suite" in r.stdout, r.stdout[:300])
    check("紅燈文字輸出含 log 尾段", "log 尾段" in r.stdout and "build" in r.stdout,
          r.stdout[:300])
    check("紅燈文字輸出 rc1", r.returncode == 1, str(r.returncode))
    # 綠燈不該噴這些噪音
    root, v, env = _mk_ci_env(stub(green))
    env["GH_STATE"] = str(root / "sttext2")
    r = _ci_run(root, v, env, "ci-wait")
    check("綠燈文字輸出無失敗步驟噪音", "失敗步驟" not in r.stdout, r.stdout[:200])


def t_ci_status_and_gov():
    """[S3] ci-status 唯讀不打網路 + gov 第 7 源(含總開關)。"""
    import json as _json
    stub = _GH_STUB_HEAD + "sys.exit(9)\n"   # 一旦被呼叫就失敗
    root, v, env = _mk_ci_env(stub)
    log = v.parent / ".ci-log.jsonl"
    log.write_text(_json.dumps({
        "ts": "2026-07-29T10:00:00+08:00", "run_id": 7, "attempt": 1, "sha": "abc1234",
        "branch": "main", "workflow": "CI", "conclusion": "failure", "title": "bad",
        "url": "u", "failed_step": "build/test", "dedup_key": "7:1:failure"},
        ensure_ascii=False) + "\n", encoding="utf-8")
    r = _ci_run(root, v, env, "ci-status", "--json")
    check("ci-status 不呼叫 gh(rc0)", r.returncode == 0, f"{r.returncode} {r.stderr[:150]}")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("ci-status 讀帳", d.get("conclusion") == "failure" and d.get("sha") == "abc1234", d)
    r = _ci_run(root, v, env, "ci-status")
    check("ci-status 文字含檢查時刻", "2026-07-29" in r.stdout, r.stdout[:150])
    # 「檔尾最後一筆」≠「最新結論」:同 sha 多支 workflow 各一筆,綠的排在紅的後面時
    # 舊碼只讀最後一筆 → 報綠(與 SessionStart hook 早先修過的同型假綠,2026-07-29 補齊)。
    rows = [
        {"ts": "2026-07-29T11:00:00+08:00", "run_id": 8, "attempt": 1, "sha": "def5678",
         "branch": "main", "workflow": "CI", "conclusion": "failure", "title": "bad",
         "url": "u8", "failed_step": "build/test", "dedup_key": "8:1:failure"},
        {"ts": "2026-07-29T11:01:00+08:00", "run_id": 9, "attempt": 1, "sha": "def5678",
         "branch": "main", "workflow": "Lint", "conclusion": "success", "title": "ok",
         "url": "u9", "failed_step": "", "dedup_key": "9:1:success"},
    ]
    log.write_text("".join(_json.dumps(x, ensure_ascii=False) + "\n" for x in rows),
                   encoding="utf-8")
    r = _ci_run(root, v, env, "ci-status", "--json")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("ci-status 同 sha 多筆:報最壞的(紅)非檔尾那筆(綠)",
          d.get("conclusion") == "failure" and d.get("workflow") == "CI", d)
    # **反序也要成立**——只測「壞的在前」分不出「報最壞」與「報第一筆」;
    # 把紅的放檔尾再測一次,兩個方向都對才是真的取最壞(終審 reviewer 指出的空洞風險)。
    log.write_text("".join(_json.dumps(x, ensure_ascii=False) + "\n"
                           for x in [rows[1], rows[0]]), encoding="utf-8")
    r = _ci_run(root, v, env, "ci-status", "--json")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("ci-status 同 sha 多筆:紅的排檔尾也照報紅(非只取第一筆)",
          d.get("conclusion") == "failure" and d.get("workflow") == "CI", d)
    # 同 sha 全綠時照報綠
    log.write_text(_json.dumps(rows[1], ensure_ascii=False) + "\n", encoding="utf-8")
    r = _ci_run(root, v, env, "ci-status", "--json")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("ci-status 同 sha 全綠仍報綠", d.get("conclusion") == "success", d)
    # 非成功非紅(cancelled)優先於綠被報出來
    log.write_text("".join(_json.dumps(x, ensure_ascii=False) + "\n" for x in [
        {**rows[1], "run_id": 11, "conclusion": "cancelled", "workflow": "Deploy",
         "dedup_key": "11:1:cancelled"}, rows[1]]), encoding="utf-8")
    r = _ci_run(root, v, env, "ci-status", "--json")
    d = _json.loads(r.stdout.strip().splitlines()[-1])
    check("ci-status 同 sha 有 cancelled:不報綠", d.get("conclusion") == "cancelled", d)
    # 還原成單筆 failure 供後續 gov 斷言
    log.write_text(_json.dumps({
        "ts": "2026-07-29T10:00:00+08:00", "run_id": 7, "attempt": 1, "sha": "abc1234",
        "branch": "main", "workflow": "CI", "conclusion": "failure", "title": "bad",
        "url": "u", "failed_step": "build/test", "dedup_key": "7:1:failure"},
        ensure_ascii=False) + "\n", encoding="utf-8")
    # gov 第 7 源
    r = _ci_run(root, v, env, "gov")
    check("gov 見得到 CI 事件", "ci" in r.stdout and "failure" in r.stdout, r.stdout[-400:])
    # 總開關:移除 ci 區塊 → gov 不 load
    (root / ".lumos" / "config.json").write_text("{}", encoding="utf-8")
    r = _ci_run(root, v, env, "gov")
    check("gov 總開關:移除宣告後不顯示", "failure" not in r.stdout, r.stdout[-300:])


def t_ci_hooks():
    """[S2b] SessionStart hook 註冊對稱 + 提醒判法(該 sha 全部筆/總開關)。"""
    import json as _json
    import subprocess as _sp
    from pathlib import Path as _P
    root_repo = _P(__file__).resolve().parent.parent
    hook = root_repo / "scripts" / "hooks" / "claude" / "ci-status-hook.py"
    check("hook 檔存在", hook.exists(), str(hook))
    src = (root_repo / "scripts" / "lumos").read_text(encoding="utf-8")
    check("hook 進 _GLOBAL_CLAUDE_HOOKS 白名單(生命週期對稱)",
          "ci-status-hook.py" in src, "")
    merge = (root_repo / "scripts" / "merge-claude-settings.py").read_text(encoding="utf-8")
    check("hook 進 HOOK_ENTRIES(SessionStart)",
          "ci-status-hook.py" in merge and "SessionStart" in merge, "")
    check("hook 輸出契約宣告 SessionStart(非抄 PreToolUse)",
          hook.exists() and '"SessionStart"' in hook.read_text(encoding="utf-8"), "")
    # 行為:紅 → 有注入;綠 → 靜默;未宣告 → 靜默
    stub = _GH_STUB_HEAD + "sys.exit(0)\n"
    root, v, env = _mk_ci_env(stub)
    sha = _sp.run(["git", "-C", str(root), "rev-parse", "HEAD"],
                  capture_output=True, text=True).stdout.strip()
    log = v.parent / ".ci-log.jsonl"
    def wr(concl):
        log.write_text(_json.dumps({"ts": "2026-07-29T10:00:00+08:00", "run_id": 1, "attempt": 1,
                                    "sha": sha, "branch": "main", "workflow": "CI",
                                    "conclusion": concl, "title": "t", "url": "u",
                                    "failed_step": "", "dedup_key": f"1:1:{concl}"},
                                   ensure_ascii=False) + "\n", encoding="utf-8")
    def run_hook():
        payload = _json.dumps({"cwd": str(root)})
        return _sp.run([sys.executable, str(hook)], input=payload, capture_output=True,
                       text=True, cwd=str(root), env=env, timeout=60)
    wr("failure")
    r = run_hook()
    check("hook 紅 → 注入提醒", r.returncode == 0 and "CI" in r.stdout and "紅" in r.stdout,
          f"{r.returncode} {r.stdout[:200]} {r.stderr[:200]}")
    wr("success")
    r = run_hook()
    check("hook 綠 → 靜默", r.stdout.strip() == "", r.stdout[:150])
    # 多 run 分筆:紅在前綠在後,不可被「最後一筆」蓋掉
    log.write_text("\n".join([
        _json.dumps({"ts": "2026-07-29T10:00:00+08:00", "run_id": 1, "attempt": 1, "sha": sha,
                     "branch": "main", "workflow": "A", "conclusion": "failure", "title": "t",
                     "url": "u", "failed_step": "", "dedup_key": "1:1:failure"}, ensure_ascii=False),
        _json.dumps({"ts": "2026-07-29T10:01:00+08:00", "run_id": 2, "attempt": 1, "sha": sha,
                     "branch": "main", "workflow": "B", "conclusion": "success", "title": "t",
                     "url": "u", "failed_step": "", "dedup_key": "2:1:success"}, ensure_ascii=False),
    ]) + "\n", encoding="utf-8")
    r = run_hook()
    check("hook 多run:紅不被最後一筆綠蓋掉", "紅" in r.stdout, r.stdout[:200])
    # 總開關
    (root / ".lumos" / "config.json").write_text("{}", encoding="utf-8")
    r = run_hook()
    check("hook 總開關:未宣告 → 靜默", r.stdout.strip() == "", r.stdout[:150])


def _testmap_mk(td):
    """testmap 沙盒 fixture:bulk commit(>20 檔,cochange 挖掘層天然丟棄)+cochange 專用小 commit。"""
    import subprocess as _sp
    from pathlib import Path as _P
    g = lambda *a: _sp.run(["git", "-c", "user.email=t@t", "-c", "user.name=t", *a],
                           cwd=td, check=True, capture_output=True)
    g("init", "-q")
    root = _P(td)
    files = {
        "src/Foo.cs": "class Foo {}", "Foo.ts": "export const x=1",
        "Foo.spec.ts": "it('x',()=>{})",
        "src/Foo.generated.cs": "class G {}", "src/Foo.generated.Tests.cs": "class GT {}",
        "foo.py": "x=1", "foo_spec.py": "y=2", "test_foo.py": "z=3", "Foo_TESTS.py": "w=4",
        "tests/FooTests.cs": "class FT {}",
        "IMember.cs": "interface IMember {}", "Member.cs": "class Member {}",
        "Db.cs": "class Db {}",
        "tests/ScenarioTests.cs": "var m = new Mock<IMember>(); // Db",
        "Card.cs": "class Card {}", "tests/CardTests.cs": "// Card here",
        "a/helpers.py": "h=1", "b/helpers.py": "h=2", "tests/helpers.py": "h=3",
        "helper.py": "h=4", "tests/helper_.py": "h=5",   # rstrip 回歸釘:未剝離 stem 不去尾底線
        "Button.tsx": "export default 1", "__tests__/Button.tsx": "render()",
        "pkg/__init__.py": "", "tests/__init__.py": "",
        "LoadTest.cs": "class LoadTest {}", "FooTest.java": "class FooTest {}",
        "Tests.cs": "class T {}", "Latest.ts": "1", "Contest.cs": "2",
        "bar.py": "b=1", "Test_bar.py": "q=9",   # 大寫T前綴負例(獨立stem,防 APFS 大小寫不敏感撞 test_foo.py)
        "ABTest.cs": "3", "PodSpec.ts": "4", "docs/foo_test.md": "# doc",
        "會員系統.cs": "class W {}", "tests/會員系統Tests.cs": "// w",
        "HugeThing.cs": "class H {}",
    }
    for rel, body in files.items():
        fp = root / rel
        fp.parent.mkdir(parents=True, exist_ok=True)
        fp.write_text(body, encoding="utf-8")
    (root / "tests/HugeThingTests.cs").write_text("// pad\n" + "0" * 250 * 1024, encoding="utf-8")
    g("add", "-A")
    g("commit", "-q", "-m", "bulk")          # 36 檔 > max_changeset 20 → cochange 丟棄
    for i in range(3):                        # support=3 → cochange 邊
        (root / "coch.cs").write_text(f"c={i}", encoding="utf-8")
        (root / "tests/CochScenTests.cs").write_text(f"t={i}", encoding="utf-8")
        g("add", "coch.cs", "tests/CochScenTests.cs")
        g("commit", "-q", "-m", f"co{i}")
    for i in range(2):                        # support=2 → 被 testmap 門檻擋
        (root / "two.cs").write_text(f"c={i}", encoding="utf-8")
        (root / "tests/TwoScenTests.cs").write_text(f"t={i}", encoding="utf-8")
        g("add", "two.cs", "tests/TwoScenTests.cs")
        g("commit", "-q", "-m", f"two{i}")
    return g


def _testmap_run(args, cwd):
    import subprocess as _sp
    from pathlib import Path as _P
    lumos_bin = str(_P(__file__).parent / "lumos")
    return _sp.run([sys.executable, lumos_bin] + args, cwd=cwd,
                   capture_output=True, text=True, timeout=120)


def _testmap_edges(td):
    import json as _json
    from pathlib import Path as _P
    m = _json.loads((_P(td) / ".lumos" / "testmap.json").read_text(encoding="utf-8"))
    return {(e["src"], e["test"]): e for e in m["edges"]}, m


def t_testmap_build():
    """[S1] 三路訊號挖掘:naming 各型/content/cochange 門檻/合併/確定性/守衛。"""
    import json as _json
    import tempfile
    from pathlib import Path as _P
    with tempfile.TemporaryDirectory() as td:
        _testmap_mk(td)
        r = _testmap_run(["testmap", "build", "--repo", td], td)
        check("build rc0", r.returncode == 0, f"{r.returncode} {r.stderr}")
        ed, m = _testmap_edges(td)
        # 1 naming 各型
        check("naming FooTests↔src/Foo.cs", ("src/Foo.cs", "tests/FooTests.cs") in ed, list(ed)[:8])
        check("naming FooTests↔Foo.ts(同stem多src各建)", ("Foo.ts", "tests/FooTests.cs") in ed)
        check("naming Foo.spec.ts↔Foo.ts(標記段)", ("Foo.ts", "Foo.spec.ts") in ed)
        check("naming 點分basename(去尾點)", ("src/Foo.generated.cs", "src/Foo.generated.Tests.cs") in ed)
        check("naming foo_spec(_spec直剝)", ("foo.py", "foo_spec.py") in ed)
        check("naming test_前綴", ("foo.py", "test_foo.py") in ed)
        check("naming Foo_TESTS(底線不敏感可剝)", ("foo.py", "Foo_TESTS.py") in ed)
        e = ed[("src/Foo.cs", "tests/FooTests.cs")]
        check("naming conf 0.9", e["conf"] == 0.9, e)
        # 2 content
        check("content I+stem 兩邊各建", ("Member.cs", "tests/ScenarioTests.cs") in ed
              and ("IMember.cs", "tests/ScenarioTests.cs") in ed)
        check("content 短stem<4不建(Db)", ("Db.cs", "tests/ScenarioTests.cs") not in ed)
        check("content conf 0.5", ed[("Member.cs", "tests/ScenarioTests.cs")]["conf"] == 0.5)
        # 3 cochange
        check("cochange support3 建邊(封頂0.8)", ("coch.cs", "tests/CochScenTests.cs") in ed
              and ed[("coch.cs", "tests/CochScenTests.cs")]["conf"] == 0.8,
              ed.get(("coch.cs", "tests/CochScenTests.cs")))
        check("cochange support2 不建", ("two.cs", "tests/TwoScenTests.cs") not in ed)
        check("cochange 擋邊 stderr 統計", "support<3" in r.stderr, r.stderr[:200])
        # 4 合併+確定性
        e = ed[("Card.cs", "tests/CardTests.cs")]
        check("多源合併 sources 字典序", e["sources"] == ["content", "naming"] and e["conf"] == 0.9, e)
        edges1 = m["edges"]
        _testmap_run(["testmap", "build", "--repo", td], td)
        _, m2 = _testmap_edges(td)
        check("edges 兩次 build 逐字相等", edges1 == m2["edges"])
        # 8 200KB 跳 content、naming 不受影響
        check("200KB 超限跳 content(stderr記)", "HugeThingTests" in r.stderr, r.stderr[:300])
        check("200KB naming 不受影響", ("HugeThing.cs", "tests/HugeThingTests.cs") in ed)
        # 9+20+21+22 判定/建邊邊界
        check("helpers 同stem>1 不建邊", not any(k[1] == "tests/helpers.py" for k in ed))
        check("rstrip 回歸釘:helper_ 未剝離不去尾(無邊)",
              not any(k[1] == "tests/helper_.py" for k in ed),
              list(k for k in ed if "helper" in k[0]))
        check("同名唯一 __tests__/Button.tsx 建邊", ("Button.tsx", "__tests__/Button.tsx") in ed)
        check("dunder 不建邊", not any(k[1] == "tests/__init__.py" for k in ed))
        check("駝峰單數限java:FooTest.java 是測試", not any(k[0] == "FooTest.java" for k in ed))
        check("LoadTest.cs 非測試(是src)", not any(k[1] == "LoadTest.cs" for k in ed))
        check("Tests.cs stem=綴詞 不建邊", not any("Tests.cs" == k[1] and k[0] for k in ed
              if k[1] == "Tests.cs"))
        for bad in ("Latest.ts", "Contest.cs", "ABTest.cs", "PodSpec.ts"):
            check(f"{bad} 不判為測試檔", not any(k[1] == bad for k in ed))
        check("md 不入場", not any("foo_test.md" in k[0] + k[1] for k in ed))
        from importlib.machinery import SourceFileLoader as _SFL
        _lm = _SFL("lumos_tm_mod", str(_P(__file__).parent / "lumos")).load_module()
        check("Test_bar.py 大寫T前綴不判測試檔(分類直驗+無邊)",
              not _lm._testmap_is_test("Test_bar.py")
              and not any(k[1] == "Test_bar.py" for k in ed),
              list(k for k in ed if "bar" in k[0] + k[1]))
        check("CJK naming 邊", ("會員系統.cs", "tests/會員系統Tests.cs") in ed)
        # 13 mkdir 自建(.lumos 由本次 build 建立)
        check("mkdir 自建 .lumos", (_P(td) / ".lumos" / "testmap.json").is_file())
        # header
        check("map header 齊", m["version"] == 1 and len(m["built_at_commit"]) == 40
              and "T" in m["built_at"], {k: m[k] for k in ("version", "built_at")})
        # 10 json 純度
        r = _testmap_run(["testmap", "build", "--repo", td, "--json"], td)
        check("build --json 單行", r.returncode == 0 and len(r.stdout.strip().splitlines()) == 1)
        j = _json.loads(r.stdout)
        check("build --json 欄位", j["edge_count"] == len(edges1) and j["path"] == ".lumos/testmap.json"
              and len(j["built_at_commit"]) == 40, j)


def t_testmap_affected():
    """[S2] advisory 查詢:推薦/自證/去重/uncovered/刪檔語意/陳舊三訊號/json。"""
    import json as _json
    import shutil
    import subprocess as _sp
    import tempfile
    from pathlib import Path as _P
    with tempfile.TemporaryDirectory() as td:
        g = _testmap_mk(td)
        root = _P(td)
        _testmap_run(["testmap", "build", "--repo", td], td)
        # ② 陳舊:build 後 commit 候選檔
        (root / "Card.cs").write_text("class Card { int x; }", encoding="utf-8")
        (root / "coch.cs").write_text("c=9", encoding="utf-8")
        g("add", "Card.cs", "coch.cs"); g("commit", "-q", "-m", "card+coch change")
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        check("affected rc0", r.returncode == 0, f"{r.returncode} {r.stderr}")
        j = _json.loads(r.stdout)
        sug = {s["test"]: s for s in j["suggests"]}
        check("推薦 CardTests(naming)", "tests/CardTests.cs" in sug
              and sug["tests/CardTests.cs"]["conf"] == 0.9, j["suggests"])
        confs = [s["conf"] for s in j["suggests"]]
        check("推薦降序(多筆異conf真序)", len(confs) >= 2 and confs[0] == 0.9
              and confs == sorted(confs, reverse=True), confs)
        check("suggests 帶 sources/srcs", sug["tests/CardTests.cs"]["sources"] == ["content", "naming"]
              and sug["tests/CardTests.cs"]["srcs"] == ["Card.cs"], sug.get("tests/CardTests.cs"))
        check("② build後commit → stale", j["stale"] is True, j["stale"])
        check("json map 欄照實", j["map_built_at"] and j["built_at_commit"], j)
        # 重建後乾淨 → stale false;自證+去重
        _testmap_run(["testmap", "build", "--repo", td], td)
        (root / "Card.cs").write_text("class Card { int y; }", encoding="utf-8")
        (root / "tests/CardTests.cs").write_text("// Card v2", encoding="utf-8")
        g("add", "-A"); g("commit", "-q", "-m", "both")
        _testmap_run(["testmap", "build", "--repo", td], td)   # 乾淨基準
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        sug = {s["test"]: s for s in j["suggests"]}
        e = sug.get("tests/CardTests.cs")
        check("自證+邊 去重一筆 conf1.0 sources聯集", e and e["conf"] == 1.0
              and "self" in e["sources"] and "naming" in e["sources"]
              and len([s for s in j["suggests"] if s["test"] == "tests/CardTests.cs"]) == 1, e)
        check("乾淨基準 stale false", j["stale"] is False, j["stale"])
        # 文字模式
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td], td)
        check("文字 banner+建議行", r.stdout.startswith("map built at ")
              and "tests/CardTests.cs" in r.stdout and "[" in r.stdout, r.stdout[:200])
        # 刪除測試檔:map 邊與自證兩路皆不推薦;src 全邊已刪 → uncovered(孤立對 Foo.generated)
        g("rm", "-q", "tests/FooTests.cs", "src/Foo.generated.Tests.cs")
        (root / "src/Foo.cs").write_text("class Foo { int z; }", encoding="utf-8")
        (root / "src/Foo.generated.cs").write_text("class G { int z; }", encoding="utf-8")
        g("add", "src"); g("commit", "-q", "-m", "del tests + change srcs")
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("已刪測試檔不推薦", not any(s["test"] in ("tests/FooTests.cs", "src/Foo.generated.Tests.cs")
              for s in j["suggests"]), j["suggests"])
        check("src邊全指已刪測試 → uncovered", "src/Foo.generated.cs" in j["uncovered"], j["uncovered"])
        # 刪除 src 仍查邊
        _testmap_run(["testmap", "build", "--repo", td], td)
        g("rm", "-q", "Card.cs"); g("commit", "-q", "-m", "del card")
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("刪除的 src 仍查邊", any(s["test"] == "tests/CardTests.cs" for s in j["suggests"]),
              j["suggests"])
        check("②′ build後刪檔 → stale", j["stale"] is True, j["stale"])
        # 25 rm 後 mkdir 同名目錄 → 不推薦(is_file 擋)
        (root / "tests/CardTests.cs").unlink()
        (root / "tests/CardTests.cs").mkdir()
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("同名目錄不推薦", not any(s["test"] == "tests/CardTests.cs" for s in j["suggests"]),
              j["suggests"])
        shutil.rmtree(root / "tests/CardTests.cs")
        _sp.run(["git", "checkout", "-q", "--", "."], cwd=td, check=True)
        # ①非祖先 sha
        _testmap_run(["testmap", "build", "--repo", td], td)
        cur = _sp.run(["git", "rev-parse", "--abbrev-ref", "HEAD"], cwd=td,
                      capture_output=True, text=True).stdout.strip()
        g("checkout", "-q", "-b", "side")
        g("commit", "-q", "--allow-empty", "-m", "side")
        side_sha = _sp.run(["git", "rev-parse", "HEAD"], cwd=td,
                           capture_output=True, text=True).stdout.strip()
        g("checkout", "-q", cur)
        g("commit", "-q", "--allow-empty", "-m", "after")
        mp = root / ".lumos" / "testmap.json"
        mm = _json.loads(mp.read_text(encoding="utf-8"))
        mm["built_at_commit"] = side_sha
        mp.write_text(_json.dumps(mm, ensure_ascii=False), encoding="utf-8")
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("①非祖先 sha → stale", j["stale"] is True, j["stale"])
        # ③ 未提交改動/未追蹤新測試檔
        _testmap_run(["testmap", "build", "--repo", td], td)
        (root / "HugeThing.cs").write_text("class H { int q; }", encoding="utf-8")
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("③ 未提交改動 → stale", j["stale"] is True, j["stale"])
        _sp.run(["git", "checkout", "-q", "--", "."], cwd=td, check=True)
        (root / "tests/NewTests.cs").write_text("// new", encoding="utf-8")
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("③ 未追蹤新測試檔 → stale", j["stale"] is True, j["stale"])
        (root / "tests/NewTests.cs").unlink()
        # 24 CJK 存在性過濾不消失
        (root / "會員系統.cs").write_text("class W { int a; }", encoding="utf-8")
        g("add", "-A"); g("commit", "-q", "-m", "cjk change")
        _testmap_run(["testmap", "build", "--repo", td], td)
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("CJK 建議不消失", any(s["test"] == "tests/會員系統Tests.cs" for s in j["suggests"]),
              j["suggests"])
        # md 靜默
        (root / "docs/foo_test.md").write_text("# doc2", encoding="utf-8")
        g("add", "-A"); g("commit", "-q", "-m", "md only")
        _testmap_run(["testmap", "build", "--repo", td], td)
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("md 靜默(不進建議/uncovered)", j["suggests"] == [] and j["uncovered"] == [], j)
        # ⑤ map 有效僅 diff 失敗:map 欄照實
        r = _testmap_run(["testmap", "affected", "--diff", "nosuch..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        check("⑤ diff失敗 rc0+map欄照實", r.returncode == 0 and j["map_built_at"] is not None
              and j["suggests"] == [], j)
        # affected --repo 子目錄 → fail-open rc0
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD",
                          "--repo", str(root / "src"), "--json"], td)
        j = _json.loads(r.stdout)
        check("23 affected 子目錄 fail-open rc0", r.returncode == 0 and j["map_built_at"] is None,
              f"{r.returncode} {j}")


def t_testmap_rc():
    """[S1][S2] rc 矩陣+map 守衛(獨立函式防 expect_rc 首敗吞斷言)。"""
    import json as _json
    import subprocess as _sp
    import tempfile
    from pathlib import Path as _P
    EMPTY = {"map_built_at": None, "built_at_commit": None, "stale": False,
             "suggests": [], "uncovered": []}
    with tempfile.TemporaryDirectory() as td:
        r = _testmap_run(["testmap", "build", "--repo", td], td)
        check("build 非git rc2", r.returncode == 2, r.returncode)
        _sp.run(["git", "init", "-q"], cwd=td, check=True)
        r = _testmap_run(["testmap", "build", "--repo", td], td)
        check("build unborn rc2", r.returncode == 2, r.returncode)
    with tempfile.TemporaryDirectory() as td:
        g = _testmap_mk(td)
        root = _P(td)
        sub = root / "src"
        r = _testmap_run(["testmap", "build", "--repo", str(sub)], td)
        check("build 子目錄 rc2", r.returncode == 2, r.returncode)
        r = _testmap_run(["testmap", "build", "--repo", td], td)
        check("build 合法根(symlink /var 路徑)不誤擋 rc0", r.returncode == 0,
              f"{r.returncode} {r.stderr}")
        # 缺 --diff rc2;等號式 - 開頭 rc0+單行 json
        r = _testmap_run(["testmap", "affected", "--repo", td], td)
        check("affected 缺 --diff rc2", r.returncode == 2, r.returncode)
        r = _testmap_run(["testmap", "affected", "--diff=-abc", "--repo", td, "--json"], td)
        check("- 開頭 rc0 單行json", r.returncode == 0
              and _json.loads(r.stdout) == EMPTY, f"{r.returncode} {r.stdout!r}")
        mp = root / ".lumos" / "testmap.json"
        good = mp.read_text(encoding="utf-8")
        # 無 map
        mp.unlink()
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        check("無 map rc0+提示+null json", r.returncode == 0 and "build" in r.stderr
              and _json.loads(r.stdout) == EMPTY, f"{r.returncode} {r.stderr[:120]}")
        # 爛 JSON / edges 非 list / header 缺 / version≠1
        for bad, label in (("{oops", "爛JSON"),
                           ('{"version":1,"built_at_commit":"' + "a" * 40 + '","built_at":"x","edges":{}}', "edges非list"),
                           ('{"version":1,"edges":[]}', "header缺"),
                           ('{"version":2,"built_at_commit":"' + "a" * 40 + '","built_at":"x","edges":[]}', "version≠1"),
                           ('{"version":1,"built_at_commit":"XYZ!","built_at":"x","edges":[]}', "sha格式不符")):
            mp.write_text(bad, encoding="utf-8")
            r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
            check(f"壞map({label}) rc0+null", r.returncode == 0
                  and _json.loads(r.stdout)["map_built_at"] is None, f"{r.returncode} {r.stdout!r}")
        # 逐邊守衛:非dict/缺欄/conf越界/sources缺→[]
        m = _json.loads(good)
        m["edges"] = [17, {"src": "Card.cs"}, {"src": "Card.cs", "test": "tests/CardTests.cs", "conf": 999,
                                               "sources": ["naming"]},
                      {"src": "Card.cs", "test": "tests/CardTests.cs", "conf": True,
                       "sources": ["naming"]},
                      {"src": "Card.cs", "test": "tests/CardTests.cs", "conf": 0.9}]
        mp.write_text(_json.dumps(m, ensure_ascii=False), encoding="utf-8")
        (root / "Card.cs").write_text("class Card { int r; }", encoding="utf-8")
        _sp.run(["git", "-c", "user.email=t@t", "-c", "user.name=t", "commit", "-q", "-am", "c"],
                cwd=td, check=True)
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        j = _json.loads(r.stdout)
        sug = [s for s in j["suggests"] if s["test"] == "tests/CardTests.cs"]
        check("逐邊守衛:壞邊跳/好邊留 sources=[]", r.returncode == 0 and len(sug) == 1
              and sug[0]["conf"] == 0.9 and sug[0]["sources"] == [], f"{r.returncode} {j}")
        # map 為目錄 → 總兜底 rc0
        mp.unlink(); mp.mkdir()
        r = _testmap_run(["testmap", "affected", "--diff", "HEAD~1..HEAD", "--repo", td, "--json"], td)
        check("map為目錄 rc0+null", r.returncode == 0
              and _json.loads(r.stdout)["map_built_at"] is None, f"{r.returncode} {r.stdout!r}")
        mp.rmdir()
        # 寫檔失敗:.lumos 換成檔案 → build rc2+json error
        import shutil
        shutil.rmtree(root / ".lumos")
        (root / ".lumos").write_text("x", encoding="utf-8")
        r = _testmap_run(["testmap", "build", "--repo", td, "--json"], td)
        check("寫檔失敗 rc2+json error", r.returncode == 2 and "error" in _json.loads(r.stdout),
              f"{r.returncode} {r.stdout!r}")




def t_slim_scan():
    """交付文字掃描器:五種懸空引用形態都要命中,保留指令不得誤報為移除指令。"""
    import tempfile as _tf
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-slimscan-"))
    scanner = str(_P(GRAPHCTL).parent / "slim-scan.py")

    f = root / "sample.md"
    f.write_text(
        "1 前綴型: 跑 `lumos pitfalls <md>` 掃隱患\n"
        "2 裸token型: 對抗審計 loop(`canary`/`refcheck`)\n"
        "3 skill型: 走 design-loop skill 打磨\n"
        "4 span帶參型: `loop status --gate` 問收斂\n"
        "5 裸散文型: canary 驗審計員醒著\n"
        "6 乾淨行: 用 `lumos search` 找節點\n",
        encoding="utf-8")

    r = subprocess.run([sys.executable, scanner, str(f), "--json"],
                       capture_output=True, text=True)
    check("slim-scan 有命中回 rc1", r.returncode == 1, r.stderr)
    import json as _j
    d = _j.loads(r.stdout)
    forms = {c["form"] for c in d["candidates"]}
    for want in ("prefixed", "bare-token", "skill-name", "span-with-args", "prose"):
        check(f"slim-scan 命中形態 {want}", want in forms, str(sorted(forms)))
    lines = {c["line"] for c in d["candidates"]}
    check("slim-scan 不誤報保留指令 search(第6行)", 6 not in lines, str(sorted(lines)))

    # 反事實:乾淨檔必須 rc0
    g = root / "clean.md"
    g.write_text("只提保留指令: `lumos search`、`lumos doctor`、`lumos guard list`\n",
                 encoding="utf-8")
