# ══ query 結構化查詢(WHERE over 標籤家族;[[Projects/架構圖結構化查詢_計劃]]) ══

def _mk_query_vault():
    """query 測試共用小庫:標籤家族×狀態×合約×連結 交叉樣本。"""
    v = mkvault()
    write(v, "Systems/Pay.md",
          "type: system\nstatus: done\ntags:\n  - type/system\n  - status/done\n  - risk/金流\n"
          "summary: |-\n  KEY:★INVARIANT★ 金流恆等一條 [test:t_dummy]\n",
          body="# Pay\n[[Systems/Hub]]\n")
    write(v, "Systems/Prose.md",
          "type: system\nstatus: done\ntags:\n  - type/system\n  - status/done\n  - risk/金流\n",
          body="# Prose\n散文裡提到 ★INVARIANT★ 三個字但不是合約行\n")
    write(v, "Issues/OpenPay.md",
          "type: issue\nstatus: open\ntags:\n  - type/issue\n  - status/open\n  - risk/金流\n  - priority/P1\n",
          body="# OpenPay\n[[Systems/Hub]]\n")
    write(v, "Issues/DonePay.md",
          "type: issue\nstatus: done\ntags:\n  - type/issue\n  - status/done\n  - risk/金流\n",
          body="# DonePay\n")
    write(v, "Systems/Hub.md",
          "type: system\nstatus: doing\ntags:\n  - type/system\n  - status/doing\n",
          body="# Hub\n[[Issues/Free]]\n")
    write(v, "Issues/Free.md",
          "type: issue\nstatus: open\ntags:\n  - type/issue\n  - status/open\n",
          body="# Free\n")
    write(v, "Systems/DeadPay.md",
          "type: system\nstatus: superseded\ntags:\n  - type/system\n  - status/superseded\n  - risk/金流\n",
          body="# DeadPay\n")
    return v


def t_query_tag_and():
    """--tag 可重複=AND;命中列出 rel [status]。"""
    v = _mk_query_vault()
    r = run(v, "query", "--tag", "risk/金流", expect_rc=0)
    for rel in ("Systems/Pay.md", "Systems/Prose.md", "Issues/OpenPay.md", "Issues/DonePay.md"):
        check(f"單 tag 命中 {rel}", rel in r.stdout, r.stdout)
    check("單 tag 不含無標節點 Hub", "Systems/Hub.md" not in r.stdout, r.stdout)
    check("輸出帶狀態欄", "[open]" in r.stdout and "[done]" in r.stdout, r.stdout)
    r2 = run(v, "query", "--tag", "risk/金流", "--tag", "priority/P1", expect_rc=0)
    check("雙 tag=AND 只剩 OpenPay", "Issues/OpenPay.md" in r2.stdout, r2.stdout)
    check("雙 tag=AND 排除單命中 Pay", "Systems/Pay.md" not in r2.stdout, r2.stdout)


def t_query_no_tag_and_active():
    """--no-tag 排除;--active=狀態不在收案態。"""
    v = _mk_query_vault()
    r = run(v, "query", "--tag", "risk/金流", "--no-tag", "type/issue", expect_rc=0)
    check("--no-tag 排除 issue 型", "Issues/OpenPay.md" not in r.stdout and "Issues/DonePay.md" not in r.stdout, r.stdout)
    check("--no-tag 保留 system 型", "Systems/Pay.md" in r.stdout, r.stdout)
    r2 = run(v, "query", "--tag", "risk/金流", "--active", expect_rc=0)
    check("--active 保留 open", "Issues/OpenPay.md" in r2.stdout, r2.stdout)
    check("--active 排除 done", "Issues/DonePay.md" not in r2.stdout and "Systems/Pay.md" not in r2.stdout, r2.stdout)


def t_query_contract_uses_real_parser():
    """--contract 沿用 extract_contracts:只認 KEY 行標準格式,散文提及不算。"""
    v = _mk_query_vault()
    r = run(v, "query", "--tag", "risk/金流", "--contract", expect_rc=0)
    check("真合約節點 Pay 命中", "Systems/Pay.md" in r.stdout, r.stdout)
    check("★散文提及 Prose 不命中(真解析器)★", "Systems/Prose.md" not in r.stdout, r.stdout)
    check("無合約 issue 不命中", "Issues/OpenPay.md" not in r.stdout, r.stdout)


def t_query_linked_scope():
    """--linked <節點>:範圍縮到連入+連出 1-hop 鄰居(不含錨點自己)。"""
    v = _mk_query_vault()
    # Hub 的鄰居:連入 Pay/OpenPay,連出 Free。DonePay/Prose 無連結不在鄰域。
    r = run(v, "query", "--linked", "Hub", "--tag", "status/open", expect_rc=0)
    check("鄰域內 open 命中 OpenPay", "Issues/OpenPay.md" in r.stdout, r.stdout)
    check("鄰域內連出方向也算(Free)", "Issues/Free.md" in r.stdout, r.stdout)
    check("鄰域外不入列(DonePay)", "Issues/DonePay.md" not in r.stdout, r.stdout)
    check("錨點自己不入列", "Systems/Hub.md" not in r.stdout, r.stdout)
    rbad = run(v, "query", "--linked", "沒這個節點", "--tag", "risk/金流")
    check("--linked 查無節點 rc2", rbad.returncode == 2, f"rc={rbad.returncode}")


def t_query_forget_superseded():
    """預設排除 superseded(對齊 search 真遺忘鐵則);--include-superseded 逃生;隱藏數走 stderr。"""
    v = _mk_query_vault()
    r = run(v, "query", "--tag", "risk/金流", expect_rc=0)
    check("預設排除 superseded(DeadPay 不出)", "Systems/DeadPay.md" not in r.stdout, r.stdout)
    check("隱藏提示走 stderr 且計數=1", "已隱藏 1" in r.stderr, r.stderr)
    check("隱藏提示不污染 stdout", "已隱藏" not in r.stdout, r.stdout)
    r2 = run(v, "query", "--tag", "risk/金流", "--include-superseded", expect_rc=0)
    check("--include-superseded 召回 DeadPay", "Systems/DeadPay.md" in r2.stdout, r2.stdout)
    check("逃生模式不印隱藏提示", "已隱藏" not in r2.stderr, r2.stderr)


def t_query_bare_rc2():
    """無任何篩選旗標=rc2 拒絕(對齊 stale --candidate 慣例,不列全庫)。"""
    v = _mk_query_vault()
    r = run(v, "query")
    check("bare query rc2", r.returncode == 2, f"rc={r.returncode}\n{r.stderr}")
    check("錯誤訊息說明要帶條件", "--tag" in r.stderr, r.stderr)


def t_query_json():
    """--json:stdout 純 JSON,含 results(node/status/tags)與 hidden_superseded。"""
    import json as _json
    v = _mk_query_vault()
    r = run(v, "query", "--tag", "risk/金流", "--json", expect_rc=0)
    parsed = None
    try:
        parsed = _json.loads(r.stdout)
    except Exception:
        pass
    check("--json stdout 合法 JSON", parsed is not None, r.stdout)
    check("--json hidden_superseded=1", bool(parsed) and parsed.get("hidden_superseded") == 1, r.stdout)
    nodes = [x.get("node") for x in (parsed or {}).get("results", [])]
    check("--json results 含 Pay", "Systems/Pay.md" in nodes, r.stdout)
    check("--json results 不含 DeadPay", "Systems/DeadPay.md" not in nodes, r.stdout)
    st = next((x.get("status") for x in (parsed or {}).get("results", []) if x.get("node") == "Issues/OpenPay.md"), None)
    check("--json 帶 status 欄", st == "open", r.stdout)


def t_vendored_consumer_srconly_skip_regression():
    """★消費端假紅回歸釘([[Issues/vendored自測3紅_來源repo專用測試漏標skip]] 2026-08-17)★:
    Landmark 跑 lumos update 後 vendored 自測 3 紅,全是引用來源 repo 資產的測試
    漏掛(或掛太粗)「來源 repo 專用」skip 守衛:
    - t_precommit_whitelist_drift_guard 直讀 docs/lumos-toolchain-knowledge/Systems/
      pitfalls-code-loop.md,無守衛 → 消費端 FileNotFoundError;
    - t_s2_snr_synthetic 守衛掛在 `governance/eval`(目錄),但 Landmark **自己有**
      governance/eval(檢索考卷),只是沒有 canary_snr.py → 守衛放行後炸兩條
      (「snr 腳本 rc0」+ json 解析 EXCEPTION)。判準粒度必須到「真正要用的檔」。

    ★驗行為不是驗寫法★:真的搭一個消費端模擬環境(scripts/ 有、docs/ 無、
    governance/eval 目錄在但腳本不在——復刻 Landmark 的陷阱形狀),spawn 子進程
    跑這兩支,斷言 rc0 + 記成 skip + 零 ✗。把守衛拿掉/改回目錄粒度,這條會紅。"""
    import shutil as _sh
    root = Path(tempfile.mkdtemp(prefix="gctl-consumer-sim-"))
    (root / "scripts").mkdir()
    src_scripts = Path(GRAPHCTL).resolve().parent
    for f in ("lumos", "test_lumos.py"):
        _sh.copy(src_scripts / f, root / "scripts" / f)
    if (src_scripts / "hooks").is_dir():
        _sh.copytree(src_scripts / "hooks", root / "scripts" / "hooks")
    # 陷阱形狀:governance/eval 目錄存在(消費端有自己的考卷)但 canary_snr.py 不存在
    (root / "governance" / "eval").mkdir(parents=True)
    # docs/ 整個不存在(消費端 vault 是自己專案的,不叫 lumos-toolchain-knowledge)
    for kw, tname in (("precommit_whitelist_drift_guard", "t_precommit_whitelist_drift_guard"),
                      ("s2_snr_synthetic", "t_s2_snr_synthetic")):
        r = subprocess.run([sys.executable, str(root / "scripts" / "test_lumos.py"), "-k", kw],
                           capture_output=True, text=True)
        check(f"★消費端模擬:{tname} rc0(不紅)★", r.returncode == 0,
              (r.stdout + r.stderr)[-800:])
        check(f"消費端模擬:{tname} 記成 skip(不是靜默綠)", f"skip {tname}" in r.stdout,
              r.stdout[-800:])
        check(f"消費端模擬:{tname} 零 ✗", "✗" not in r.stdout, r.stdout[-800:])


def main():
    # ★把 git 的環境變數從進程 env 清掉(2026-08-01,pre-push 假紅實錘)★
    #
    # 症狀:同一個 commit、同一棵樹,直接跑 `python3 scripts/test_lumos.py` 是
    # 2039 passed / 0 failed,但由 pre-push hook 跑同一支就 3~5 條紅,而且每次
    # 紅的條數還不一樣。
    #
    # 真因:`git push` 會把 `GIT_DIR` 這類變數 export 給 hook,hook 再把整個
    # env 傳給測試進程。大量測試會自己 `git init` 一個臨時 repo 再對它下 git
    # 指令——但 `GIT_DIR` 一旦存在就★覆蓋 cwd 推斷★,那些 git 指令全部打到
    # 本 repo 而不是臨時 repo,行為當然對不上。實測把 `GIT_DIR` 指向本 repo
    # 再跑,紅的條數暴增到 65,機制確認。
    #
    # 為什麼修在這裡:替代方案是「每個建臨時 repo 的測試各自清 env」——那是
    # 幾十個呼叫點的分支簿記,天生會漏(本專案 2026-08-01 才因為同型的分支簿記
    # 漏一條被代碼審抓到)。清在唯一進入點,對現有與未來新增的測試都自動成立。
    #
    # ★為什麼這不是把閘關掉★:清掉的是「測試進程該用哪個 repo」的外部注入,
    # 不是任何斷言。清完之後 hook 跑出來的結果會跟人手跑的一致——閘從「會給
    # 假紅」變成「可信」,是加嚴不是放寬。一個持續給假紅的閘,下一次就會被人
    # 用 --no-verify waive 掉,那才是真的把閘關掉。
    import os as _os_env
    for _v in ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_PREFIX",
               "GIT_COMMON_DIR", "GIT_OBJECT_DIRECTORY", "GIT_ALTERNATE_OBJECT_DIRECTORIES"):
        _os_env.environ.pop(_v, None)

    import argparse as _ap
    _p = _ap.ArgumentParser(add_help=False)
    _p.add_argument("-k", dest="keyword", default=None, help="只跑名稱含此字串的測試")
    _args, _ = _p.parse_known_args()
    tests = [v for k, v in sorted(globals().items()) if k.startswith("t_")]
    if _args.keyword:
        tests = [t for t in tests if _args.keyword in t.__name__]
        if not tests:
            # 假綠洞修補:-k 選中 0 案例 ≠ 全綠——「跑了個寂寞」必須紅,
            # 否則消費 rc 的一方(hook/CI 等機制)會把「沒驗」當「驗過」。
            print(f"✗ -k '{_args.keyword}' 選中 0 個測試(t_ 名單無此子字串)——視為失敗", file=sys.stderr)
            return 1
    print(f"lumos 測試({len(tests)} 案例)")
    global FAIL, SKIP
    for t in tests:
        try:
            # ★單一處的自動規則,不往每支測試塞一行★:`t_slim_*` 整族驗的是「交付包」
            # (slim/ 底下的產物 + slim-gen/slim-scan),那是來源 repo 專用。用前綴在
            # 這裡一次涵蓋,★新增的 t_slim_* 自動繼承★——往 40 個函式各插一行才是
            # 會漏的分支簿記(本專案 2026-08-01 剛因同型簿記漏一條被代碼審抓到)。
            # 判定仍是狀態驅動:`slim/` 真的在(來源 repo)就照跑,零行為改變。
            if t.__name__.startswith("t_slim_"):
                _need_src("slim")
            t()
        except _SrcOnly as e:
            SKIP += 1
            print(f"  - skip {t.__name__}: {e}")
        except Exception as e:
            FAIL += 1
            print(f"  ✗ {t.__name__} EXCEPTION: {e}")
    tail = f", {SKIP} skipped(來源 repo 專用)" if SKIP else ""
    print(f"\n{'─'*40}\n{PASS} passed, {FAIL} failed{tail}")
    return 1 if FAIL else 0




# ═══ 驗證層自證三件 S1/S2 落地(2026-08-06,plan:Projects/驗證層自證三件_計劃)═══

def t_s2_loop_next_random_type_draw():
    """[S2 同場補]canary 型別派工當下隨機抽(日報 gap③:固定輪替=可猜=答案印在考卷背面)。
    ①slot 值域仍限 a-d ②同輪 slot 間不重複(width≤4;冗餘灌水 caught-rate 紀律的機械半)
    ③跨多次呼叫 slot1 至少出現 2 種值(12 抽全同的機率 (1/4)^11≈0,非 flaky)
    翻紅釘:改回 (i+n-1)%4 固定輪替 → ③翻紅(恆同值)。"""
    print("t_s2_loop_next_random_type_draw")
    import ast
    v = mkvault()
    lid = f"rndtype-{_M1U}"
    seen_slot1 = set()
    for _ in range(12):
        r = run(v, "loop", "next", lid, "--tier", "standard")
        line = next((l for l in r.stdout.splitlines() if "canary_type:" in l), "")
        d = ast.literal_eval(line.split("canary_type:", 1)[1].strip())
        vals = list(d.values())
        check("slot 值域限 a-d", all(x in ("a", "b", "c", "d") for x in vals), line) if _ == 0 else None
        if len(vals) <= 4 and len(set(vals)) != len(vals):
            check("★同輪 slot 間不重複(width≤4)★", False, line)
            return
        seen_slot1.add(d.get("slot1"))
    check("★同輪 slot 間不重複(width≤4)★", True, "")
    check("★隨機抽:12 次呼叫 slot1 非恆同值★", len(seen_slot1) >= 2, str(seen_slot1))
    # light 單席路徑:單值且在值域
    r = run(v, "loop", "next", f"rndlight-{_M1U}", "--tier", "light")
    line = next((l for l in r.stdout.splitlines() if "canary_type:" in l), "")
    val = line.split("canary_type:", 1)[1].strip()
    check("light 單席隨機抽仍在值域", val in ("a", "b", "c", "d"), line)


def t_s2_canary_stats_type_coverage():
    """[S2 回溯層]canary-stats 型別覆蓋率如實分層(plan r2 折入:數字要即時計算):
    attr(結構化 canary_type)/note(散文 type=X regex fallback)/unknown 三層分開數,
    印覆蓋率行——不硬猜、unknown 不併入任何型別。
    翻紅釘:拔 note fallback 或 unknown 計數 → 斷言翻紅。"""
    print("t_s2_canary_stats_type_coverage")
    v = mkvault()
    lid = f"cov-{_M1U}"
    run(v, "canary", "record", "caught", "--loop", lid, "--auditor", "s1", "--severity", "minor",
        "--canary-type", "b", expect_rc=0)
    run(v, "canary", "record", "caught", "--loop", lid, "--auditor", "s2", "--severity", "minor",
        "--note", "r1 type=c caught 舊慣例散文", expect_rc=0)
    run(v, "canary", "record", "missed", "--loop", lid, "--auditor", "s3", "--severity", "minor",
        "--note", "無型別線索的舊筆", expect_rc=0)
    r = run(v, "loop", "canary-stats", lid)
    check("★覆蓋率行:attr/note/unknown 三層分開數★", r.returncode == 0
          and "attr 1" in r.stdout and "note 1" in r.stdout and "unknown 1" in r.stdout, r.stdout[:600])
    check("note-derived 型別列出且標示來源", "c" in r.stdout and "note" in r.stdout, r.stdout[:600])


def t_s1_seat_check():
    """[S1 唯一新碼]seat-check 有講沒做對帳(evidra protocol_violation 語彙):
    ①unreported=dispatch materials 在報告零觸及(路徑機械比對;lens 觀測不判定)
    ②out_of_scope=finding 引句錨不進任何 material(證據 file:line 恆合法——只驗引句錨定)
    ③空 materials=vacuous 豁免 ④恆 rc0(觀測);--ledger 時越界寫 out-of-scope.jsonl
    翻紅釘:拔空 materials 豁免 → ③翻紅;拔 ledger append → ④斷言翻紅。"""
    print("t_s1_seat_check")
    import json as _j
    v = mkvault()
    d = v.parent / "seatcheck"
    d.mkdir(exist_ok=True)
    (d / "matA.md").write_text("# 材料A\n這段是被審材料的甲宣稱長這樣。\n", encoding="utf-8")
    (d / "matB.md").write_text("# 材料B\n乙檔案的內容完全不同。\n", encoding="utf-8")
    disp = d / "r1-dispatch.json"
    disp.write_text(_j.dumps({"round": "r1", "seat": "s1", "lens": "正確性",
                              "materials": [str(d / "matA.md"), str(d / "matB.md")],
                              "auditor": "sonnet"}, ensure_ascii=False), encoding="utf-8")
    # a) 觸及兩材料+引句錨定 matA → 無 unreported/out_of_scope
    rep_ok = d / "rep-ok.md"
    rep_ok.write_text("審了 matA.md 與 matB.md。\n引句:「這段是被審材料的甲宣稱長這樣」有問題。\n", encoding="utf-8")
    r = run(v, "seat-check", str(rep_ok), "--dispatch", str(disp))
    check("★乾淨報告:rc0 且無 unreported/out_of_scope★", r.returncode == 0
          and "unreported 0" in r.stdout and "out_of_scope 0" in r.stdout, r.stdout[:400])
    # b) 漏 matB → unreported 1
    rep_miss = d / "rep-miss.md"
    rep_miss.write_text("只審了 matA.md。\n引句:「這段是被審材料的甲宣稱長這樣」。\n", encoding="utf-8")
    r = run(v, "seat-check", str(rep_miss), "--dispatch", str(disp))
    check("★漏材料=unreported(仍 rc0 觀測)★", r.returncode == 0 and "unreported 1" in r.stdout,
          r.stdout[:400])
    # c) 引句錨不進任何材料 → out_of_scope + ledger append
    led = d / "out-of-scope.jsonl"
    rep_oos = d / "rep-oos.md"
    rep_oos.write_text("審了 matA.md 與 matB.md。\n引句:「這句話在兩份材料都找不到來源喔」錨定外部。\n", encoding="utf-8")
    r = run(v, "seat-check", str(rep_oos), "--dispatch", str(disp), "--ledger", str(led))
    check("★引句出界=out_of_scope(仍 rc0)★", r.returncode == 0 and "out_of_scope 1" in r.stdout,
          r.stdout[:400])
    rows = [_j.loads(l) for l in led.read_text(encoding="utf-8").splitlines() if l.strip()]
    check("★越界帳 append:{round,seat,quote,reason}★", len(rows) == 1
          and rows[0]["round"] == "r1" and rows[0]["seat"] == "s1" and rows[0]["quote"], str(rows)[:300])
    # d) 空 materials → vacuous 豁免
    disp_empty = d / "r1-dispatch-empty.json"
    disp_empty.write_text(_j.dumps({"round": "r1", "seat": "s2", "lens": "-", "materials": [],
                                    "auditor": "sonnet"}), encoding="utf-8")
    r = run(v, "seat-check", str(rep_oos), "--dispatch", str(disp_empty))
    check("★空 materials=vacuous 豁免(不判 unreported/out_of_scope)★", r.returncode == 0
          and "vacuous" in r.stdout, r.stdout[:400])
    # e) dispatch 讀不到=rc2(壞輸入 fail loud,非觀測靜默)
    r = run(v, "seat-check", str(rep_ok), "--dispatch", str(d / "不存在.json"))
    check("dispatch 缺檔=rc2", r.returncode == 2, str(r.returncode))


def t_s2_snr_synthetic():
    """[S2 前瞻層驗收②]合成樣本單測:低 SNR 題被標出(swap-candidate)、
    高 SNR 題 keep、樣本不足(同席重跑<3)與分母=0 判 no-verdict 非高訊號。
    翻紅釘:把分母=0 判成 keep/高訊號 → 斷言翻紅。"""
    print("t_s2_snr_synthetic")
    import json as _j, subprocess as _sp
    repo = Path(GRAPHCTL).resolve().parent.parent
    snr = repo / "governance" / "eval" / "canary_snr.py"
    # ★判準粒度必須到「真正要用的檔」★:消費端(Landmark)自己有 governance/eval
    # (檢索考卷),目錄粒度守衛會放行、然後 canary_snr.py 不存在炸兩條
    # ([[Issues/vendored自測3紅_來源repo專用測試漏標skip]] 2026-08-17 實錘)
    _need_src("governance/eval/canary_snr.py")
    rows = []
    # P-low:跨席分不開(全席各半 caught)且席內重跑亂跳 → 低 SNR → swap-candidate
    for seat in ("s1", "s2", "s3"):
        for i in range(4):
            rows.append({"plant": "P-low", "seat": seat, "run_id": f"r{i}", "caught": i % 2 == 0})
    # P-high:席間分得開(s1 7/8 中、s2 1/8 中)且席內雜訊相對小 → SNR≥1 → keep
    # (注意不能用「全中 vs 全漏」:席內變異=0 會正確落入分母=0 不裁決——那是 P-zero 的戲份)
    for i in range(8):
        rows.append({"plant": "P-high", "seat": "s1", "run_id": f"r{i}", "caught": i != 0})
        rows.append({"plant": "P-high", "seat": "s2", "run_id": f"r{i}", "caught": i == 0})
    # P-thin:每席只跑 1 次 → 樣本不足 → no-verdict
    rows.append({"plant": "P-thin", "seat": "s1", "run_id": "r0", "caught": True})
    rows.append({"plant": "P-thin", "seat": "s2", "run_id": "r0", "caught": False})
    # P-zero:席內重跑全同(分母=0)→ no-verdict(非高訊號)
    for i in range(3):
        rows.append({"plant": "P-zero", "seat": "s1", "run_id": f"r{i}", "caught": True})
        rows.append({"plant": "P-zero", "seat": "s2", "run_id": f"r{i}", "caught": False})
    import tempfile as _tf
    with _tf.NamedTemporaryFile("w", suffix=".json", delete=False, encoding="utf-8") as f:
        _j.dump(rows, f)
        pth = f.name
    r = _sp.run([sys.executable, str(snr), "--matrix", pth, "--json"], capture_output=True, text=True)
    check("snr 腳本 rc0", r.returncode == 0, r.stderr[:300])
    out = {row["plant"]: row for row in _j.loads(r.stdout)}
    check("★低 SNR 題標 swap-candidate★", out["P-low"]["verdict"] == "swap-candidate", str(out.get("P-low")))
    check("★高 SNR 題 keep★", out["P-high"]["verdict"] == "keep", str(out.get("P-high")))
    check("★重跑<3=no-verdict★", out["P-thin"]["verdict"] == "no-verdict", str(out.get("P-thin")))
    check("★分母=0=no-verdict 非高訊號★", out["P-zero"]["verdict"] == "no-verdict", str(out.get("P-zero")))




