def _hk_fixture(tmp_prefix="gctl-hk-"):
    """fixture repo:vault+code 檔;A 節點引 scripts/tool_x.sh(direct),B 節點 wikilink A(hop1)
    且 body 詞彙可被 query 命中(把 max_free 撐高→閾殺 direct)。回傳 (repo, vault)。"""
    import shutil
    repo = Path(tempfile.mkdtemp(prefix=tmp_prefix))
    (repo / "scripts").mkdir()
    (repo / "scripts" / "tool_x.sh").write_text("#!/bin/sh\n", encoding="utf-8")
    (repo / "scripts" / "tool_y.sh").write_text("#!/bin/sh\n", encoding="utf-8")
    vault = repo / "docs" / "hk-knowledge"
    for sub in ("Systems", "Verification", "Projects", "MOC", "Issues"):
        (vault / sub).mkdir(parents=True, exist_ok=True)
    (vault / "Systems" / "A直連.md").write_text(
        "---\ntype: system\nstatus: doing\ncreated: 2026-08-07\nupdated: 2026-08-07\n"
        "tags:\n  - type/system\nrelated:\n  - \"[[Systems/B鄰居]]\"\n"
        "summary: |-\n  KEY:x\n---\n# A直連\n管 `scripts/tool_x.sh` 的節點,詞彙刻意不含查詢字。\n",
        encoding="utf-8")
    (vault / "Systems" / "B鄰居.md").write_text(
        "---\ntype: system\nstatus: doing\ncreated: 2026-08-07\nupdated: 2026-08-07\n"
        "tags:\n  - type/system\nrelated:\n  - \"[[Systems/A直連]]\"\n"
        "summary: |-\n  KEY:x\n---\n# B鄰居\n"
        "zebra quartz 檢索 zebra quartz 詞彙 zebra quartz 高分 zebra quartz。\n"
        "quokka wombat quokka wombat quokka wombat(第二組特徵詞,供水位測試撐閾)。\n",
        encoding="utf-8")
    return repo, vault


def _hk_impact(repo, file, query, extra_env=None, top="8"):
    import subprocess, json as _j, os
    env = dict(os.environ)
    if extra_env:
        env.update(extra_env)
    r = subprocess.run([sys.executable, GRAPHCTL, "impact", "--file", file,
                        "--repo", str(repo), "--ranked", "--top", top,
                        "--stdin-payload", "--json"],
                       capture_output=True, text=True, env=env,
                       input=_j.dumps({"query": query, "prospective": {}}))
    return _j.loads(r.stdout.strip().splitlines()[-1])


def t_impact_direct_rescue():
    """[R1 直連保底席]①零 direct 觸發(rescued:true/pinned:false/meta.rescued)②knob=0 不觸發
    ③direct 存活不觸發 ④多 direct 全滅→觸發(r2 折入案例)+缺口/N 上限+tie-break。
    ★QGATE_MINLEN=0 為前瞻防護:現行預設 1(僅 shebang)下本測 query 不會被閘,旋鈕確保未來網格調高 MINLEN 時救援語意測試仍與閘正交(code-標註刷新後單審 minor 修正敘述)★。翻紅釘:拔 rescue 邏輯 → ①④翻紅;rescued 誤標 pinned → ①翻紅。"""
    print("t_impact_direct_rescue")
    repo, vault = _hk_fixture()
    q = "zebra quartz 檢索"
    # ① N=1:direct 被閾殺(L=0),B 鄰居 L 高撐閾 → rescue
    d = _hk_impact(repo, "scripts/tool_x.sh", q, {"LUMOS_IMPACT_QGATE_MINLEN": "0", "LUMOS_IMPACT_RESCUE_N": "1"})
    res = d["results"]
    resc = [x for x in res if x.get("rescued")]
    check("★零 direct 場景觸發保底:恰 1 筆 rescued★", len(resc) == 1, str(res)[:300])
    check("★rescued 為 direct 且 pinned:false(第三桶不污染固定席)★",
          resc and resc[0]["kind"] == "direct" and resc[0]["pinned"] is False, str(resc)[:200])
    check("★meta.rescued 計數鍵★", d["meta"].get("rescued") == 1, str(d["meta"]))
    # ② knob=0(A 臂)不觸發
    d0 = _hk_impact(repo, "scripts/tool_x.sh", q, {"LUMOS_IMPACT_QGATE_MINLEN": "0", "LUMOS_IMPACT_RESCUE_N": "0"})
    check("★knob=0 不觸發(A 臂=現行行為)★",
          not any(x.get("rescued") for x in d0["results"]), str(d0["results"])[:200])
    # ③ query 命中 direct 本身 → direct 存活 → 不觸發
    d3 = _hk_impact(repo, "scripts/tool_x.sh", "管 節點 詞彙", {"LUMOS_IMPACT_QGATE_MINLEN": "0", "LUMOS_IMPACT_RESCUE_N": "1"})
    free_direct = [x for x in d3["results"] if x["kind"] == "direct" and not x.get("rescued")]
    if free_direct:
        check("direct 存活時不觸發", not any(x.get("rescued") for x in d3["results"]),
              str(d3["results"])[:200])
    # ④ 多 direct 全滅:再加一個引同檔的節點,兩 direct 皆 L=0 → 觸發且 N=1 只救 1(tie-break 字典序)
    (vault / "Systems" / "C直連.md").write_text(
        "---\ntype: system\nstatus: doing\ncreated: 2026-08-07\nupdated: 2026-08-07\n"
        "tags:\n  - type/system\nsummary: |-\n  KEY:x\n---\n# C直連\n也管 `scripts/tool_x.sh`,同樣不含查詢字。\n",
        encoding="utf-8")
    d4 = _hk_impact(repo, "scripts/tool_x.sh", q, {"LUMOS_IMPACT_QGATE_MINLEN": "0", "LUMOS_IMPACT_RESCUE_N": "1"})
    resc4 = [x for x in d4["results"] if x.get("rescued")]
    check("★多 direct 全滅→照樣觸發(r2 折入:非「多 direct 必不觸發」)★",
          len(resc4) == 1, str(resc4)[:200])
    check("tie-break 同分取字典序(A直連 先於 C直連)",
          resc4 and "A直連" in resc4[0]["node"], str(resc4)[:200])
    d5 = _hk_impact(repo, "scripts/tool_x.sh", q, {"LUMOS_IMPACT_QGATE_MINLEN": "0", "LUMOS_IMPACT_RESCUE_N": "2"})
    check("N=2 且缺口 2 → 救 2", sum(1 for x in d5["results"] if x.get("rescued")) == 2,
          str(d5["results"])[:250])


def t_impact_basename_match():
    """[R2 裸檔名容錯]git fixture:①唯一裸檔名+knob on → direct 命中 hit=basename-match
    ②knob off → 不命中 ③重名 basename → 跳過 ④完整路徑優先於裸檔名 ⑤非 git repo → degrade。
    翻紅釘:拔 basename 抽取 → ①翻紅;拔唯一性檢查 → ③翻紅。"""
    print("t_impact_basename_match")
    import subprocess, os
    repo, vault = _hk_fixture(tmp_prefix="gctl-hkbn-")
    # 節點 D:裸檔名引用 tool_x.sh(無 /)
    (vault / "Systems" / "D裸名.md").write_text(
        "---\ntype: system\nstatus: doing\ncreated: 2026-08-07\nupdated: 2026-08-07\n"
        "tags:\n  - type/system\nsummary: |-\n  KEY:x\n---\n# D裸名\n入口在 `tool_x.sh`(裸檔名慣例)。\n",
        encoding="utf-8")
    for cmd in (["git", "init", "-q"], ["git", "add", "-A"],
                ["git", "-c", "user.email=t@t", "-c", "user.name=t", "commit", "-qm", "x"]):
        subprocess.run(cmd, cwd=str(repo), capture_output=True)
    on = {"LUMOS_IMPACT_BASENAME_MATCH": "1", "LUMOS_IMPACT_RESCUE_N": "0"}
    d = _hk_impact(repo, "scripts/tool_x.sh", "", on)
    dnodes = {x["node"]: x for x in d["results"] if x["kind"] == "direct"}
    check("★唯一裸檔名命中:D裸名 進 direct★", any("D裸名" in n for n in dnodes), str(dnodes)[:300])
    dd = next((x for n, x in dnodes.items() if "D裸名" in n), None)
    check("★hit=basename-match(provenance 穿透 ranked)★",
          dd is not None and dd.get("hit") == "basename-match", str(dd))
    da = next((x for n, x in dnodes.items() if "A直連" in n), None)
    check("★完整路徑優先:A直連 hit=body-inline-code★",
          da is not None and da.get("hit") == "body-inline-code", str(da))
    # ② knob off
    doff = _hk_impact(repo, "scripts/tool_x.sh", "", {"LUMOS_IMPACT_BASENAME_MATCH": "0"})
    check("★knob off 裸檔名不命中★",
          not any("D裸名" in x["node"] for x in doff["results"]), str(doff["results"])[:200])
    # ③ 重名:加同名檔 → 歧義跳過
    (repo / "tool_x.sh").write_text("dup", encoding="utf-8")
    subprocess.run(["git", "add", "-A"], cwd=str(repo), capture_output=True)
    subprocess.run(["git", "-c", "user.email=t@t", "-c", "user.name=t", "commit", "-qm", "dup"],
                   cwd=str(repo), capture_output=True)
    ddup = _hk_impact(repo, "scripts/tool_x.sh", "", on)
    check("★重名 basename=歧義跳過不猜★",
          not any("D裸名" in x["node"] for x in ddup["results"]), str(ddup["results"])[:200])
    # ⑤ 非 git repo → degrade 不炸、無 basename 命中
    repo2, vault2 = _hk_fixture(tmp_prefix="gctl-hknogit-")
    (vault2 / "Systems" / "D裸名.md").write_text(
        "---\ntype: system\nstatus: doing\ncreated: 2026-08-07\nupdated: 2026-08-07\n"
        "tags:\n  - type/system\nsummary: |-\n  KEY:x\n---\n# D裸名\n入口在 `tool_x.sh`。\n",
        encoding="utf-8")
    dng = _hk_impact(repo2, "scripts/tool_x.sh", "", on)
    check("★git 缺席 degrade:不炸且裸檔名不命中★",
          not any("D裸名" in x["node"] for x in dng["results"]), str(dng["results"])[:200])




def t_s2_waterline_rescue():
    """[連結缺失補全 S2]水位謂詞:free direct<N 補至水位(need=N-count),非零 direct 特例。
    ①1 direct 存活+N=2 → 補恰 1 席 ②1 direct 存活+N=1 → 不觸發(向下相容=舊零 direct 語意)
    ③pinned direct 不計入 free 計數(合約 direct 固定席時仍可觸發)④dropped<need 補盡即止。
    ★QGATE_MINLEN=0 為前瞻防護:現行預設 1(僅 shebang)下本測 query 不會被閘,旋鈕確保未來網格調高 MINLEN 時救援語意測試仍與閘正交(code-標註刷新後單審 minor 修正敘述)★。翻紅釘:補入數退回 dropped[:N] → ①翻紅(會補 2)。"""
    print("t_s2_waterline_rescue")
    repo, vault = _hk_fixture(tmp_prefix="gctl-wl-")
    # D直連2:詞彙可被特定 query 命中(存活),A/C 直連死
    (vault / "Systems" / "D直連2.md").write_text(
        "---\ntype: system\nstatus: doing\ncreated: 2026-08-07\nupdated: 2026-08-07\n"
        "tags:\n  - type/system\nsummary: |-\n  KEY:x\n---\n# D直連2\n"
        "也引 `scripts/tool_x.sh`;特徵詞 quokka wombat quokka wombat quokka。\n", encoding="utf-8")
    (vault / "Systems" / "C直連.md").write_text(
        "---\ntype: system\nstatus: doing\ncreated: 2026-08-07\nupdated: 2026-08-07\n"
        "tags:\n  - type/system\nsummary: |-\n  KEY:x\n---\n# C直連\n也管 `scripts/tool_x.sh`,無特徵詞。\n",
        encoding="utf-8")
    q = "quokka wombat"   # 勿含「特徵」——C 節點寫「無特徵詞」會被誤命中(首版夾具瑕疵)
    # ① N=2:D 存活(free_direct=1)→ need=1,救 1(A/C 分數同 → 字典序 A)
    d = _hk_impact(repo, "scripts/tool_x.sh", q, {"LUMOS_IMPACT_QGATE_MINLEN": "0", "LUMOS_IMPACT_RESCUE_N": "2"})
    resc = [x for x in d["results"] if x.get("rescued")]
    check("★1 direct 存活+N=2 → 補恰 1 席(need=N-count)★", len(resc) == 1, str(d["results"])[:300])
    # ② N=1:1≥1 不觸發
    d1 = _hk_impact(repo, "scripts/tool_x.sh", q, {"LUMOS_IMPACT_QGATE_MINLEN": "0", "LUMOS_IMPACT_RESCUE_N": "1"})
    check("★1 direct 存活+N=1 → 不觸發(向下相容)★",
          not any(x.get("rescued") for x in d1["results"]), str(d1["results"])[:200])
    # ③ pinned direct 不計入:給 D直連2 掛合約 → 變 pinned;free_direct=0 → N=1 觸發
    p3 = vault / "Systems" / "D直連2.md"
    p3.write_text(p3.read_text(encoding="utf-8").replace(
        "KEY:x", "KEY:★INVARIANT★ 假合約 [test:t_x]"), encoding="utf-8")
    d3 = _hk_impact(repo, "scripts/tool_x.sh", q, {"LUMOS_IMPACT_QGATE_MINLEN": "0", "LUMOS_IMPACT_RESCUE_N": "1"})
    check("★pinned direct 不計入 free 計數 → N=1 仍觸發★",
          sum(1 for x in d3["results"] if x.get("rescued")) == 1, str(d3["results"])[:300])
    # ④ dropped<need:N=9 → 只補得出 dropped 數
    d4 = _hk_impact(repo, "scripts/tool_x.sh", q, {"LUMOS_IMPACT_QGATE_MINLEN": "0", "LUMOS_IMPACT_RESCUE_N": "9"})
    n_dropped = sum(1 for x in d4["results"] if x.get("rescued"))
    check("dropped<need 補盡即止(不虛報)", 1 <= n_dropped <= 3, str(n_dropped))


def t_link_candidates():
    """[連結缺失補全 S1]候選生成:D1 純文字(完整路徑/檔名/複合詞 stem)、D2 鄰居家族
    (四邊型單跳+剝後綴 LCS≥4 CJK / plan_refs 單跳)、已 direct 去重、CLI 互斥、schema 封閉。
    翻紅釘:拔剝後綴 → 泛用尾綴誤報斷言翻紅;拔去重 → 已 direct 斷言翻紅。"""
    print("t_link_candidates")
    import subprocess, json as _j, os
    repo, vault = _hk_fixture(tmp_prefix="gctl-lc-")
    # E:純文字完整路徑(無反引號)→ D1
    (vault / "Systems" / "E純文字.md").write_text(
        "---\ntype: system\nstatus: doing\ncreated: 2026-08-07\nupdated: 2026-08-07\n"
        "tags:\n  - type/system\nsummary: |-\n  KEY:x\n---\n# E純文字\n"
        "本節掌管 scripts/tool_x.sh 的流程(刻意無反引號)。\n", encoding="utf-8")
    # d 家族:工具X掃描_實作計畫(direct)+ 工具X掃描_計劃(related 鄰居,剝後綴 LCS=工具X掃描)
    (vault / "Projects" / "工具X掃描_實作計畫.md").write_text(
        "---\ntype: project\nstatus: done\ncreated: 2026-08-07\nupdated: 2026-08-07\n"
        "tags:\n  - type/project\nrelated:\n  - \"[[Projects/工具X掃描_計劃]]\"\n"
        "  - \"[[Projects/無關主題_計劃]]\"\n---\n# 工具X掃描_實作計畫\n落點 `scripts/tool_x.sh`。\n",
        encoding="utf-8")
    (vault / "Projects" / "工具X掃描_計劃.md").write_text(
        "---\ntype: project\nstatus: done\ncreated: 2026-08-07\nupdated: 2026-08-07\n"
        "tags:\n  - type/project\n---\n# 工具X掃描_計劃\n設計文,零 code 引用。\n", encoding="utf-8")
    (vault / "Projects" / "無關主題_計劃.md").write_text(
        "---\ntype: project\nstatus: done\ncreated: 2026-08-07\nupdated: 2026-08-07\n"
        "tags:\n  - type/project\n---\n# 無關主題_計劃\n只共享 _計劃 泛用尾綴。\n", encoding="utf-8")
    # V:僅 plan_refs 單跳連 d → D2(b)
    (vault / "Verification" / "V驗證.md").write_text(
        "---\ntype: verification\nstatus: pass\ndate: 2026-08-07\n"
        "plan_refs:\n  - \"[[Projects/工具X掃描_實作計畫]]\"\n"
        "tags:\n  - type/verification\n---\n# V驗證\n零 code 引用。\n", encoding="utf-8")
    def run_lc(*args):
        env = dict(os.environ)
        return subprocess.run([sys.executable, GRAPHCTL, "link-candidates", *args,
                               "--repo", str(repo), "--json"],
                              capture_output=True, text=True, env=env)
    r = run_lc("scripts/tool_x.sh")
    check("rc0", r.returncode == 0, r.stderr[:200])
    d = _j.loads(r.stdout.strip().splitlines()[-1])
    cand = {c["node"]: c for c in d["candidates"]}
    check("★D1 純文字完整路徑命中★", any("E純文字" in n for n in cand), str(cand)[:300])
    e = next((c for n, c in cand.items() if "E純文字" in n), None)
    check("D1 signal+evidence 欄位", e and e["signal"] in ("plain-text", "both") and e["evidence"], str(e))
    check("★D2 剝後綴 LCS 家族命中(工具X掃描_計劃)★", any("工具X掃描_計劃" in n for n in cand), str(cand)[:300])
    check("★泛用尾綴不誤報(無關主題_計劃 不在)★", not any("無關主題" in n for n in cand), str(cand)[:300])
    check("★D2(b) plan_refs 單跳命中(V驗證)★", any("V驗證" in n for n in cand), str(cand)[:300])
    check("★已 direct 去重(A直連/工具X掃描_實作計畫 不在)★",
          not any("A直連" in n or "實作計畫" in n for n in cand), str(cand)[:300])
    # CLI 互斥
    r2 = run_lc()
    check("無參數=rc2", r2.returncode == 2, str(r2.returncode))




def t_mutate_diff():
    """[驗證層去模型化 S4]diff 變異測試 v1:①ast 算子生成+殺/活判定 ②baseline 紅=rc2
    ③cap 決定性(同 range 兩跑同結果) ④no-test-selected 分桶 ⑤--json schema ⑥互斥 rc 合約。
    翻紅釘:拔 baseline 前置 → ②翻紅;拔 sha256 排序 → ③翻紅。"""
    print("t_mutate_diff")
    import subprocess, json as _j, os
    repo = Path(tempfile.mkdtemp(prefix="gctl-mut-"))
    def git(*a):
        subprocess.run(["git", "-c", "user.email=t@t", "-c", "user.name=t", *a],
                       cwd=str(repo), capture_output=True)
    git("init", "-q")
    src = repo / "src_mod.py"
    tst = repo / "test_src_mod.py"
    # src:兩個可變異點——check_limit 的 >=(測試蓋到,變異必死)、silent_flag 的 ==(測試沒蓋,變異活)
    SRC = ("def check_limit(x):\n"
           "    return x >= 10\n"
           "\n"
           "def silent_flag(y):\n"
           "    return y == 3\n")
    TST = ("import sys\nimport src_mod\n"
           "assert src_mod.check_limit(10) is True\n"
           "assert src_mod.check_limit(9) is False\n"
           "print('ok')\n")
    # 3 個共改 commit 餵 testmap 挖掘(support>=3)
    for i in range(3):
        src.write_text(SRC + f"# rev{i}\n", encoding="utf-8")
        tst.write_text(TST + f"# rev{i}\n", encoding="utf-8")
        git("add", "-A"); git("commit", "-qm", f"c{i}")
    # 最後一筆:改 src 的兩行(diff 目標)
    src.write_text(SRC.replace("x >= 10", "x >= 10  # touched").replace("y == 3", "y == 3  # touched"),
                   encoding="utf-8")
    tst.write_text(TST, encoding="utf-8")
    git("add", "-A"); git("commit", "-qm", "change")
    r = subprocess.run([sys.executable, GRAPHCTL, "testmap", "build", "--repo", str(repo)],
                       capture_output=True, text=True)
    def mut(*args):
        return subprocess.run([sys.executable, GRAPHCTL, "mutate", "--repo", str(repo), *args],
                              capture_output=True, text=True)
    r1 = mut("--diff", "HEAD~1..HEAD", "--json")
    check("mutate rc0(觀測有效)", r1.returncode == 0, r1.stderr[:300])
    d = _j.loads(r1.stdout.strip().splitlines()[-1])
    check("★schema:mutants/buckets/kill_rate 鍵齊★",
          all(k in d for k in ("mutants", "buckets", "kill_rate")), str(d)[:200])
    kinds = {m["bucket"] for m in d["mutants"]}
    check("★蓋到的變異被殺(killed 桶非空)★", "killed" in kinds, str(d["mutants"])[:400])
    check("★沒蓋到的變異存活(survived 桶非空=測試網的洞)★", "survived" in kinds,
          str(d["mutants"])[:400])
    surv = [m for m in d["mutants"] if m["bucket"] == "survived"]
    check("活口帶 file:line+變異描述", surv and all(m.get("line") and m.get("op") for m in surv),
          str(surv)[:200])
    # ③ cap 決定性:兩跑結果一致
    r2 = mut("--diff", "HEAD~1..HEAD", "--json")
    d2 = _j.loads(r2.stdout.strip().splitlines()[-1])
    check("★決定性:同 range 兩跑 mutants 序列一致★",
          [(m["line"], m["op"], m["bucket"]) for m in d["mutants"]] ==
          [(m["line"], m["op"], m["bucket"]) for m in d2["mutants"]], "兩跑不一致")
    # ② baseline 紅 → rc2 fail loud
    tst.write_text(TST + "assert False  # 故意紅\n", encoding="utf-8")
    git("add", "-A"); git("commit", "-qm", "red")
    r3 = mut("--diff", "HEAD~2..HEAD~1", "--json")
    check("★baseline 非綠=rc2 fail loud(殺率不可被紅測試灌水)★", r3.returncode == 2,
          f"rc={r3.returncode} {r3.stderr[:200]}")
    git("revert", "-n", "HEAD"); git("commit", "-qm", "unred")
    # ④ no-test-selected:動一個沒有 testmap 邊的新檔
    orphan = repo / "orphan_mod.py"
    orphan.write_text("def lonely(z):\n    return z > 5\n", encoding="utf-8")
    git("add", "-A"); git("commit", "-qm", "orphan")
    r4 = mut("--diff", "HEAD~1..HEAD", "--json")
    d4 = _j.loads(r4.stdout.strip().splitlines()[-1])
    check("★無測試邊的檔=no-test-selected 桶(不混報測試洞)★",
          any(m["bucket"] == "no-test-selected" for m in d4["mutants"]), str(d4)[:300])
    # ⑥ 互斥 rc 合約
    r5 = mut()
    check("無 --diff=rc2", r5.returncode == 2, str(r5.returncode))




# ── 派工編制資料化(Projects/派工編制資料化_計劃):_TIER_ROSTER+loop next roster+status --roster ──
def _mk_roster_fixture():
    """vault+repo+design standard panel 帳(r1 兩席)+dispatch 目錄。"""
    import json as _j
    vault = mkvault()
    repo = Path(tempfile.mkdtemp(prefix="gctl-roster-repo-"))
    spec = repo / "spec.md"
    spec.write_text("# s\n", encoding="utf-8")
    def rec(loop, rid, auditor, tier="standard", sev="minor"):
        row = {"ts": "2026-08-18T10:00:00+08:00", "kind": "none", "loop": loop,
               "round": rid, "severity": sev, "auditor": auditor, "tier": tier, "note": rid}
        with open(vault.parent / ".canary-log.jsonl", "a", encoding="utf-8") as f:
            f.write(_j.dumps(row, ensure_ascii=False) + "\n")
    def disp(loop, name, obj):
        d = repo / "governance" / "review-reports" / loop
        d.mkdir(parents=True, exist_ok=True)
        (d / name).write_text(_j.dumps(obj, ensure_ascii=False), encoding="utf-8")
    return vault, repo, spec, rec, disp


def t_tier_roster_table():
    """S1 防雙真相釘:panel 條目佔 W 席數==width、single=1;requirement 恆裸枚舉;無 code/standard。"""
    m = _load_lumos_module()
    tbl = m._TIER_ROSTER
    check("roster: 表存在且含五組合", set(tbl.keys()) ==
          {("design", "light"), ("design", "standard"), ("design", "high"), ("code", "high"),
           ("code", "standard")},
          str(sorted(tbl.keys())))
    check("roster: code/standard 補列(循序 tier 錨定案 supersede v1 範圍釘)",
          tbl.get(("code", "standard"), {}).get("mode") == "sequential", str(tbl.get(("code", "standard"))))
    allowed_req = {"required", "required-fail-closed", "note-if-absent", "conditional"}
    for (kind, tier), entry in tbl.items():
        seats = entry["seats"]
        w = sum(1 for s in seats if s["occupies_w"])
        if entry["mode"] == "panel":
            check(f"roster: {kind}/{tier} 佔W=={m._TIER_PARAMS[tier][0]}",
                  w == m._TIER_PARAMS[tier][0], f"got {w}")
        else:
            check(f"roster: {kind}/{tier} single 佔W=1", w == 1, f"got {w}")
        check(f"roster: {kind}/{tier} requirement 全裸枚舉",
              all(s["requirement"] in allowed_req for s in seats),
              str([s["requirement"] for s in seats]))
    ch = tbl[("code", "high")]["seats"]
    check("roster: code/high 外家 finder 佔W+required-fail-closed",
          any(s["family"] == "external" and s["occupies_w"] and s["requirement"] == "required-fail-closed" for s in ch), str(ch))
    check("roster: code/high spec-conformance conditional 不佔W",
          any(s["requirement"] == "conditional" and not s["occupies_w"] for s in ch), str(ch))


